def _normalise_menu_text(value):
    return " ".join(str(value or "").strip().lower().split())


def set_customer_menu_state(customer_number, menu_name):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO customer_menu_state (customer_number, menu_name, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (customer_number)
                DO UPDATE SET menu_name=EXCLUDED.menu_name, updated_at=NOW()
                """,
                (customer_number, str(menu_name or "MAIN")[:30]),
            )
        conn.commit()


def get_customer_menu_state(customer_number):
    """Return only a recent menu state so an old menu cannot hijack later numeric replies."""
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT menu_name
                FROM customer_menu_state
                WHERE customer_number=%s
                  AND updated_at > NOW() - INTERVAL '2 hours'
                """,
                (customer_number,),
            )
            row = cur.fetchone()
    return row[0] if row else None


def clear_customer_menu_state(customer_number):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "DELETE FROM customer_menu_state WHERE customer_number=%s",
                (customer_number,),
            )
        conn.commit()


def is_main_service_menu_request(customer_message):
    """Recognise explicit requests to show the IBROWS main/service menu.

    This check intentionally runs before any active Career Assist/application-pack
    routing so a customer can always escape a stale workflow and ask for the main
    menu. Keep it conservative: a mere mention of a service is not enough.
    """
    raw = str(customer_message or "").strip().lower()
    text = _normalise_menu_text(raw)
    # A punctuation-free form makes natural requests such as
    # "Please show me the main IBROWS service menu." deterministic.
    cleaned = re.sub(r"[^a-z0-9&+]+", " ", text)
    cleaned = " ".join(cleaned.split())

    exact = {
        "menu", "main menu", "services", "service", "service menu",
        "show services", "show me services", "list services", "service list",
        "what do you offer", "what services do you offer", "what do you do",
        "your services", "ibrows services",
    }
    if text in exact or cleaned in exact:
        return True

    # Natural-language requests that clearly ask to display/open the menu.
    if "menu" in cleaned:
        request_words = {"show", "send", "give", "display", "open", "see", "view", "list"}
        menu_context = {"main", "service", "services", "ibrows"}
        words = set(cleaned.split())
        if (words & request_words) and (words & menu_context):
            return True

        # Polite phrasings can omit an explicit command after "please".
        if "please" in words and ("service" in words or "services" in words or "main" in words):
            return True

    return False


