@app.route("/admin/leads/<int:lead_id>/send-document/<doc_type>", methods=["POST"])
@admin_required
def admin_business_document_send(lead_id, doc_type):
    validate_csrf()
    doc_type = str(doc_type or "").strip().lower()
    if doc_type not in BUSINESS_DOCUMENT_TYPES:
        abort(404)

    payment_id_raw = request.form.get("payment_id", "").strip()
    payment_id = int(payment_id_raw) if payment_id_raw.isdigit() else None
    return_to = _safe_admin_return_path(request.form.get("return_to"))

    context = get_business_document_context(lead_id, payment_id=payment_id)
    if not context:
        abort(404)

    try:
        document_record = get_or_create_business_document_record(
            doc_type,
            lead_id,
            payment_id=payment_id,
        )
        document = _business_pdf_build(
            doc_type,
            context,
            payment_id=payment_id,
            document_record=document_record,
        )
    except ValueError:
        abort(400)

    sent = send_whatsapp_document(
        context["customer_number"],
        document["bytes"],
        document["filename"],
        document["mime_type"],
        caption=(
            f"IBROWS Enterprise {document['title']} - "
            f"{document['reference']}"
        ),
    )

    if sent:
        _record_document_sent_activity(
            lead_id,
            doc_type,
            document["reference"],
        )
        print(
            f"BUSINESS DOCUMENT SENT: lead={lead_id} "
            f"type={doc_type} ref={document['reference']}",
            flush=True,
        )
    else:
        print(
            f"BUSINESS DOCUMENT SEND FAILED: lead={lead_id} type={doc_type}",
            flush=True,
        )

    return redirect(return_to)




