@app.route("/admin/leads/<int:lead_id>/operations", methods=["POST"])
@admin_required
def admin_lead_operations(lead_id):
    validate_csrf()
    action = request.form.get("action", "").strip().lower()
    return_to = _safe_admin_return_path(request.form.get("return_to"))

    try:
        if action == "save_all":
            priority = request.form.get("priority", "").strip().upper()
            raw_follow_up = request.form.get("follow_up", "").strip()

            if request.form.get("clear_follow_up") == "1":
                follow_up_at = None
            elif raw_follow_up:
                follow_up_at = parse_admin_follow_up(raw_follow_up)
            else:
                follow_up_at = None

            note_text = request.form.get("note", "")
            update_lead_management(
                lead_id=lead_id,
                priority=priority,
                follow_up_at=follow_up_at,
                note_text=note_text,
                estimated_value=request.form.get("estimated_value", ""),
                value_currency=request.form.get("value_currency", "MWK"),
                quote_status=request.form.get("quote_status", "NOT_STARTED"),
                quote_reference=request.form.get("quote_reference", ""),
                payment_amount=request.form.get("payment_amount", ""),
                payment_method=request.form.get("payment_method", "OTHER"),
                payment_reference=request.form.get("payment_reference", ""),
                payment_note=request.form.get("payment_note", ""),
                payment_request_token=request.form.get("payment_request_token", ""),
                payment_confirmed=(request.form.get("payment_confirmed") == "1"),
            )

        # Backward-compatible handling for an already-open older dashboard page.
        elif action == "priority":
            priority = request.form.get("priority", "").strip().upper()
            update_lead_priority(lead_id, priority)

        elif action == "followup":
            if request.form.get("clear_follow_up") == "1":
                update_lead_follow_up(lead_id, None)
            else:
                raw_follow_up = request.form.get("follow_up", "").strip()
                if not raw_follow_up:
                    abort(400)
                follow_up_at = parse_admin_follow_up(raw_follow_up)
                update_lead_follow_up(lead_id, follow_up_at)

        elif action == "note":
            note_text = request.form.get("note", "")
            add_lead_note(lead_id, note_text)

        else:
            abort(400)

    except (ValueError, TypeError):
        abort(400)

    return redirect(return_to)


