def _project_clean(value, limit=2000):
    value = str(value or "").strip()
    return value[:limit]


def _project_list(values, limit_items=30, item_limit=120):
    cleaned = []
    for value in values or []:
        item = _project_clean(value, item_limit)
        if item and item not in cleaned:
            cleaned.append(item)
        if len(cleaned) >= limit_items:
            break
    return cleaned


def _project_answers_dict(raw):
    if isinstance(raw, dict):
        return raw
    if not raw:
        return {}
    try:
        value = json.loads(raw)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _project_json_list(raw):
    if isinstance(raw, list):
        return raw
    if not raw:
        return []
    try:
        value = json.loads(raw)
        return value if isinstance(value, list) else []
    except Exception:
        return []


def _project_activity_insert(cur, project_id, event_type, description):
    cur.execute(
        """
        INSERT INTO project_activity (project_id, event_type, description)
        VALUES (%s, %s, %s)
        """,
        (project_id, _project_clean(event_type, 80), _project_clean(description, 2000)),
    )


def _create_project_assessment(contact_name, organisation, phone, email, project_type):
    public_token = secrets.token_urlsafe(32)
    initial_answers = {
        "project_type_label": dict(PROJECT_TYPES).get(project_type, "Other / Not Sure"),
    }
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_assessments (
                    public_token, contact_name, organisation, phone, email,
                    project_type, answers, status, updated_at
                )
                VALUES (%s, %s, NULLIF(%s, ''), NULLIF(%s, ''), NULLIF(%s, ''),
                        %s, %s::jsonb, 'DRAFT', NOW())
                RETURNING id
                """,
                (
                    public_token,
                    contact_name,
                    organisation,
                    phone,
                    email,
                    project_type,
                    json.dumps(initial_answers),
                ),
            )
            project_id = cur.fetchone()[0]
            reference = f"IBR-PD-{datetime.now(ADMIN_TIMEZONE).year}-{project_id:04d}"
            cur.execute(
                "UPDATE project_assessments SET reference=%s WHERE id=%s",
                (reference, project_id),
            )
            _project_activity_insert(cur, project_id, "CREATED", "Project Discovery started by customer.")
        conn.commit()
    return public_token


def _get_project_by_token(public_token):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, reference, public_token, contact_name, organisation,
                       phone, email, project_type, answers, status, complexity,
                       quotation_readiness, scope_confidence, ai_summary,
                       ai_required_features, ai_recommended_features,
                       ai_future_enhancements, ai_missing_information,
                       ai_risk_flags, ai_cost_drivers, ai_scope_reducers,
                       submitted_at, created_at, updated_at
                FROM project_assessments
                WHERE public_token=%s
                """,
                (public_token,),
            )
            row = cur.fetchone()
    return _project_row_to_dict(row) if row else None


def _get_project_by_id(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, reference, public_token, contact_name, organisation,
                       phone, email, project_type, answers, status, complexity,
                       quotation_readiness, scope_confidence, ai_summary,
                       ai_required_features, ai_recommended_features,
                       ai_future_enhancements, ai_missing_information,
                       ai_risk_flags, ai_cost_drivers, ai_scope_reducers,
                       submitted_at, created_at, updated_at
                FROM project_assessments
                WHERE id=%s
                """,
                (project_id,),
            )
            row = cur.fetchone()
    return _project_row_to_dict(row) if row else None


def _project_row_to_dict(row):
    if not row:
        return None
    keys = [
        "id", "reference", "public_token", "contact_name", "organisation",
        "phone", "email", "project_type", "answers", "status", "complexity",
        "quotation_readiness", "scope_confidence", "ai_summary",
        "ai_required_features", "ai_recommended_features",
        "ai_future_enhancements", "ai_missing_information", "ai_risk_flags",
        "ai_cost_drivers", "ai_scope_reducers", "submitted_at", "created_at",
        "updated_at",
    ]
    item = dict(zip(keys, row))
    item["answers"] = _project_answers_dict(item.get("answers"))
    for field in (
        "ai_required_features", "ai_recommended_features",
        "ai_future_enhancements", "ai_missing_information", "ai_risk_flags",
        "ai_cost_drivers", "ai_scope_reducers",
    ):
        item[field] = _project_json_list(item.get(field))
    item["project_type_label"] = dict(PROJECT_TYPES).get(item.get("project_type"), "Other / Not Sure")
    item["status_label"] = PROJECT_DISCOVERY_STATUSES.get(item.get("status"), item.get("status") or "Unknown")
    return item


def _update_project_answers(public_token, updates):
    project = _get_project_by_token(public_token)
    if not project:
        abort(404)
    answers = dict(project.get("answers") or {})
    answers.update(updates)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE project_assessments
                SET answers=%s::jsonb, updated_at=NOW()
                WHERE id=%s
                """,
                (json.dumps(answers), project["id"]),
            )
        conn.commit()


def _project_fallback_analysis(project):
    answers = project.get("answers") or {}
    current_setup = _project_list(answers.get("current_setup", []))
    customer_actions = _project_list(answers.get("customer_actions", []))
    staff_actions = _project_list(answers.get("staff_actions", []))
    website_features = _project_list(answers.get("website_features", []))
    app_features = _project_list(answers.get("app_features", []))
    app_platforms = _project_list(answers.get("app_platforms", []))
    portal_features = _project_list(answers.get("portal_features", []))
    ai_features = _project_list(answers.get("ai_features", []))
    integrations = _project_list(answers.get("integrations", []))
    data_types = _project_list(answers.get("data_types", []))
    security_controls = _project_list(answers.get("security_controls", []))
    project_type = project.get("project_type")
    website_relevant = project_type in {"WEBSITE", "WEB_APP"} or (project_type == "EXISTING_SYSTEM" and "Website" in current_setup)
    app_relevant = project_type in {"MOBILE_APP", "WEB_APP"} or (project_type == "EXISTING_SYSTEM" and "Mobile App" in current_setup)
    missing = []
    risks = []
    reducers = []

    existing_answer = answers.get("existing_system", "")
    website_url = answers.get("website_url", "")
    if existing_answer == "YES" and "Website" in current_setup and not website_url:
        missing.append("Confirm the existing website address.")
    if integrations and answers.get("api_availability") in {"", "NOT_SURE", "NO"}:
        missing.append("Confirm which existing systems provide documented APIs or another supported integration method.")
        risks.append("Integration scope cannot be fixed until API/access feasibility is confirmed.")
    if answers.get("monthly_customers") in {"", "NOT_SURE"}:
        missing.append("Confirm approximate monthly customer/enquiry volume.")
    if answers.get("staff_users") in {"", "NOT_SURE"}:
        missing.append("Confirm approximately how many staff members will use the system.")
    if website_relevant and not answers.get("website_scope"):
        missing.append("Confirm whether the website is new, a redesign, or an extension of the existing site.")
    if website_relevant and not answers.get("website_content_status"):
        missing.append("Confirm how much website content is ready and who will prepare the remainder.")
    if app_relevant and not app_platforms:
        missing.append("Confirm the required app platforms (Android, iOS, PWA, or another agreed target).")
    if app_relevant and not answers.get("app_backend"):
        missing.append("Confirm whether the app will use existing systems, a new backend, or a mixed architecture.")
    if not answers.get("success_criteria"):
        missing.append("Confirm practical success criteria for the first release.")
    if data_types and any(x in data_types for x in {"Customer accounts", "Business documents", "Invoices / payment records", "Sensitive / confidential business data"}) and not security_controls:
        missing.append("Confirm access-control, audit, backup and privacy expectations for business/customer data.")
        risks.append("The solution will handle business/customer data but security controls are not yet defined.")
    if "WhatsApp" in integrations or project.get("project_type") == "WHATSAPP_AI":
        if "WhatsApp Business" in current_setup:
            missing.append("Confirm the current WhatsApp Business/Meta setup before production onboarding.")
            risks.append("An actively used WhatsApp number must follow the approved Meta onboarding path; do not assume migration is acceptable.")
    if existing_answer == "YES":
        reducers.append("Existing infrastructure may be retained where it already satisfies the requirement; do not assume a full rebuild.")
    if website_url:
        reducers.append("Website redesign should remain optional unless the discovery shows it is necessary to achieve the stated objective.")
    if answers.get("website_scope") == "EXTEND":
        reducers.append("Customer prefers to retain the current website and add only the required features.")
    if answers.get("delivery_approach") in {"MVP", "PHASED"}:
        reducers.append("Keep later-phase enhancements outside the first-release quotation unless they are technically indispensable.")

    feature_count = len(customer_actions) + len(staff_actions) + len(website_features) + len(app_features) + len(portal_features) + len(ai_features)
    integration_count = len(integrations)
    if integration_count >= 3 or feature_count >= 10:
        complexity = "ADVANCED"
    elif integration_count >= 1 or feature_count >= 5:
        complexity = "STANDARD"
    else:
        complexity = "BASIC"

    confidence = max(45, min(95, 94 - (len(missing) * 9)))
    readiness = "READY" if not missing else ("READY_WITH_ASSUMPTIONS" if len(missing) == 1 else "NOT_READY")
    objective = _project_clean(answers.get("objective"), 800)
    summary = (
        f"{project.get('organisation') or project.get('contact_name')} is exploring "
        f"{project.get('project_type_label', 'a digital project')}. "
        + (f"Primary objective: {objective}" if objective else "The customer has submitted a structured Project Discovery assessment.")
    )
    required = customer_actions + website_features + app_features + portal_features + staff_actions + ai_features
    if not required:
        required = [project.get("project_type_label", "Digital project")]
    recommended = []
    if customer_actions and "Customer records" not in recommended:
        recommended.append("Maintain searchable customer/enquiry records where the workflow requires follow-up.")
    if staff_actions:
        recommended.append("Provide an admin/staff view appropriate to the selected internal actions.")
    future = []
    if "Advanced analytics" not in required:
        future.append("Advanced analytics can remain a later enhancement unless it is required for the first release.")
    if answers.get("phase_two_items"):
        future.append("Customer identified later-phase items: " + _project_clean(answers.get("phase_two_items"), 500))
    return {
        "summary": summary,
        "required_features": required[:16],
        "recommended_features": recommended[:10],
        "future_enhancements": future[:8],
        "missing_information": missing[:12],
        "risk_flags": risks[:10],
        "cost_drivers": (integrations + app_platforms + security_controls)[:14] + (["AI/automation scope"] if ai_features else []),
        "scope_reducers": reducers[:10],
        "complexity": complexity,
        "scope_confidence": confidence,
        "quotation_readiness": readiness,
    }


def analyze_project_assessment(project_id):
    project = _get_project_by_id(project_id)
    if not project:
        raise ValueError("Project assessment not found.")

    fallback = _project_fallback_analysis(project)
    result = fallback

    if OPENAI_API_KEY:
        safe_input = {
            "organisation": project.get("organisation") or "",
            "project_type": project.get("project_type_label"),
            "answers": project.get("answers") or {},
        }
        instructions = """
You are the internal requirements analyst for IBROWS Enterprise.
Analyse a customer Project Discovery assessment for scoping, not sales pressure.
The goal is to avoid both over-quoting and under-quoting.

Return ONLY valid JSON with these exact keys:
summary: string
required_features: array of strings
recommended_features: array of strings
future_enhancements: array of strings
missing_information: array of strings
risk_flags: array of strings
cost_drivers: array of strings
scope_reducers: array of strings
complexity: one of BASIC, STANDARD, ADVANCED
scope_confidence: integer 0-100
quotation_readiness: one of NOT_READY, READY_WITH_ASSUMPTIONS, READY

Rules:
- Required features are only things the customer clearly requested or that are technically indispensable to the stated request.
- Recommended features must be genuinely useful but should not be silently added to the paid scope.
- Future enhancements are optional and should not inflate the first quotation.
- Flag missing API access, integrations, active WhatsApp/Meta setup, unclear volumes, unclear staff access, security/privacy requirements, or contradictory answers when relevant.
- If an existing website/system can likely be retained, explicitly identify that as a scope reducer.
- For WEBSITE, MOBILE_APP, WEB_APP, CUSTOMER_PORTAL and EXISTING_SYSTEM projects, use the dedicated website/app/portal answers as primary scoping evidence. Distinguish required first-release capabilities from later-phase wishes.
- Treat content preparation, app-store release, hosting, security controls, integrations, migration, staff training and maintenance as separate scope/cost drivers only when the customer selected or clearly implied them.
- If the client selected MVP or phased delivery, do not pull later-phase items into required first-release scope unless technically indispensable.
- Never generate a final price, quotation, discount, margin, or negotiation strategy.
- Do not claim you inspected the customer's website. A URL in the form is only customer-supplied text unless another verified process later reviews it.
- Do not invent requirements.
"""
        try:
            response = client.responses.create(
                model="gpt-5.6-luna",
                store=False,
                instructions=instructions,
                input=json.dumps(safe_input, ensure_ascii=False),
                max_output_tokens=1800,
            )
            parsed = json.loads(response.output_text.strip())
            if isinstance(parsed, dict):
                result = {
                    "summary": _project_clean(parsed.get("summary") or fallback["summary"], 4000),
                    "required_features": _project_list(parsed.get("required_features", []), 20, 240),
                    "recommended_features": _project_list(parsed.get("recommended_features", []), 20, 240),
                    "future_enhancements": _project_list(parsed.get("future_enhancements", []), 20, 240),
                    "missing_information": _project_list(parsed.get("missing_information", []), 20, 240),
                    "risk_flags": _project_list(parsed.get("risk_flags", []), 20, 240),
                    "cost_drivers": _project_list(parsed.get("cost_drivers", []), 20, 240),
                    "scope_reducers": _project_list(parsed.get("scope_reducers", []), 20, 240),
                    "complexity": str(parsed.get("complexity") or fallback["complexity"]).upper(),
                    "scope_confidence": int(parsed.get("scope_confidence", fallback["scope_confidence"])),
                    "quotation_readiness": str(parsed.get("quotation_readiness") or fallback["quotation_readiness"]).upper(),
                }
                if result["complexity"] not in {"BASIC", "STANDARD", "ADVANCED"}:
                    result["complexity"] = fallback["complexity"]
                if result["quotation_readiness"] not in {"NOT_READY", "READY_WITH_ASSUMPTIONS", "READY"}:
                    result["quotation_readiness"] = fallback["quotation_readiness"]
                result["scope_confidence"] = max(0, min(100, result["scope_confidence"]))
        except Exception as error:
            print(f"PROJECT DISCOVERY AI ANALYSIS FALLBACK: {type(error).__name__}", flush=True)
            result = fallback

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE project_assessments
                SET complexity=%s,
                    quotation_readiness=%s,
                    scope_confidence=%s,
                    ai_summary=%s,
                    ai_required_features=%s::jsonb,
                    ai_recommended_features=%s::jsonb,
                    ai_future_enhancements=%s::jsonb,
                    ai_missing_information=%s::jsonb,
                    ai_risk_flags=%s::jsonb,
                    ai_cost_drivers=%s::jsonb,
                    ai_scope_reducers=%s::jsonb,
                    updated_at=NOW()
                WHERE id=%s
                """,
                (
                    result["complexity"], result["quotation_readiness"], result["scope_confidence"],
                    result["summary"], json.dumps(result["required_features"]),
                    json.dumps(result["recommended_features"]), json.dumps(result["future_enhancements"]),
                    json.dumps(result["missing_information"]), json.dumps(result["risk_flags"]),
                    json.dumps(result["cost_drivers"]), json.dumps(result["scope_reducers"]),
                    project_id,
                ),
            )
            _project_activity_insert(cur, project_id, "AI_ANALYSIS", "Project scope analysis refreshed.")
        conn.commit()
    return result


def send_project_discovery_alert_email(project_id):
    if not BREVO_API_KEY or not NOTIFICATION_EMAIL or not BREVO_SENDER_EMAIL:
        return False
    project = _get_project_by_id(project_id)
    if not project:
        return False
    admin_url = f"{LEAD_DASHBOARD_URL.rsplit('/admin/leads', 1)[0]}/admin/projects/{project_id}"
    body = f"""A new IBROWS Smart Project Discovery assessment has been submitted.

Reference: {project['reference']}
Client: {project.get('organisation') or project.get('contact_name')}
Contact: {project.get('contact_name')}
Project type: {project.get('project_type_label')}
Complexity guide: {project.get('complexity')}
Quotation readiness: {project.get('quotation_readiness')}

Review: {admin_url}
"""
    payload = {
        "sender": {"name": BREVO_SENDER_NAME, "email": BREVO_SENDER_EMAIL},
        "to": [{"email": NOTIFICATION_EMAIL, "name": "IBROWS Enterprise"}],
        "subject": f"New Project Discovery: {project['reference']}",
        "textContent": body,
    }
    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={"api-key": BREVO_API_KEY, "Content-Type": "application/json"},
            json=payload,
            timeout=12,
        )
        return 200 <= response.status_code < 300
    except Exception as error:
        print(f"PROJECT DISCOVERY EMAIL FAILED: {type(error).__name__}", flush=True)
        return False


