def _project_review_brief(project):
    lines = [
        f"IBROWS PROJECT DISCOVERY REVIEW — {project['reference']}",
        f"Client: {project.get('organisation') or project.get('contact_name')}",
        f"Contact: {project.get('contact_name')}",
        f"Project type: {project.get('project_type_label')}",
        f"Status: {project.get('status_label')}",
        f"Complexity guide: {project.get('complexity')}",
        f"Quotation readiness: {project.get('quotation_readiness')}",
        f"Scope confidence guide: {project.get('scope_confidence') if project.get('scope_confidence') is not None else '—'}%",
        "",
        "CUSTOMER ANSWERS",
    ]
    for label, value in _project_answer_rows(project):
        lines.append(f"- {label}: {value}")
    lines += ["", "IBROWS AI SCOPE ANALYSIS", project.get("ai_summary") or "No analysis available."]
    sections = [
        ("Required features", project.get("ai_required_features", [])),
        ("Recommended — do not silently include", project.get("ai_recommended_features", [])),
        ("Future / optional", project.get("ai_future_enhancements", [])),
        ("Missing information", project.get("ai_missing_information", [])),
        ("Risk flags", project.get("ai_risk_flags", [])),
        ("Cost drivers", project.get("ai_cost_drivers", [])),
        ("Scope reducers", project.get("ai_scope_reducers", [])),
    ]
    for title, values in sections:
        lines.append("")
        lines.append(title.upper())
        if values:
            lines.extend(f"- {x}" for x in values)
        else:
            lines.append("- None recorded")
    lines += ["", "Instruction for ChatGPT review: Review this assessment with me. Separate required scope from optional scope, identify unresolved technical questions, and help me prepare a fair quotation without automatically adding unnecessary features."]
    return "\n".join(lines)


def _project_phone_whatsapp_url(project):
    digits = re.sub(r"\D", "", project.get("phone") or "")
    if digits.startswith("0") and len(digits) in {9, 10}:
        digits = "265" + digits[1:]
    if len(digits) < 8:
        return ""
    message = f"Hello {project.get('contact_name')}. This is IBROWS Enterprise regarding Project Discovery {project.get('reference')}."
    return f"https://wa.me/{digits}?text={quote(message, safe='')}"


