def _cost_sheet_scope(value):
    n = _cost_sheet_norm(value)
    if n in {"recommended", "recommend", "suggested"}:
        return "RECOMMENDED"
    if n in {"optional", "future", "optional future", "phase 2", "phase two"}:
        return "OPTIONAL"
    return "REQUIRED"


def _xlsx_rows(raw):
    # Lightweight XLSX reader for the first worksheet. This avoids adding a new
    # production dependency just for mobile price-sheet imports.
    rows = []
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        shared = []
        if "xl/sharedStrings.xml" in zf.namelist():
            root = ET.fromstring(zf.read("xl/sharedStrings.xml"))
            ns = {"a": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
            for si in root.findall("a:si", ns):
                shared.append("".join((t.text or "") for t in si.findall(".//a:t", ns)))
        sheet_name = "xl/worksheets/sheet1.xml"
        if sheet_name not in zf.namelist():
            candidates = sorted(x for x in zf.namelist() if x.startswith("xl/worksheets/sheet") and x.endswith(".xml"))
            if not candidates:
                return rows
            sheet_name = candidates[0]
        root = ET.fromstring(zf.read(sheet_name))
        ns = {"a": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
        def col_index(ref):
            letters = re.match(r"[A-Z]+", ref or "A")
            n = 0
            for ch in (letters.group(0) if letters else "A"):
                n = n * 26 + (ord(ch) - 64)
            return n - 1
        for row in root.findall(".//a:sheetData/a:row", ns):
            vals = {}
            max_idx = -1
            for cell in row.findall("a:c", ns):
                idx = col_index(cell.get("r", "A1"))
                max_idx = max(max_idx, idx)
                t = cell.get("t")
                if t == "inlineStr":
                    value = "".join((x.text or "") for x in cell.findall(".//a:t", ns))
                else:
                    vnode = cell.find("a:v", ns)
                    value = vnode.text if vnode is not None and vnode.text is not None else ""
                    if t == "s" and value != "":
                        try:
                            value = shared[int(value)]
                        except Exception:
                            pass
                vals[idx] = value
            if max_idx >= 0:
                rows.append([vals.get(i, "") for i in range(max_idx + 1)])
    return rows


def _uploaded_cost_sheet_rows(file_storage):
    filename = (file_storage.filename or "").strip()
    ext = os.path.splitext(filename.lower())[1]
    raw = file_storage.read(COST_SHEET_MAX_BYTES + 1)
    if not raw:
        raise ValueError("The uploaded price sheet is empty.")
    if len(raw) > COST_SHEET_MAX_BYTES:
        raise ValueError("The price sheet is too large. Keep it under 1 MB.")
    if ext == ".xlsx":
        return _xlsx_rows(raw)
    if ext not in {".csv", ".txt"}:
        raise ValueError("Use an IBROWS CSV, TXT or XLSX price sheet.")
    text = raw.decode("utf-8-sig", errors="replace")
    sample = text[:4096]
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=",;\t")
    except Exception:
        dialect = csv.excel
    return [list(r) for r in csv.reader(io.StringIO(text), dialect)]


def _parse_cost_sheet_rows(rows):
    component_labels = dict(PROJECT_COST_COMPONENTS)
    aliases = _cost_sheet_component_aliases()
    parsed = {
        "components": [],
        "commercial": {},
        "unmatched": [],
    }
    commercial_aliases = {
        "commercial price": "commercial_price",
        "commercial price before discount": "commercial_price",
        "client price": "commercial_price",
        "selling price": "commercial_price",
        "discount": "discount_amount",
        "discount amount": "discount_amount",
        "deposit": "deposit_percent",
        "deposit %": "deposit_percent",
        "deposit percent": "deposit_percent",
        "monthly support": "monthly_support",
        "support monthly": "monthly_support",
        "monthly maintenance": "monthly_support",
    }
    seen_components = {}
    for row_no, raw_row in enumerate(rows, start=1):
        row = [str(x or "").strip() for x in raw_row]
        if not any(row):
            continue
        # Skip common header rows.
        n0 = _cost_sheet_norm(row[0] if row else "")
        n1 = _cost_sheet_norm(row[1] if len(row) > 1 else "")
        if n0 in {"type", "row type"} and n1 in {"item", "component", "name"}:
            continue
        if n0 in {"component", "item", "name"} and n1 in {"amount", "price", "value"}:
            continue

        row_type = ""
        item = ""
        amount_text = ""
        scope_text = ""
        if len(row) >= 4 and _cost_sheet_norm(row[0]) in {"component", "commercial", "pricing", "price"}:
            row_type, item, amount_text, scope_text = row[0], row[1], row[2], row[3]
        elif len(row) >= 3:
            item, amount_text, scope_text = row[0], row[1], row[2]
        elif len(row) >= 2:
            item, amount_text = row[0], row[1]
        else:
            parsed["unmatched"].append({"row": row_no, "text": " | ".join(row)})
            continue

        norm_item = _cost_sheet_norm(item)
        # Support MWK strings and comma formatted values.
        cleaned_amount = re.sub(r"(?i)\b(mwk|mk)\b", "", amount_text).replace(",", "").strip()
        amount = _money_decimal(cleaned_amount, Decimal("-1"))

        if norm_item in commercial_aliases:
            if amount < 0:
                parsed["unmatched"].append({"row": row_no, "text": " | ".join(row)})
                continue
            parsed["commercial"][commercial_aliases[norm_item]] = str(amount)
            continue

        key = aliases.get(norm_item)
        if not key:
            # Fuzzy-safe fallback: only accept a unique component label containing the normalized phrase.
            candidates = []
            for alias, candidate_key in aliases.items():
                if norm_item and (norm_item in alias or alias in norm_item):
                    candidates.append(candidate_key)
            candidates = list(dict.fromkeys(candidates))
            if len(candidates) == 1:
                key = candidates[0]
        if key and amount > 0:
            seen_components[key] = {
                "key": key,
                "label": component_labels[key],
                "amount": str(amount),
                "scope_type": _cost_sheet_scope(scope_text),
                "row": row_no,
            }
        else:
            parsed["unmatched"].append({"row": row_no, "text": " | ".join(row)})
    parsed["components"] = list(seen_components.values())
    parsed["internal_total"] = str(sum((_money_decimal(x["amount"]) for x in parsed["components"]), Decimal("0")))
    return parsed


def _cost_sheet_to_form(project, parsed):
    costing = _get_project_costing(project)
    data = {}
    for item in parsed.get("components", []):
        key = item["key"]
        data[f"include_{key}"] = "1"
        data[f"amount_{key}"] = item["amount"]
        data[f"scope_{key}"] = item["scope_type"]
    commercial = parsed.get("commercial", {})
    data["commercial_price"] = commercial.get("commercial_price", costing.get("commercial_price", 0))
    data["discount_amount"] = commercial.get("discount_amount", costing.get("discount_amount", 0))
    data["deposit_percent"] = commercial.get("deposit_percent", costing.get("deposit_percent", 50))
    data["monthly_support"] = commercial.get("monthly_support", costing.get("monthly_support", 0))
    data["assumptions"] = costing.get("assumptions", "")
    data["exclusions"] = costing.get("exclusions", "")
    data["payment_terms"] = costing.get("payment_terms", "")
    data["third_party_costs"] = costing.get("third_party_costs", "")
    return data


def _money_decimal(value, default=Decimal("0")):
    try:
        cleaned = str(value or "").replace(",", "").strip()
        if cleaned == "":
            return default
        amount = Decimal(cleaned)
        if amount < 0:
            return default
        return amount.quantize(Decimal("0.01"))
    except (InvalidOperation, ValueError, TypeError):
        return default


def _project_costing_defaults(project):
    missing = project.get("ai_missing_information") or []
    risks = project.get("ai_risk_flags") or []
    assumption_lines = []
    for x in missing + risks:
        x = _project_clean(x, 500)
        if x and x not in assumption_lines:
            assumption_lines.append(x)
    assumptions = "\n".join(f"- {x}" for x in assumption_lines[:10])
    exclusions = (
        "- Third-party charges (including Meta/WhatsApp, AI API, hosting, domains, SMS, "
        "payment-gateway fees and applicable taxes) are excluded unless explicitly included.\n"
        "- Work outside the approved scope will be quoted separately.\n"
        "- Future/optional enhancements are not included in Phase 1 unless expressly selected."
    )
    return {
        "project_id": project["id"],
        "quote_reference": "",
        "line_items": [],
        "internal_estimate": Decimal("0"),
        "commercial_price": Decimal("0"),
        "discount_amount": Decimal("0"),
        "deposit_percent": Decimal("50"),
        "monthly_support": Decimal("0"),
        "assumptions": assumptions,
        "exclusions": exclusions,
        "payment_terms": "50% on commencement, 30% after functional demonstration, 20% at production deployment.",
        "third_party_costs": "Client pays approved third-party usage/infrastructure charges unless the quotation explicitly states otherwise.",
        "status": "DRAFT",
        "approved_at": None,
    }


def _get_project_costing(project):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT project_id, quote_reference, line_items, internal_estimate,
                       commercial_price, discount_amount, deposit_percent, monthly_support,
                       assumptions, exclusions, payment_terms, third_party_costs,
                       status, approved_at, created_at, updated_at
                FROM project_costing WHERE project_id=%s
                """,
                (project["id"],),
            )
            row = cur.fetchone()
    if not row:
        return _project_costing_defaults(project)
    keys = [
        "project_id", "quote_reference", "line_items", "internal_estimate",
        "commercial_price", "discount_amount", "deposit_percent", "monthly_support",
        "assumptions", "exclusions", "payment_terms", "third_party_costs",
        "status", "approved_at", "created_at", "updated_at",
    ]
    item = dict(zip(keys, row))
    item["line_items"] = _project_json_list(item.get("line_items"))
    return item


def _costing_view(costing):
    commercial = _money_decimal(costing.get("commercial_price"))
    discount = _money_decimal(costing.get("discount_amount"))
    final_price = max(Decimal("0"), commercial - discount)
    deposit_percent = _money_decimal(costing.get("deposit_percent"), Decimal("50"))
    if deposit_percent > 100:
        deposit_percent = Decimal("100")
    deposit_amount = (final_price * deposit_percent / Decimal("100")).quantize(Decimal("0.01"))
    balance = max(Decimal("0"), final_price - deposit_amount)
    out = dict(costing)
    out.update({
        "final_price": final_price,
        "deposit_amount": deposit_amount,
        "balance_after_deposit": balance,
    })
    return out


def _save_project_costing(project, form):
    items = []
    internal_total = Decimal("0")
    for key, label in PROJECT_COST_COMPONENTS:
        if form.get(f"include_{key}") != "1":
            continue
        amount = _money_decimal(form.get(f"amount_{key}"))
        if amount <= 0:
            continue
        scope_type = _project_clean(form.get(f"scope_{key}") or "REQUIRED", 20).upper()
        if scope_type not in {"REQUIRED", "RECOMMENDED", "OPTIONAL"}:
            scope_type = "REQUIRED"
        items.append({"key": key, "label": label, "amount": str(amount), "scope_type": scope_type})
        internal_total += amount
    other_label = _project_clean(form.get("other_label"), 160)
    other_amount = _money_decimal(form.get("other_amount"))
    if other_label and other_amount > 0:
        other_scope = _project_clean(form.get("other_scope") or "REQUIRED", 20).upper()
        if other_scope not in {"REQUIRED", "RECOMMENDED", "OPTIONAL"}:
            other_scope = "REQUIRED"
        items.append({"key": "custom_other", "label": other_label, "amount": str(other_amount), "scope_type": other_scope})
        internal_total += other_amount

    commercial = _money_decimal(form.get("commercial_price"))
    discount = _money_decimal(form.get("discount_amount"))
    deposit_percent = _money_decimal(form.get("deposit_percent"), Decimal("50"))
    deposit_percent = min(Decimal("100"), deposit_percent)
    monthly_support = _money_decimal(form.get("monthly_support"))
    assumptions = _project_clean(form.get("assumptions"), 5000)
    exclusions = _project_clean(form.get("exclusions"), 5000)
    payment_terms = _project_clean(form.get("payment_terms"), 2500)
    third_party = _project_clean(form.get("third_party_costs"), 2500)

    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_costing (
                    project_id, line_items, internal_estimate, commercial_price,
                    discount_amount, deposit_percent, monthly_support, assumptions,
                    exclusions, payment_terms, third_party_costs, status, updated_at
                ) VALUES (%s, %s::jsonb, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'DRAFT', NOW())
                ON CONFLICT (project_id) DO UPDATE SET
                    line_items=EXCLUDED.line_items,
                    internal_estimate=EXCLUDED.internal_estimate,
                    commercial_price=EXCLUDED.commercial_price,
                    discount_amount=EXCLUDED.discount_amount,
                    deposit_percent=EXCLUDED.deposit_percent,
                    monthly_support=EXCLUDED.monthly_support,
                    assumptions=EXCLUDED.assumptions,
                    exclusions=EXCLUDED.exclusions,
                    payment_terms=EXCLUDED.payment_terms,
                    third_party_costs=EXCLUDED.third_party_costs,
                    status='DRAFT', approved_at=NULL, updated_at=NOW()
                """,
                (
                    project["id"], json.dumps(items), internal_total, commercial, discount,
                    deposit_percent, monthly_support, assumptions, exclusions, payment_terms, third_party,
                ),
            )
            _project_activity_insert(cur, project["id"], "COSTING", "Internal project costing saved or updated.")
        conn.commit()


def _approve_project_costing(project):
    costing = _get_project_costing(project)
    view = _costing_view(costing)
    if not view.get("line_items") or view.get("final_price", Decimal("0")) <= 0:
        return False, "Add at least one internal cost component and a commercial price before approval."
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(revision_no), 0) FROM project_quotations WHERE project_id=%s", (project["id"],))
            issued_revision = int((cur.fetchone() or [0])[0] or 0)
            cur.execute("SELECT quote_reference FROM project_costing WHERE project_id=%s", (project["id"],))
            row = cur.fetchone()
            current_reference = row[0] if row and row[0] else ""
            base_reference = f"IBR-QT-{datetime.now(ADMIN_TIMEZONE).year}-{project['id']:04d}"
            if issued_revision > 0:
                quote_reference = f"{base_reference}-R{issued_revision + 1}"
            else:
                quote_reference = current_reference or base_reference
            cur.execute(
                """
                UPDATE project_costing
                SET quote_reference=%s, status='APPROVED_FOR_QUOTE', approved_at=NOW(), updated_at=NOW()
                WHERE project_id=%s
                """,
                (quote_reference, project["id"]),
            )
            _project_activity_insert(cur, project["id"], "COSTING_APPROVED", f"Commercial costing approved for quotation draft {quote_reference}.")
        conn.commit()
    return True, ""


PROJECT_QUOTE_STATUSES = {
    "ISSUED": "Issued",
    "VIEWED": "Viewed by client",
    "ACCEPTED": "Accepted / Awaiting Deposit",
    "DECLINED": "Declined",
    "EXPIRED": "Expired",
}


def _quote_event_insert(cur, quotation_id, event_type, description):
    cur.execute(
        """
        INSERT INTO project_quotation_events (quotation_id, event_type, description)
        VALUES (%s, %s, %s)
        """,
        (quotation_id, _project_clean(event_type, 80), _project_clean(description, 2000)),
    )


def _quotation_snapshot(project, costing):
    costing = _costing_view(costing)
    required = [x.get("label") for x in costing.get("line_items", []) if x.get("scope_type") == "REQUIRED" and x.get("label")]
    recommended = [x.get("label") for x in costing.get("line_items", []) if x.get("scope_type") == "RECOMMENDED" and x.get("label")]
    optional = [x.get("label") for x in costing.get("line_items", []) if x.get("scope_type") == "OPTIONAL" and x.get("label")]
    if not required:
        required = list(project.get("ai_required_features") or [])
    return {
        "business": {
            "name": IBROWS_BUSINESS_NAME,
            "tagline": IBROWS_BUSINESS_TAGLINE,
            "location": IBROWS_BUSINESS_LOCATION,
            "email": IBROWS_BUSINESS_EMAIL,
            "whatsapp": IBROWS_BUSINESS_WHATSAPP,
        },
        "client": {
            "organisation": project.get("organisation") or "",
            "contact_name": project.get("contact_name") or "",
            "email": project.get("email") or "",
            "phone": project.get("phone") or "",
        },
        "project": {
            "discovery_reference": project.get("reference") or "",
            "project_type": project.get("project_type_label") or "",
            "summary": project.get("ai_summary") or "",
        },
        "scope": {
            "required": required,
            "recommended": recommended,
            "optional": optional,
        },
        "pricing": {
            "currency": "MWK",
            "commercial_price": str(_money_decimal(costing.get("commercial_price"))),
            "discount_amount": str(_money_decimal(costing.get("discount_amount"))),
            "final_price": str(_money_decimal(costing.get("final_price"))),
            "deposit_percent": str(_money_decimal(costing.get("deposit_percent"))),
            "deposit_amount": str(_money_decimal(costing.get("deposit_amount"))),
            "balance_after_deposit": str(_money_decimal(costing.get("balance_after_deposit"))),
            "monthly_support": str(_money_decimal(costing.get("monthly_support"))),
        },
        "terms": {
            "payment_terms": costing.get("payment_terms") or "",
            "assumptions": costing.get("assumptions") or "",
            "exclusions": costing.get("exclusions") or "",
            "third_party_costs": costing.get("third_party_costs") or "",
        },
    }


def _quotation_row_to_dict(row):
    if not row:
        return None
    keys = [
        "id", "project_id", "quote_reference", "revision_no", "public_token",
        "status", "snapshot", "issued_at", "valid_until", "viewed_at",
        "responded_at", "responded_by", "response_note", "accepted_at",
        "declined_at", "created_at", "updated_at",
    ]
    item = dict(zip(keys, row))
    snap = item.get("snapshot")
    if not isinstance(snap, dict):
        try:
            snap = json.loads(snap or "{}")
        except Exception:
            snap = {}
    item["snapshot"] = snap
    pricing_raw = dict(snap.get("pricing") or {})
    item["pricing"] = {
        key: _money_decimal(pricing_raw.get(key))
        for key in (
            "commercial_price", "discount_amount", "final_price",
            "deposit_percent", "deposit_amount", "balance_after_deposit",
            "monthly_support",
        )
    }
    item["currency"] = pricing_raw.get("currency") or "MWK"
    item["client"] = dict(snap.get("client") or {})
    item["project_snapshot"] = dict(snap.get("project") or {})
    item["business"] = dict(snap.get("business") or {})
    item["scope"] = dict(snap.get("scope") or {})
    item["terms"] = dict(snap.get("terms") or {})
    item["status_label"] = PROJECT_QUOTE_STATUSES.get(item.get("status"), item.get("status") or "Unknown")
    for key in ("required", "recommended", "optional"):
        values = item["scope"].get(key)
        item["scope"][key] = values if isinstance(values, list) else []
    item["issued_label"] = item["issued_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("issued_at") else ""
    item["valid_label"] = item["valid_until"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("valid_until") else ""
    item["viewed_label"] = item["viewed_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("viewed_at") else ""
    item["responded_label"] = item["responded_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("responded_at") else ""
    return item


def _quotation_select_sql():
    return """
        SELECT id, project_id, quote_reference, revision_no, public_token,
               status, snapshot, issued_at, valid_until, viewed_at,
               responded_at, responded_by, response_note, accepted_at,
               declined_at, created_at, updated_at
        FROM project_quotations
    """


def _get_project_quotation_by_id(quotation_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(_quotation_select_sql() + " WHERE id=%s", (quotation_id,))
            row = cur.fetchone()
    return _quotation_row_to_dict(row) if row else None


def _get_project_quotation_by_token(public_token):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(_quotation_select_sql() + " WHERE public_token=%s", (public_token,))
            row = cur.fetchone()
    return _quotation_row_to_dict(row) if row else None


def _get_project_quotation_by_reference(project_id, quote_reference):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(_quotation_select_sql() + " WHERE project_id=%s AND quote_reference=%s", (project_id, quote_reference))
            row = cur.fetchone()
    return _quotation_row_to_dict(row) if row else None


def _list_project_quotations(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(_quotation_select_sql() + " WHERE project_id=%s ORDER BY revision_no DESC, id DESC", (project_id,))
            rows = cur.fetchall()
    return [_quotation_row_to_dict(row) for row in rows]


def _list_quotation_events(quotation_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT event_type, description, created_at FROM project_quotation_events WHERE quotation_id=%s ORDER BY created_at DESC, id DESC LIMIT 100",
                (quotation_id,),
            )
            rows = cur.fetchall()
    return [{
        "event_type": row[0],
        "description": row[1],
        "created_label": row[2].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if row[2] else "",
    } for row in rows]


def _sync_project_quotation_expiry(quote_item):
    if not quote_item or quote_item.get("status") not in {"ISSUED", "VIEWED"}:
        return quote_item
    valid_until = quote_item.get("valid_until")
    if not valid_until or datetime.now(UTC_TIMEZONE) <= valid_until.astimezone(UTC_TIMEZONE):
        return quote_item
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE project_quotations SET status='EXPIRED', updated_at=NOW() WHERE id=%s AND status IN ('ISSUED','VIEWED') RETURNING id",
                (quote_item["id"],),
            )
            changed = cur.fetchone()
            if changed:
                _quote_event_insert(cur, quote_item["id"], "EXPIRED", "Quotation validity period expired.")
                _project_activity_insert(cur, quote_item["project_id"], "QUOTE_EXPIRED", f"Quotation {quote_item['quote_reference']} expired.")
        conn.commit()
    return _get_project_quotation_by_id(quote_item["id"])


def _quote_latin1(value):
    return _pdf_normalize_text(value).encode("latin-1", "replace").decode("latin-1")


def _quotation_pdf_bytes(quote_item):
    """Build a branded, revision-aware client quotation PDF without external PDF dependencies."""
    quote_item = _sync_project_quotation_expiry(quote_item)
    pricing = quote_item["pricing"]

    # Brand palette: IBROWS purple with neutral business-document tones.
    PURPLE = (0.39, 0.08, 0.35)
    PURPLE_DARK = (0.27, 0.05, 0.24)
    PURPLE_PALE = (0.97, 0.94, 0.97)
    INK = (0.08, 0.10, 0.14)
    MUTED = (0.40, 0.44, 0.50)
    LIGHT = (0.965, 0.97, 0.975)
    BORDER = (0.86, 0.87, 0.89)
    GREEN = (0.03, 0.38, 0.23)
    GREEN_PALE = (0.93, 0.98, 0.95)
    BLUE_PALE = (0.94, 0.97, 1.00)

    PAGE_W, PAGE_H = 595.0, 842.0
    LEFT, RIGHT = 42.0, 553.0
    CONTENT_W = RIGHT - LEFT
    BOTTOM_LIMIT = 102.0

    pages = []
    commands = None
    y = 0.0

    def color_fill(rgb):
        return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} rg"

    def color_stroke(rgb):
        return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} RG"

    def add_text(text, x, y_pos, size=10.0, bold=False, rgb=INK):
        safe = _quote_latin1(text)
        font = "F2" if bold else "F1"
        commands.append(color_fill(rgb))
        commands.append(
            f"BT /{font} {size:g} Tf {x:g} {y_pos:g} Td ({_pdf_escape(safe)}) Tj ET"
        )

    def right_text(text, right_x, y_pos, size=10.0, bold=False, rgb=INK):
        safe = _quote_latin1(text)
        width = _pdf_text_width_points(safe, size=size, bold=bold)
        add_text(safe, max(LEFT, right_x - width), y_pos, size=size, bold=bold, rgb=rgb)

    def new_page():
        nonlocal commands, y
        commands = []
        pages.append(commands)

        logo_w = 155.0
        logo_h = logo_w * (IBROWS_LOGO_JPEG_HEIGHT / IBROWS_LOGO_JPEG_WIDTH)
        commands.append(f"q {logo_w:g} 0 0 {logo_h:g} {LEFT:g} {786-logo_h:g} cm /Logo Do Q")

        right_text("QUOTATION", RIGHT, 794, size=20, bold=True, rgb=PURPLE_DARK)
        right_text(
            f"{quote_item['quote_reference']}  |  Revision {quote_item['revision_no']}",
            RIGHT, 774, size=8.8, bold=True, rgb=INK,
        )
        right_text(f"Issued: {quote_item['issued_label']}", RIGHT, 760, size=8.2, rgb=MUTED)
        right_text(f"Valid until: {quote_item['valid_label']}", RIGHT, 747, size=8.2, rgb=MUTED)

        commands.append(color_stroke(PURPLE))
        commands.append(f"2 w {LEFT:g} 724 m {RIGHT:g} 724 l S")
        y = 700.0

    def ensure(height):
        nonlocal y
        if y - height < BOTTOM_LIMIT:
            new_page()

    def wrapped_lines(text, size=9.6, bold=False, width=CONTENT_W):
        return _wrap_pdf_text_points(_quote_latin1(text), size=size, bold=bold, max_points=width)

    def draw_wrapped(text, size=9.6, bold=False, rgb=INK, width=CONTENT_W, x=LEFT, leading=13.2, after=5.0):
        nonlocal y
        lines = wrapped_lines(text, size=size, bold=bold, width=width)
        ensure(len(lines) * leading + after)
        for line in lines:
            add_text(line, x, y, size=size, bold=bold, rgb=rgb)
            y -= leading
        y -= after

    def section_heading(label, after=10.0):
        nonlocal y
        ensure(31.0)
        y -= 3.0
        add_text(label.upper(), LEFT, y, size=10.5, bold=True, rgb=PURPLE_DARK)
        y -= 8.0
        commands.append(color_stroke(BORDER))
        commands.append(f"0.7 w {LEFT:g} {y:g} m {RIGHT:g} {y:g} l S")
        y -= after

    def bullet(text, size=9.4):
        nonlocal y
        lines = wrapped_lines(text, size=size, width=CONTENT_W - 22)
        needed = max(1, len(lines)) * 12.7 + 2
        ensure(needed)
        add_text("-", LEFT + 2, y, size=size, bold=True, rgb=PURPLE)
        for idx, line in enumerate(lines):
            add_text(line, LEFT + 16, y, size=size, rgb=INK)
            y -= 12.7
        y -= 2.0

    def client_box():
        nonlocal y
        values = []
        organisation = quote_item["client"].get("organisation") or ""
        contact = quote_item["client"].get("contact_name") or ""
        if organisation:
            values.append((organisation, True))
        if contact and contact != organisation:
            values.append((contact, False))
        if quote_item["client"].get("email"):
            values.append((quote_item["client"]["email"], False))
        if quote_item["client"].get("phone"):
            values.append((quote_item["client"]["phone"], False))
        if not values:
            values = [("Client", True)]

        box_h = 30.0 + 15.0 * len(values)
        ensure(box_h + 14)
        box_y = y - box_h
        commands.append(color_fill(LIGHT))
        commands.append(f"{LEFT:g} {box_y:g} {CONTENT_W:g} {box_h:g} re f")
        add_text("PREPARED FOR", LEFT + 12, y - 18, size=8.2, bold=True, rgb=PURPLE)
        line_y = y - 37
        for value, strong in values:
            add_text(value, LEFT + 12, line_y, size=10.2 if strong else 9.3, bold=strong, rgb=INK if strong else MUTED)
            line_y -= 15.0
        y = box_y - 18.0

    def commercial_card():
        nonlocal y
        card_h = 126.0 if pricing.get("monthly_support", Decimal("0")) > 0 else 108.0
        ensure(card_h + 16)
        box_y = y - card_h
        commands.append(color_fill(PURPLE_PALE))
        commands.append(f"{LEFT:g} {box_y:g} {CONTENT_W:g} {card_h:g} re f")
        add_text("QUOTED INVESTMENT", LEFT + 14, y - 22, size=8.4, bold=True, rgb=PURPLE)
        add_text(f"MWK {pricing['final_price']:,.0f}", LEFT + 14, y - 51, size=22, bold=True, rgb=PURPLE_DARK)

        if pricing.get("discount_amount", Decimal("0")) > 0:
            right_text(
                f"Before discount: MWK {pricing['commercial_price']:,.0f}",
                RIGHT - 14, y - 29, size=8.1, rgb=MUTED,
            )
            right_text(
                f"Discount: MWK {pricing['discount_amount']:,.0f}",
                RIGHT - 14, y - 43, size=8.1, rgb=MUTED,
            )

        row_y = y - 78
        add_text(f"Deposit ({pricing['deposit_percent']:,.0f}%)", LEFT + 14, row_y, size=8.2, bold=True, rgb=MUTED)
        add_text(f"MWK {pricing['deposit_amount']:,.0f}", LEFT + 14, row_y - 15, size=11.4, bold=True, rgb=INK)
        add_text("Balance after deposit", LEFT + 205, row_y, size=8.2, bold=True, rgb=MUTED)
        add_text(f"MWK {pricing['balance_after_deposit']:,.0f}", LEFT + 205, row_y - 15, size=11.4, bold=True, rgb=INK)

        if pricing.get("monthly_support", Decimal("0")) > 0:
            add_text("ONGOING SUPPORT", RIGHT - 155, row_y, size=8.2, bold=True, rgb=MUTED)
            right_text(f"MWK {pricing['monthly_support']:,.0f} / month", RIGHT - 14, row_y - 15, size=10.5, bold=True, rgb=INK)
        y = box_y - 19.0

    def term_section(label, raw_text):
        nonlocal y
        section_heading(label, after=9.0)
        raw = _pdf_normalize_text(raw_text or "").replace("\r", "")
        paragraphs = [p.strip() for p in raw.split("\n") if p.strip()] or ["Not stated."]
        for paragraph in paragraphs:
            is_bullet = paragraph.startswith(("-", "*", "•"))
            cleaned = paragraph.lstrip("-*• ").strip() if is_bullet else paragraph
            if is_bullet:
                bullet(cleaned, size=9.1)
            else:
                draw_wrapped(cleaned, size=9.2, leading=12.6, after=3.0)
        y -= 3.0

    new_page()
    client_box()

    section_heading("Project")
    draw_wrapped(
        quote_item["project_snapshot"].get("project_type") or "Digital solution",
        size=12.5, bold=True, after=7.0,
    )
    discovery_ref = quote_item["project_snapshot"].get("discovery_reference") or ""
    if discovery_ref:
        draw_wrapped(f"Project discovery reference: {discovery_ref}", size=8.4, rgb=MUTED, after=5.0)
    draw_wrapped(quote_item["project_snapshot"].get("summary") or "", size=9.5, leading=13.0, after=11.0)

    section_heading("Included scope")
    for item in quote_item["scope"].get("required", []):
        bullet(item)

    if quote_item["scope"].get("recommended"):
        y -= 4.0
        section_heading("Recommended additions included in this quotation")
        for item in quote_item["scope"]["recommended"]:
            bullet(item)

    if quote_item["scope"].get("optional"):
        y -= 4.0
        section_heading("Optional / future enhancements")
        draw_wrapped(
            "Shown for future consideration and not part of the core delivery unless expressly included in the final scope.",
            size=8.9, rgb=MUTED, after=5.0,
        )
        for item in quote_item["scope"]["optional"]:
            bullet(item)

    # Commercial terms intentionally start on a fresh page so the investment and
    # legal/commercial conditions remain together and easy for the client to review.
    new_page()
    section_heading("Investment")
    commercial_card()

    term_section("Payment terms", quote_item["terms"].get("payment_terms") or "Not stated.")
    term_section("Assumptions", quote_item["terms"].get("assumptions") or "None stated.")
    term_section("Exclusions", quote_item["terms"].get("exclusions") or "None stated.")
    term_section("Third-party costs", quote_item["terms"].get("third_party_costs") or "Not stated.")

    # Explicit client-protection notice. This mirrors the secure client quotation page.
    notice_lines = wrapped_lines(
        "Acceptance of this quotation records approval of the quoted scope and terms. Acceptance does not constitute payment or confirmation that payment has been received. Project commencement remains subject to IBROWS confirmation and the stated payment/deposit conditions.",
        size=8.8, width=CONTENT_W - 30,
    )
    notice_h = 24.0 + len(notice_lines) * 12.0
    ensure(notice_h + 10)
    box_y = y - notice_h
    commands.append(color_fill(BLUE_PALE))
    commands.append(f"{LEFT:g} {box_y:g} {CONTENT_W:g} {notice_h:g} re f")
    commands.append(color_fill(GREEN))
    commands.append(f"{LEFT:g} {box_y:g} 4 {notice_h:g} re f")
    add_text("ACCEPTANCE & PAYMENT", LEFT + 14, y - 17, size=8.2, bold=True, rgb=GREEN)
    line_y = y - 34
    for line in notice_lines:
        add_text(line, LEFT + 14, line_y, size=8.8, rgb=INK)
        line_y -= 12.0
    y = box_y - 10.0

    total_pages = len(pages)
    for index, page_commands in enumerate(pages, start=1):
        page_commands.append(color_stroke(BORDER))
        page_commands.append(f"0.7 w {LEFT:g} 78 m {RIGHT:g} 78 l S")
        page_commands.append(color_fill(MUTED))
        footer_left = _quote_latin1(f"{IBROWS_BUSINESS_TAGLINE}  |  {IBROWS_BUSINESS_EMAIL}")
        page_commands.append(f"BT /F1 7.8 Tf {LEFT:g} 57 Td ({_pdf_escape(footer_left)}) Tj ET")
        page_label = f"Page {index} of {total_pages}"
        page_width = _pdf_text_width_points(page_label, size=7.8, bold=False)
        page_commands.append(f"BT /F1 7.8 Tf {RIGHT-page_width:g} 57 Td ({_pdf_escape(page_label)}) Tj ET")
        page_commands.append(color_fill(INK))

    logo_bytes = base64.b64decode(IBROWS_LOGO_JPEG_B64)
    objects = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        5: (
            b"<< /Type /XObject /Subtype /Image "
            + f"/Width {IBROWS_LOGO_JPEG_WIDTH} /Height {IBROWS_LOGO_JPEG_HEIGHT} ".encode("ascii")
            + b"/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode "
            + f"/Length {len(logo_bytes)} >>\nstream\n".encode("ascii")
            + logo_bytes
            + b"\nendstream"
        ),
    }

    kids = []
    next_id = 6
    for page_commands in pages:
        page_id = next_id
        content_id = next_id + 1
        next_id += 2
        kids.append(f"{page_id} 0 R")
        stream = "\n".join(page_commands).encode("latin-1", "strict")
        objects[page_id] = (
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {PAGE_W:g} {PAGE_H:g}] ".encode("ascii")
            + b"/Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo 5 0 R >> >> "
            + f"/Contents {content_id} 0 R >>".encode("ascii")
        )
        objects[content_id] = (
            b"<< /Length " + str(len(stream)).encode("ascii") + b" >>\nstream\n" + stream + b"\nendstream"
        )

    objects[2] = f"<< /Type /Pages /Kids [{' '.join(kids)}] /Count {len(kids)} >>".encode("ascii")

    max_id = max(objects)
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0] * (max_id + 1)
    for obj_id in range(1, max_id + 1):
        offsets[obj_id] = len(out)
        out.extend(f"{obj_id} 0 obj\n".encode("ascii"))
        out.extend(objects[obj_id])
        out.extend(b"\nendobj\n")

    xref = len(out)
    out.extend(f"xref\n0 {max_id + 1}\n".encode("ascii"))
    out.extend(b"0000000000 65535 f \n")
    for obj_id in range(1, max_id + 1):
        out.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode("ascii"))
    out.extend(
        f"trailer\n<< /Size {max_id + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF".encode("ascii")
    )
    return bytes(out)
def _quotation_whatsapp_message(quote_item, public_url):
    name = quote_item["client"].get("contact_name") or "there"
    return (
        f"Hello {name}, IBROWS Enterprise has issued quotation {quote_item['quote_reference']} "
        f"(Revision {quote_item.get('revision_no') or 1}). "
        f"Quoted investment: MWK {quote_item['pricing']['final_price']:,.0f}. "
        f"Deposit: {quote_item['pricing']['deposit_percent']:,.0f}% - MWK {quote_item['pricing']['deposit_amount']:,.0f}. "
        f"It is valid until {quote_item['valid_label']}. "
        f"Please review the quotation, download the PDF, and respond securely here: {public_url}"
    )


def _quotation_whatsapp_delivery(quote_item, public_url):
    digits = re.sub(r"\D", "", quote_item["client"].get("phone") or "")
    if digits.startswith("0") and len(digits) in {9, 10}:
        digits = "265" + digits[1:]
    if len(digits) < 8:
        return {
            "digits": "",
            "message": "",
            "business_intent": "",
            "standard_intent": "",
            "web_url": "",
        }

    message = _quotation_whatsapp_message(quote_item, public_url)
    encoded = quote(message, safe="")
    query_string = f"phone={digits}&text={encoded}"

    # Android package-targeted intents avoid a browser falling through to the
    # ordinary WhatsApp download page when the staff member uses WhatsApp Business.
    business_intent = (
        f"intent://send?{query_string}"
        "#Intent;scheme=whatsapp;package=com.whatsapp.w4b;end"
    )
    standard_intent = (
        f"intent://send?{query_string}"
        "#Intent;scheme=whatsapp;package=com.whatsapp;end"
    )
    web_url = f"https://wa.me/{digits}?text={encoded}"
    return {
        "digits": digits,
        "message": message,
        "business_intent": business_intent,
        "standard_intent": standard_intent,
        "web_url": web_url,
    }


def _quotation_whatsapp_url(quote_item, public_url):
    # Backwards-compatible web fallback used by the existing /whatsapp route.
    return _quotation_whatsapp_delivery(quote_item, public_url).get("web_url", "")


def _send_project_quotation_email(quote_item, public_url):
    recipient = (quote_item["client"].get("email") or "").strip()
    if not recipient:
        return False, "The client does not have an email address on this Project Discovery record."
    if not BREVO_API_KEY or not BREVO_SENDER_EMAIL:
        return False, "Brevo email delivery is not configured."
    name = quote_item["client"].get("contact_name") or "Client"
    body = f"""Hello {name},

IBROWS Enterprise has issued quotation {quote_item['quote_reference']} for your project.

Quoted investment: MWK {quote_item['pricing']['final_price']:,.0f}
Deposit: {quote_item['pricing']['deposit_percent']:,.0f}% - MWK {quote_item['pricing']['deposit_amount']:,.0f}
Valid until: {quote_item['valid_label']}

Review, download and respond securely:
{public_url}

A PDF copy of the quotation is attached for your records.

Acceptance records approval of the quoted scope and terms. It does not record payment. Project commencement remains subject to IBROWS confirmation and the stated payment/deposit conditions.

IBROWS Enterprise
{IBROWS_BUSINESS_TAGLINE}
"""
    pdf_bytes = _quotation_pdf_bytes(quote_item)
    payload = {
        "sender": {"name": BREVO_SENDER_NAME, "email": BREVO_SENDER_EMAIL},
        "to": [{"email": recipient, "name": name}],
        "subject": f"IBROWS Quotation {quote_item['quote_reference']}",
        "textContent": body,
        "attachment": [{
            "content": base64.b64encode(pdf_bytes).decode("ascii"),
            "name": f"{quote_item['quote_reference']}.pdf",
        }],
    }
    try:
        response = requests.post(
            "https://api.brevo.com/v3/smtp/email",
            headers={"api-key": BREVO_API_KEY, "Content-Type": "application/json"},
            json=payload,
            timeout=15,
        )
        if 200 <= response.status_code < 300:
            return True, ""
        return False, f"Brevo returned HTTP {response.status_code}."
    except Exception as error:
        print(f"PROJECT QUOTATION EMAIL FAILED: {type(error).__name__}", flush=True)
        return False, f"Email delivery failed: {type(error).__name__}."



PROJECT_PAYMENT_STAGE_LABELS = {
    "DEPOSIT": "Deposit / initial payment",
    "MILESTONE_2": "Functional demonstration payment",
    "FINAL": "Final deployment payment",
    "OTHER": "Other project payment",
}
PROJECT_INVOICE_STATUS_LABELS = {
    "UNPAID": "Unpaid",
    "PART_PAID": "Part paid",
    "PAID": "Paid",
    "VOID": "Void",
}


def _latest_accepted_project_quotation(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                _quotation_select_sql() +
                " WHERE project_id=%s AND status='ACCEPTED' ORDER BY revision_no DESC, id DESC LIMIT 1",
                (project_id,),
            )
            row = cur.fetchone()
    return _quotation_row_to_dict(row) if row else None


def _project_invoice_row_to_dict(row):
    if not row:
        return None
    keys = [
        "id", "project_id", "quotation_id", "invoice_number", "invoice_type",
        "amount", "currency", "status", "issued_at", "paid_at", "created_at", "updated_at",
    ]
    item = dict(zip(keys, row))
    item["amount"] = _money_decimal(item.get("amount"))
    item["currency"] = item.get("currency") or "MWK"
    item["status_label"] = PROJECT_INVOICE_STATUS_LABELS.get(item.get("status"), item.get("status") or "Unknown")
    item["issued_label"] = item["issued_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("issued_at") else ""
    item["paid_label"] = item["paid_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("paid_at") else ""
    return item


def _get_project_invoice_by_quotation(quotation_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, project_id, quotation_id, invoice_number, invoice_type,
                       amount, currency, status, issued_at, paid_at, created_at, updated_at
                FROM project_invoices WHERE quotation_id=%s
                """,
                (quotation_id,),
            )
            row = cur.fetchone()
    return _project_invoice_row_to_dict(row)


def _ensure_project_deposit_invoice(quote_item):
    if not quote_item or quote_item.get("status") != "ACCEPTED":
        return None
    existing = _get_project_invoice_by_quotation(quote_item["id"])
    if existing:
        return existing
    year = quote_item["issued_at"].astimezone(ADMIN_TIMEZONE).year if quote_item.get("issued_at") else datetime.now(ADMIN_TIMEZONE).year
    invoice_number = f"IBR-INV-{year}-{quote_item['project_id']:04d}-D{int(quote_item.get('revision_no') or 1)}"
    deposit_amount = _money_decimal(quote_item["pricing"].get("deposit_amount"))
    if deposit_amount <= 0:
        return None
    inserted = False
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_invoices (
                    project_id, quotation_id, invoice_number, invoice_type,
                    amount, currency, status, issued_at, updated_at
                ) VALUES (%s,%s,%s,'DEPOSIT',%s,%s,'UNPAID',NOW(),NOW())
                ON CONFLICT (quotation_id) DO NOTHING
                RETURNING id
                """,
                (quote_item["project_id"], quote_item["id"], invoice_number, deposit_amount, quote_item.get("currency") or "MWK"),
            )
            inserted = bool(cur.fetchone())
            if inserted:
                _quote_event_insert(cur, quote_item["id"], "DEPOSIT_INVOICE_CREATED", f"Deposit invoice {invoice_number} created for {quote_item.get('currency') or 'MWK'} {deposit_amount:,.0f}.")
                _project_activity_insert(cur, quote_item["project_id"], "DEPOSIT_INVOICE", f"Deposit invoice {invoice_number} created from accepted quotation {quote_item['quote_reference']}.")
        conn.commit()
    return _get_project_invoice_by_quotation(quote_item["id"])


def _get_project_execution(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, project_id, quotation_id, status, scope_snapshot,
                       investment, currency, payment_schedule, start_note,
                       started_at, completed_at, created_at, updated_at
                FROM project_execution WHERE project_id=%s
                """,
                (project_id,),
            )
            row = cur.fetchone()
    if not row:
        return None
    keys = [
        "id", "project_id", "quotation_id", "status", "scope_snapshot",
        "investment", "currency", "payment_schedule", "start_note",
        "started_at", "completed_at", "created_at", "updated_at",
    ]
    item = dict(zip(keys, row))
    item["investment"] = _money_decimal(item.get("investment"))
    item["started_label"] = item["started_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("started_at") else ""
    item["completed_label"] = item["completed_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("completed_at") else ""
    return item


def _project_payment_rows(project_id, quotation_id=None):
    sql = """
        SELECT id, project_id, quotation_id, invoice_id, stage, amount, currency,
               payment_method, reference, payment_note, received_at, created_at
        FROM project_payments WHERE project_id=%s
    """
    params = [project_id]
    if quotation_id is not None:
        sql += " AND quotation_id=%s"
        params.append(quotation_id)
    sql += " ORDER BY received_at DESC, id DESC"
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(sql, tuple(params))
            rows = cur.fetchall()
    out = []
    for row in rows:
        keys = [
            "id", "project_id", "quotation_id", "invoice_id", "stage", "amount", "currency",
            "payment_method", "reference", "payment_note", "received_at", "created_at",
        ]
        item = dict(zip(keys, row))
        item["amount"] = _money_decimal(item.get("amount"))
        item["currency"] = item.get("currency") or "MWK"
        item["method_label"] = PAYMENT_METHODS.get(item.get("payment_method") or "OTHER", str(item.get("payment_method") or "OTHER").replace("_", " ").title())
        item["stage_label"] = PROJECT_PAYMENT_STAGE_LABELS.get(item.get("stage"), item.get("stage") or "Project payment")
        item["received_label"] = item["received_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("received_at") else ""
        out.append(item)
    return out


def _project_commercial_state(project_id, quote_item=None, sync=True):
    quote_item = quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item or quote_item.get("status") != "ACCEPTED":
        return None
    invoice = _ensure_project_deposit_invoice(quote_item)
    payments = _project_payment_rows(project_id, quote_item["id"])
    total_paid = sum((_money_decimal(x.get("amount")) for x in payments), Decimal("0"))
    final_price = _money_decimal(quote_item["pricing"].get("final_price"))
    deposit_required = _money_decimal(quote_item["pricing"].get("deposit_amount"))
    deposit_applied = min(total_paid, deposit_required)
    deposit_remaining = max(Decimal("0"), deposit_required - total_paid)
    total_remaining = max(Decimal("0"), final_price - total_paid)
    deposit_verified = deposit_required > 0 and total_paid >= deposit_required
    fully_paid = final_price > 0 and total_paid >= final_price
    execution = _get_project_execution(project_id)
    desired_project_status = ("COMPLETED" if execution and execution.get("status") == "COMPLETED" else ("IN_PROGRESS" if execution and execution.get("status") == "IN_PROGRESS" else ("DEPOSIT_PAID" if deposit_verified else "ACCEPTED")))
    invoice_status = "PAID" if deposit_verified else ("PART_PAID" if total_paid > 0 else "UNPAID")
    if sync and invoice:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE project_invoices
                    SET status=%s,
                        paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,
                        updated_at=NOW()
                    WHERE id=%s AND status <> 'VOID'
                    """,
                    (invoice_status, invoice_status, invoice["id"]),
                )
                cur.execute(
                    "UPDATE project_assessments SET status=%s, updated_at=NOW() WHERE id=%s AND status IN ('ACCEPTED','DEPOSIT_PAID','IN_PROGRESS')",
                    (desired_project_status, project_id),
                )
            conn.commit()
        invoice = _get_project_invoice_by_quotation(quote_item["id"])
    return {
        "quote": quote_item,
        "invoice": invoice,
        "payments": payments,
        "total_paid": total_paid,
        "final_price": final_price,
        "deposit_required": deposit_required,
        "deposit_applied": deposit_applied,
        "deposit_remaining": deposit_remaining,
        "total_remaining": total_remaining,
        "deposit_verified": deposit_verified,
        "fully_paid": fully_paid,
        "execution": execution,
        "project_status": desired_project_status,
        "currency": quote_item.get("currency") or "MWK",
    }


def _project_sandbox_state(project_id, quote_item=None):
    """Return the isolated test-payment state for one accepted project.

    Sandbox rows intentionally live in their own tables. They are never read by
    Finance, never update project_invoices, and never change the live project
    status or project_execution record.
    """
    quote_item = quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item or quote_item.get("status") != "ACCEPTED":
        return None
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT project_id, quotation_id, enabled, sandbox_started_at,
                       start_note, execution_plan, created_at, updated_at
                FROM project_sandbox_state WHERE project_id=%s
                """,
                (project_id,),
            )
            row = cur.fetchone()
            cur.execute(
                """
                SELECT id, project_id, quotation_id, stage, amount, currency,
                       payment_method, reference, payment_note, received_at,
                       voided_at, void_reason, created_at
                FROM project_sandbox_payments
                WHERE project_id=%s AND quotation_id=%s
                ORDER BY received_at DESC, id DESC
                """,
                (project_id, quote_item["id"]),
            )
            payment_rows = cur.fetchall()

    enabled = bool(row and row[2] and int(row[1]) == int(quote_item["id"]))
    payments = []
    active_total = Decimal("0")
    for prow in payment_rows:
        keys = [
            "id", "project_id", "quotation_id", "stage", "amount", "currency",
            "payment_method", "reference", "payment_note", "received_at",
            "voided_at", "void_reason", "created_at",
        ]
        item = dict(zip(keys, prow))
        item["amount"] = _money_decimal(item.get("amount"))
        item["currency"] = item.get("currency") or "MWK"
        item["method_label"] = PAYMENT_METHODS.get(
            item.get("payment_method") or "OTHER",
            str(item.get("payment_method") or "OTHER").replace("_", " ").title(),
        )
        item["stage_label"] = PROJECT_PAYMENT_STAGE_LABELS.get(
            item.get("stage"), item.get("stage") or "Test project payment"
        )
        item["received_label"] = (
            item["received_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M")
            if item.get("received_at") else ""
        )
        item["voided_label"] = (
            item["voided_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M")
            if item.get("voided_at") else ""
        )
        item["is_void"] = bool(item.get("voided_at"))
        if not item["is_void"]:
            active_total += item["amount"]
        payments.append(item)

    final_price = _money_decimal(quote_item["pricing"].get("final_price"))
    deposit_required = _money_decimal(quote_item["pricing"].get("deposit_amount"))
    deposit_remaining = max(Decimal("0"), deposit_required - active_total)
    total_remaining = max(Decimal("0"), final_price - active_total)
    deposit_verified = deposit_required > 0 and active_total >= deposit_required
    fully_paid = final_price > 0 and active_total >= final_price
    sandbox_started_at = row[3] if row and enabled else None
    started = bool(sandbox_started_at)
    execution_plan = (row[5] if row and enabled and isinstance(row[5], dict) else {})
    execution_status = str(execution_plan.get("status") or "")
    if started and execution_status == "COMPLETED":
        state_label = "TEST: Completed"
    elif started:
        state_label = "TEST: In Progress"
    elif deposit_verified:
        state_label = "TEST: Deposit Paid / Ready to Start"
    else:
        state_label = "TEST: Awaiting Deposit"
    return {
        "enabled": enabled,
        "quotation_id": quote_item["id"],
        "quote": quote_item,
        "payments": payments,
        "total_paid": active_total,
        "final_price": final_price,
        "deposit_required": deposit_required,
        "deposit_remaining": deposit_remaining,
        "total_remaining": total_remaining,
        "deposit_verified": deposit_verified,
        "fully_paid": fully_paid,
        "started": started,
        "started_at": sandbox_started_at,
        "started_label": sandbox_started_at.astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if sandbox_started_at else "",
        "start_note": (row[4] or "") if row and enabled else "",
        "state_label": state_label,
        "currency": quote_item.get("currency") or "MWK",
        "can_enable": True,
    }


def _project_sandbox_enabled(project_id, quote_item=None):
    state = _project_sandbox_state(project_id, quote_item)
    return bool(state and state.get("enabled"))


def _project_deposit_invoice_pdf_bytes(invoice, quote_item, state):
    # One-page branded PDF. The invoice is intentionally generated from the locked
    # quotation snapshot rather than live costing, so an issued commercial record
    # cannot silently change after the client accepts it.
    PAGE_W, PAGE_H = 595.0, 842.0
    LEFT, RIGHT = 42.0, 553.0
    CONTENT_W = RIGHT - LEFT
    INK=(0.07,0.10,0.16); MUTED=(0.40,0.44,0.52); PURPLE=(0.39,0.08,0.35)
    PURPLE_DARK=(0.30,0.05,0.28); BORDER=(0.88,0.89,0.92); PALE=(0.97,0.96,0.98)
    GREEN=(0.02,0.47,0.30); BLUE_PALE=(0.94,0.97,1.0)
    commands=[]
    def fill(rgb): return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} rg"
    def stroke(rgb): return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} RG"
    def text_line(value,x,y,size=10,bold=False,rgb=INK):
        commands.append(fill(rgb)); font="F2" if bold else "F1"
        commands.append(f"BT /{font} {size:g} Tf {x:g} {y:g} Td ({_pdf_escape(_quote_latin1(value))}) Tj ET")
    def right_text(value,x,y,size=10,bold=False,rgb=INK):
        width=_pdf_text_width_points(_quote_latin1(value),size=size,bold=bold)
        text_line(value,x-width,y,size,bold,rgb)
    def wrap(value,size=9,width=CONTENT_W-28):
        return _business_pdf_wrap(_pdf_normalize_text(value or ""),size=size,width=width)
    logo_bytes=base64.b64decode(IBROWS_LOGO_JPEG_B64)
    logo_w=142.0; logo_h=logo_w*(IBROWS_LOGO_JPEG_HEIGHT/IBROWS_LOGO_JPEG_WIDTH)
    commands.append(f"q {logo_w:g} 0 0 {logo_h:g} {LEFT:g} {PAGE_H-55-logo_h:g} cm /Logo Do Q")
    text_line("DEPOSIT INVOICE", RIGHT-155, 792, 17, True, PURPLE_DARK)
    right_text(invoice["invoice_number"], RIGHT, 773, 8.8, True, INK)
    right_text(f"Quotation: {quote_item['quote_reference']} | Revision {quote_item.get('revision_no') or 1}", RIGHT, 758, 8.1, False, MUTED)
    right_text(f"Issued: {invoice['issued_label']}", RIGHT, 744, 8.1, False, MUTED)
    commands.append(stroke(PURPLE)); commands.append(f"2 w {LEFT:g} 718 m {RIGHT:g} 718 l S")

    y=688.0
    text_line("BILL TO",LEFT,y,8.3,True,PURPLE); y-=18
    client=quote_item.get("client") or {}
    for line in [client.get("organisation") or client.get("contact_name") or "Client", client.get("contact_name") or "", client.get("email") or "", client.get("phone") or ""]:
        if line:
            text_line(str(line),LEFT,y,9.5,False,INK); y-=14
    y-=7
    text_line("PROJECT",LEFT,y,8.3,True,PURPLE); y-=18
    text_line(quote_item.get("project_snapshot",{}).get("project_type") or "Digital project",LEFT,y,11.5,True,INK); y-=16
    ref=quote_item.get("project_snapshot",{}).get("discovery_reference") or ""
    if ref:
        text_line(f"Project discovery reference: {ref}",LEFT,y,8.2,False,MUTED); y-=16

    box_h=126.0; box_y=y-box_h
    commands.append(fill(PALE)); commands.append(f"{LEFT:g} {box_y:g} {CONTENT_W:g} {box_h:g} re f")
    text_line("AMOUNT DUE",LEFT+15,y-22,8.4,True,PURPLE)
    text_line(f"{invoice['currency']} {invoice['amount']:,.0f}",LEFT+15,y-53,23,True,PURPLE_DARK)
    text_line("Deposit required before project commencement",LEFT+15,y-74,8.5,False,MUTED)
    text_line("Total quotation value",LEFT+265,y-22,8.2,True,MUTED)
    right_text(f"{state['currency']} {state['final_price']:,.0f}",RIGHT-15,y-39,10.5,True,INK)
    text_line("Verified project ledger",LEFT+265,y-62,8.2,True,MUTED)
    right_text(f"{state['currency']} {state['total_paid']:,.0f}",RIGHT-15,y-79,10.5,True,INK)
    text_line("Invoice status",LEFT+265,y-100,8.2,True,MUTED)
    right_text(invoice.get("status_label") or invoice.get("status") or "Unpaid",RIGHT-15,y-117,10.5,True,GREEN if invoice.get("status")=='PAID' else INK)
    y=box_y-26

    text_line("PAYMENT REFERENCE",LEFT,y,8.3,True,PURPLE); y-=18
    for line in wrap(f"Please use {invoice['invoice_number']} or {quote_item['quote_reference']} as the payment reference where the channel allows it.",9.1):
        text_line(line,LEFT,y,9.1,False,INK); y-=13
    y-=7
    text_line("APPROVED PAYMENT CHANNELS",LEFT,y,8.3,True,PURPLE); y-=18
    for channel,number,account_name in IBROWS_PAYMENT_CHANNELS:
        label="Number" if channel in {"Airtel Money","TNM Mpamba"} else "Account"
        text_line(f"{channel}: {label} {number} - {account_name}",LEFT,y,8.7,False,INK); y-=13
    y-=7
    text_line("PAYMENT VERIFICATION",LEFT,y,8.3,True,PURPLE); y-=18
    notice="This invoice requests the agreed deposit only. Payment is treated as received only after IBROWS verifies it in the internal project ledger. A screenshot, copied transaction reference, customer message or payment claim by itself does not mark this invoice as paid or start the project."
    lines=wrap(notice,8.8,CONTENT_W-28)
    h=22+len(lines)*12
    commands.append(fill(BLUE_PALE)); commands.append(f"{LEFT:g} {y-h+8:g} {CONTENT_W:g} {h:g} re f")
    line_y=y-8
    for line in lines:
        text_line(line,LEFT+14,line_y,8.8,False,INK); line_y-=12
    y=y-h-12
    text_line("Project commencement",LEFT,y,8.2,True,MUTED); y-=15
    text_line("Begins only after the required deposit is verified and IBROWS explicitly starts the project.",LEFT,y,8.7,False,INK)

    commands.append(stroke(BORDER)); commands.append(f"0.7 w {LEFT:g} 77 m {RIGHT:g} 77 l S")
    text_line(f"{IBROWS_BUSINESS_TAGLINE} | {IBROWS_BUSINESS_EMAIL}",LEFT,56,7.8,False,MUTED)
    right_text("Page 1 of 1",RIGHT,56,7.8,False,MUTED)

    stream="\n".join(commands).encode("latin-1","strict")
    objects={
        1:b"<< /Type /Catalog /Pages 2 0 R >>",
        2:b"<< /Type /Pages /Kids [6 0 R] /Count 1 >>",
        3:b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        4:b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        5:(b"<< /Type /XObject /Subtype /Image "+f"/Width {IBROWS_LOGO_JPEG_WIDTH} /Height {IBROWS_LOGO_JPEG_HEIGHT} ".encode("ascii")+b"/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode "+f"/Length {len(logo_bytes)} >>\nstream\n".encode("ascii")+logo_bytes+b"\nendstream"),
        6:f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {PAGE_W:g} {PAGE_H:g}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo 5 0 R >> >> /Contents 7 0 R >>".encode("ascii"),
        7:b"<< /Length "+str(len(stream)).encode("ascii")+b" >>\nstream\n"+stream+b"\nendstream",
    }
    max_id=max(objects); out=bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"); offsets=[0]*(max_id+1)
    for obj_id in range(1,max_id+1):
        offsets[obj_id]=len(out); out.extend(f"{obj_id} 0 obj\n".encode("ascii")); out.extend(objects[obj_id]); out.extend(b"\nendobj\n")
    xref=len(out); out.extend(f"xref\n0 {max_id+1}\n".encode("ascii")); out.extend(b"0000000000 65535 f \n")
    for obj_id in range(1,max_id+1): out.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode("ascii"))
    out.extend(f"trailer\n<< /Size {max_id+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF".encode("ascii"))
    return bytes(out)


PROJECTS_ADMIN_TEMPLATE = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101828"><title>IBROWS Projects</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#101828;font-family:Arial,sans-serif;padding-bottom:36px}header{background:#101828;color:#fff;position:sticky;top:0;z-index:10}.wrap{max-width:980px;margin:auto;padding:0 14px}.top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 0}.brand{font-size:20px;font-weight:850}.nav{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.nav a{color:#fff;text-decoration:none;border:1px solid #667085;border-radius:8px;padding:7px 9px;font-size:11px;font-weight:800}h1{font-size:26px;margin:22px 0 4px}.sub{color:#667085;margin:0 0 14px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}.stat,.card{background:#fff;border-radius:13px;padding:14px;box-shadow:0 2px 8px rgba(0,0,0,.05)}.stat b{display:block;font-size:23px}.stat span{color:#667085;font-size:11px}.card{margin-bottom:12px;text-decoration:none;color:#101828;display:block}.row{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.title{font-size:17px;font-weight:850}.ref{font-size:11px;color:#667085;margin-top:3px}.badge{display:inline-block;border-radius:999px;background:#eef2f6;padding:5px 8px;font-size:10px;font-weight:850}.badge.ready{background:#ecfdf3;color:#067647}.badge.warn{background:#fff7e6;color:#b54708}.meta{margin-top:9px;color:#667085;font-size:12px;line-height:1.45}.empty{background:#fff;border-radius:13px;padding:26px;text-align:center;color:#667085}@media(max-width:650px){.top{display:block}.nav{justify-content:flex-start;margin-top:9px}.stats{grid-template-columns:1fr 1fr}.row{display:block}.badge{margin-top:7px}}</style></head><body>
<header><div class="wrap top"><div class="brand">IBROWS Project Discovery</div><div class="nav"><a href="{{ url_for('admin_inbox') }}">Inbox</a><a href="{{ url_for('admin_customers') }}">Customers</a><a href="{{ url_for('admin_leads') }}">Enquiries</a><a href="{{ url_for('admin_finance') }}">Finance</a></div></div></header>
<main class="wrap"><h1>Projects</h1><p class="sub">Smart Project Discovery assessments before costing and quotation.</p><div class="stats"><div class="stat"><b>{{ counts.total }}</b><span>Total assessments</span></div><div class="stat"><b>{{ counts.new }}</b><span>Awaiting review</span></div><div class="stat"><b>{{ counts.clarify }}</b><span>Need clarification</span></div><div class="stat"><b>{{ counts.costing }}</b><span>Ready for costing</span></div></div>
{% if projects %}{% for p in projects %}<a class="card" href="{{ url_for('admin_project_detail', project_id=p.id) }}"><div class="row"><div><div class="title">{{ p.organisation or p.contact_name }}</div><div class="ref">{{ p.reference }} · {{ p.project_type_label }}</div></div><div><span class="badge {% if p.status=='READY_FOR_COSTING' %}ready{% elif p.status=='NEEDS_CLARIFICATION' %}warn{% endif %}">{{ p.status_label }}</span></div></div><div class="meta">{{ p.contact_name }}{% if p.phone %} · {{ p.phone }}{% endif %}<br>{{ p.complexity }} complexity guide · {{ p.quotation_readiness }}{% if p.scope_confidence is not none %} · {{ p.scope_confidence }}% scope confidence{% endif %}<br>Submitted {{ p.submitted_label }}</div></a>{% endfor %}{% else %}<div class="empty">No submitted Project Discovery assessments yet.</div>{% endif %}</main></body></html>
"""


PROJECT_DETAIL_TEMPLATE = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#101828"><title>{{ project.reference }} · IBROWS</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#101828;font-family:Arial,sans-serif;padding-bottom:40px}.wrap{max-width:980px;margin:auto;padding:0 14px}header{background:#101828;color:#fff}.top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 0}.brand{font-size:19px;font-weight:850}.back{color:#fff;text-decoration:none;border:1px solid #667085;border-radius:8px;padding:7px 10px;font-size:11px;font-weight:850}h1{font-size:27px;margin:22px 0 4px}.sub{color:#667085;margin:0 0 13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.card{background:#fff;border-radius:13px;padding:15px;margin-bottom:12px;box-shadow:0 2px 8px rgba(0,0,0,.05)}.card h2{font-size:17px;margin:0 0 11px}.metric{background:#f9fafb;border-radius:10px;padding:10px}.metric small{color:#667085;font-weight:800}.metric b{display:block;margin-top:4px}.answer{padding:9px 0;border-bottom:1px solid #eaecf0}.answer:last-child{border:0}.label{font-size:11px;color:#667085;font-weight:850}.value{margin-top:3px;white-space:pre-wrap;line-height:1.45}.list{margin:0;padding-left:20px}.list li{margin:6px 0;line-height:1.4}.good{border-left:4px solid #12b76a}.warn{border-left:4px solid #f79009}.risk{border-left:4px solid #f04438}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #d0d5dd;background:#fff;color:#101828;border-radius:9px;padding:10px 12px;font-size:12px;font-weight:850;cursor:pointer}.primary{background:#101828;color:#fff;border-color:#101828}.actions{display:flex;gap:7px;flex-wrap:wrap}.status-grid{display:grid;grid-template-columns:1fr auto;gap:8px}select,input,textarea{width:100%;border:1px solid #d0d5dd;border-radius:9px;padding:10px;font-size:14px;background:#fff}textarea{min-height:95px;resize:vertical}.review{min-height:330px;font-family:monospace;font-size:12px;line-height:1.45}.activity{padding:8px 0;border-bottom:1px solid #eaecf0;font-size:12px}.activity:last-child{border:0}.activity small{color:#98a2b3}.note{background:#f9fafb;border-radius:9px;padding:9px;margin-bottom:7px;font-size:12px}.links{display:flex;gap:7px;flex-wrap:wrap}.publiclink{word-break:break-all;color:#175cd3;font-size:11px}.money{font-variant-numeric:tabular-nums}.costing-banner{border-left:4px solid #155eef;background:#eff8ff}.costing-banner p{margin:5px 0 0;line-height:1.4}.commercial{border-left:4px solid #12b76a}.payment-row{padding:10px 0;border-bottom:1px solid #eaecf0}.payment-row:last-child{border-bottom:0}.guard{background:#fffaeb;color:#7a2e0e;border-radius:9px;padding:10px;line-height:1.45;margin:9px 0}.success{background:#ecfdf3;color:#067647;border-radius:9px;padding:10px;line-height:1.45;margin:9px 0}.sandbox{border-left:4px solid #7f56d9;background:#f9f5ff}.sandbox-banner{background:#f4ebff;color:#53389e;border-radius:9px;padding:11px;line-height:1.45;margin:9px 0}.sandbox-test{background:#fff;border:2px dashed #9e77ed;border-radius:11px;padding:12px;margin:12px 0}.sandbox-void{opacity:.62;text-decoration:none;background:#f9fafb}.danger-btn{background:#fff;color:#b42318;border:1px solid #fda29b;border-radius:8px;padding:7px 9px;font-weight:800}.mini{font-size:11px;color:#667085}.money-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}@media(max-width:700px){.top{display:block}.back{display:inline-block;margin-top:9px}.grid,.money-grid{grid-template-columns:1fr}.status-grid{grid-template-columns:1fr}.actions .btn{width:100%}}</style></head><body>
<header><div class="wrap top"><div class="brand">IBROWS Project Discovery</div><a class="back" href="{{ url_for('admin_projects') }}">Back to Projects</a></div></header><main class="wrap"><h1>{{ project.organisation or project.contact_name }}</h1><p class="sub">{{ project.reference }} · {{ project.project_type_label }}</p>
<div class="grid"><section class="card"><h2>Assessment state</h2><div class="grid"><div class="metric"><small>Status</small><b>{{ project.status_label }}</b></div><div class="metric"><small>Complexity guide</small><b>{{ project.complexity }}</b></div><div class="metric"><small>Quotation readiness</small><b>{{ project.quotation_readiness }}</b></div><div class="metric"><small>Scope confidence guide</small><b>{% if project.scope_confidence is not none %}{{ project.scope_confidence }}%{% else %}—{% endif %}</b></div></div></section>
<section class="card"><h2>Client contact</h2><div class="answer"><div class="label">Contact</div><div class="value">{{ project.contact_name }}</div></div>{% if project.phone %}<div class="answer"><div class="label">Phone</div><div class="value">{{ project.phone }}</div></div>{% endif %}{% if project.email %}<div class="answer"><div class="label">Email</div><div class="value">{{ project.email }}</div></div>{% endif %}<div class="links" style="margin-top:10px">{% if whatsapp_url %}<a class="btn" href="{{ whatsapp_url }}" target="_blank" rel="noopener">WhatsApp Client</a>{% endif %}</div></section></div>
<section class="card"><h2>Workflow</h2>{% if project.status in commercial_statuses %}<div class="success"><strong>{{ project.status_label }}</strong><br>Commercial project statuses are controlled by quotation acceptance, verified ledger payments and the Start Project action. They cannot be faked from the generic status dropdown.</div>{% else %}<form method="POST" action="{{ url_for('admin_project_status', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><div class="status-grid"><select name="status">{% for value,label in statuses.items() %}<option value="{{ value }}" {% if project.status==value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select><button class="btn primary" type="submit">Update Status</button></div></form>{% endif %}<div class="actions" style="margin-top:9px"><form method="POST" action="{{ url_for('admin_project_analyze', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><button class="btn" type="submit">Refresh AI Scope Analysis</button></form></div></section>
{% if project.status in ['READY_FOR_COSTING','QUOTED','ACCEPTED','DECLINED'] %}<section class="card costing-banner"><h2>Internal costing & quotation</h2><p>This is staff-only. Internal component costs, margins and discounts are never shown on the public Project Discovery pages.</p><div class="actions" style="margin-top:10px"><a class="btn primary" href="{{ url_for('admin_project_costing', project_id=project.id) }}">Open Costing</a>{% if costing and costing.status=='APPROVED_FOR_QUOTE' %}<a class="btn" href="{{ url_for('admin_project_quotation_preview', project_id=project.id) }}">Preview Quotation</a>{% endif %}</div></section>{% endif %}
{% if quotations %}<section class="card"><h2>Quotation history</h2>{% for q in quotations %}<div class="answer"><div class="label"><a href="{{ url_for('admin_project_quotation_detail', project_id=project.id, quotation_id=q.id) }}">{{ q.quote_reference }}</a> · Revision {{ q.revision_no }}</div><div class="value"><strong>{{ q.status_label }}</strong><br>Issued {{ q.issued_label }} · Valid until {{ q.valid_label }}</div></div>{% endfor %}</section>{% endif %}
{% if commercial_state %}<section class="card commercial"><h2>Deposit & project start</h2>
<div class="guard"><strong>Verified ledger only.</strong> Record a live payment here only after IBROWS has independently verified the money was received. Customer messages, screenshots, copied references or claims do not change payment status.</div>
<div class="money-grid"><div class="metric"><small>Accepted investment</small><b>{{ commercial_state.currency }} {{ '{:,.0f}'.format(commercial_state.final_price) }}</b></div><div class="metric"><small>Required deposit</small><b>{{ commercial_state.currency }} {{ '{:,.0f}'.format(commercial_state.deposit_required) }}</b></div><div class="metric"><small>Verified ledger total</small><b>{{ commercial_state.currency }} {{ '{:,.0f}'.format(commercial_state.total_paid) }}</b></div><div class="metric"><small>Deposit remaining</small><b>{{ commercial_state.currency }} {{ '{:,.0f}'.format(commercial_state.deposit_remaining) }}</b></div><div class="metric"><small>Project balance</small><b>{{ commercial_state.currency }} {{ '{:,.0f}'.format(commercial_state.total_remaining) }}</b></div><div class="metric"><small>Deposit invoice</small><b>{{ commercial_state.invoice.status_label if commercial_state.invoice else 'Not generated' }}</b></div></div>
{% if commercial_state.invoice %}<div class="actions" style="margin-top:10px"><a class="btn primary" href="{{ url_for('admin_project_deposit_invoice_pdf', project_id=project.id) }}">Download Deposit Invoice</a><a class="btn" href="{{ url_for('admin_finance') }}">Open Finance</a></div><div class="mini" style="margin-top:8px">{{ commercial_state.invoice.invoice_number }} · Issued {{ commercial_state.invoice.issued_label }}</div>{% endif %}

{% if sandbox_state and sandbox_state.enabled %}
<div class="sandbox-test"><div class="sandbox-banner"><strong>🧪 SANDBOX / TEST PAYMENT MODE</strong><br>Everything inside this test box is isolated. Test payments do <strong>not</strong> affect Finance, the live verified ledger, the live deposit invoice, the quotation, or the real project status. The live project remains {{ project.status_label }} until genuine verified payment is recorded outside Sandbox.</div>
<div class="money-grid"><div class="metric"><small>Test status</small><b>{{ sandbox_state.state_label }}</b></div><div class="metric"><small>Test ledger total</small><b>{{ sandbox_state.currency }} {{ '{:,.0f}'.format(sandbox_state.total_paid) }}</b></div><div class="metric"><small>Test deposit remaining</small><b>{{ sandbox_state.currency }} {{ '{:,.0f}'.format(sandbox_state.deposit_remaining) }}</b></div><div class="metric"><small>Test project balance</small><b>{{ sandbox_state.currency }} {{ '{:,.0f}'.format(sandbox_state.total_remaining) }}</b></div></div>
{% if sandbox_state.total_remaining > 0 %}<h3 style="margin-bottom:4px">Record test payment</h3><form method="POST" action="{{ url_for('admin_project_sandbox_payment_record', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><div class="grid"><div><label class="label">Test amount ({{ sandbox_state.currency }})</label><input type="number" name="amount" min="1" step="0.01" max="{{ sandbox_state.total_remaining }}" required placeholder="e.g. 200000"></div><div><label class="label">Payment stage</label><select name="stage">{% for value,label in payment_stages.items() %}<option value="{{ value }}" {% if (not sandbox_state.deposit_verified and value=='DEPOSIT') or (sandbox_state.deposit_verified and not sandbox_state.fully_paid and value=='MILESTONE_2') %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div><label class="label">Payment method</label><select name="payment_method">{% for value,label in payment_methods.items() %}<option value="{{ value }}">{{ label }}</option>{% endfor %}</select></div><div><label class="label">Test reference (optional)</label><input name="reference" maxlength="180" placeholder="e.g. TEST-PARTIAL-1"></div></div><label class="label">Test note (optional)</label><textarea name="payment_note" maxlength="1000" placeholder="Simulation only — no money was received"></textarea><button class="btn primary" type="submit" style="margin-top:8px">Record Test Payment</button></form>{% endif %}
{% if sandbox_state.payments %}<h3>Sandbox payment history</h3>{% for payment in sandbox_state.payments %}<div class="payment-row {% if payment.is_void %}sandbox-void{% endif %}"><strong>{{ payment.currency }} {{ '{:,.0f}'.format(payment.amount) }}</strong> · {{ payment.stage_label }}{% if payment.is_void %} · <strong>VOID</strong>{% endif %}<br><span class="mini">{{ payment.method_label }}{% if payment.reference %} · Ref {{ payment.reference }}{% endif %} · {{ payment.received_label }}</span>{% if payment.payment_note %}<div class="mini">{{ payment.payment_note }}</div>{% endif %}{% if payment.is_void %}<div class="mini">Voided {{ payment.voided_label }}{% if payment.void_reason %} · {{ payment.void_reason }}{% endif %}</div>{% else %}<form method="POST" action="{{ url_for('admin_project_sandbox_payment_void', project_id=project.id, payment_id=payment.id) }}" data-confirm="Void this TEST payment? No real Finance records are affected." style="margin-top:7px"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input name="void_reason" maxlength="300" required placeholder="Reason for test void (required)"><button class="danger-btn" type="submit">Void Test Payment</button></form>{% endif %}</div>{% endfor %}{% endif %}
{% if sandbox_state.started %}<div class="success"><strong>TEST project started.</strong><br>Simulated start {{ sandbox_state.started_label }}{% if sandbox_state.start_note %}<br>{{ sandbox_state.start_note }}{% endif %}<br><span class="mini">This did not create a live project execution record.</span><div class="actions" style="margin-top:9px"><a class="btn primary" href="{{ url_for('admin_project_execution', project_id=project.id, mode='sandbox') }}">Open TEST Execution Workspace</a></div></div>{% elif sandbox_state.deposit_verified %}<div class="success"><strong>TEST deposit threshold reached.</strong> You can now simulate the controlled project-start action without affecting the live project.</div><form method="POST" action="{{ url_for('admin_project_sandbox_start', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label class="label">Test start note (optional)</label><textarea name="start_note" maxlength="1200" placeholder="Simulation only"></textarea><label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px"><input type="checkbox" name="confirm_start" value="1" required style="width:auto;margin-top:3px"> <span>I understand this starts only the sandbox simulation and does not start real work.</span></label><button class="btn primary" type="submit" style="margin-top:8px">Simulate Start Project</button></form>{% else %}<div class="guard"><strong>TEST awaiting deposit.</strong> The simulated Start Project action remains locked until sandbox payments reach the required deposit.</div>{% endif %}
<div class="actions" style="margin-top:12px"><form method="POST" action="{{ url_for('admin_project_sandbox_reset', project_id=project.id) }}" data-confirm="Reset all sandbox payments and the simulated project start? Live records will remain untouched."><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="confirm_reset" value="1"><button class="btn" type="submit">Reset Sandbox</button></form><form method="POST" action="{{ url_for('admin_project_sandbox_exit', project_id=project.id) }}" data-confirm="Exit Sandbox and clear all test entries? Live records will remain untouched."><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="confirm_exit" value="1"><button class="danger-btn" type="submit">Exit & Clear Sandbox</button></form></div></div>
{% else %}
{% if commercial_state.total_paid == 0 and not commercial_state.execution %}<section class="sandbox"><div class="sandbox-banner"><strong>Need to test the payment workflow?</strong><br>Enable Sandbox to simulate partial payment → full deposit → project start → voiding without changing Finance, the live invoice, or the real project status.</div><form method="POST" action="{{ url_for('admin_project_sandbox_enable', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" name="confirm_sandbox" value="1" required style="width:auto;margin-top:3px"> <span>I understand Sandbox records are test-only and do not represent money received.</span></label><button class="btn" type="submit" style="margin-top:8px">Enable Sandbox / Test Mode</button></form></section>{% endif %}
{% if commercial_state.total_remaining > 0 %}<h3 style="margin-bottom:4px">Record verified payment</h3><form method="POST" action="{{ url_for('admin_project_payment_record', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="payment_request_token" value="{{ project_payment_token }}"><div class="grid"><div><label class="label">Amount ({{ commercial_state.currency }})</label><input type="number" name="amount" min="1" step="0.01" max="{{ commercial_state.total_remaining }}" required placeholder="e.g. 425000"></div><div><label class="label">Payment stage</label><select name="stage">{% for value,label in payment_stages.items() %}<option value="{{ value }}" {% if not commercial_state.deposit_verified and value=='DEPOSIT' %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div><label class="label">Payment method</label><select name="payment_method">{% for value,label in payment_methods.items() %}<option value="{{ value }}">{{ label }}</option>{% endfor %}</select></div><div><label class="label">Reference (optional)</label><input name="reference" maxlength="180" placeholder="Bank/mobile-money reference"></div></div><label class="label">Internal payment note (optional)</label><textarea name="payment_note" maxlength="1000" placeholder="How IBROWS independently verified the payment"></textarea><button class="btn primary" type="submit" style="margin-top:8px">Record Verified Payment</button></form>{% endif %}
{% if commercial_state.payments %}<h3>Verified payment ledger</h3>{% for payment in commercial_state.payments %}<div class="payment-row"><strong>{{ payment.currency }} {{ '{:,.0f}'.format(payment.amount) }}</strong> · {{ payment.stage_label }}<br><span class="mini">{{ payment.method_label }}{% if payment.reference %} · Ref {{ payment.reference }}{% endif %} · {{ payment.received_label }}</span>{% if payment.payment_note %}<div class="mini">{{ payment.payment_note }}</div>{% endif %}<form method="POST" action="{{ url_for('admin_project_payment_void', project_id=project.id, payment_id=payment.id) }}" data-confirm="Void this verified payment? This will remove it from project and finance totals but preserve an audit record." style="margin-top:7px"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input name="void_reason" maxlength="300" required placeholder="Reason for voiding (required)"><button class="danger-btn" type="submit">Void Payment</button></form></div>{% endfor %}{% endif %}
{% if commercial_state.execution %}<div class="success"><strong>Project started.</strong><br>Started {{ commercial_state.execution.started_label }}{% if commercial_state.execution.start_note %}<br>{{ commercial_state.execution.start_note }}{% endif %}<div class="actions" style="margin-top:9px"><a class="btn primary" href="{{ url_for('admin_project_execution', project_id=project.id) }}">Open Project Execution</a></div></div>{% elif commercial_state.deposit_verified %}<div class="success"><strong>Deposit threshold verified.</strong> Payment alone does not start work. Use the controlled action below when IBROWS is ready to commence.</div><form method="POST" action="{{ url_for('admin_project_start', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label class="label">Start note (optional)</label><textarea name="start_note" maxlength="1200" placeholder="Kick-off date, handover note, or internal commencement detail"></textarea><label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px"><input type="checkbox" name="confirm_start" value="1" required style="width:auto;margin-top:3px"> <span>I confirm the required deposit is verified and IBROWS is intentionally starting this project.</span></label><button class="btn primary" type="submit" style="margin-top:8px">Start Project</button></form>{% else %}<div class="guard"><strong>Awaiting deposit.</strong> The Start Project action remains locked until the verified project ledger reaches the required deposit.</div>{% endif %}
{% endif %}</section>{% endif %}
<section class="card"><h2>Customer's original answers</h2>{% for label,value in answer_rows %}<div class="answer"><div class="label">{{ label }}</div><div class="value">{{ value }}</div></div>{% endfor %}</section>
<section class="card"><h2>IBROWS AI scope analysis</h2><p style="line-height:1.5">{{ project.ai_summary or 'No analysis available yet.' }}</p></section>
<div class="grid"><section class="card good"><h2>Required scope</h2><ul class="list">{% for x in project.ai_required_features %}<li>{{ x }}</li>{% else %}<li>None identified yet.</li>{% endfor %}</ul></section><section class="card"><h2>Recommended — not automatic scope</h2><ul class="list">{% for x in project.ai_recommended_features %}<li>{{ x }}</li>{% else %}<li>None identified.</li>{% endfor %}</ul></section><section class="card"><h2>Future / optional</h2><ul class="list">{% for x in project.ai_future_enhancements %}<li>{{ x }}</li>{% else %}<li>None identified.</li>{% endfor %}</ul></section><section class="card warn"><h2>Missing information</h2><ul class="list">{% for x in project.ai_missing_information %}<li>{{ x }}</li>{% else %}<li>No major missing items identified by the current analysis.</li>{% endfor %}</ul></section><section class="card risk"><h2>Quotation risk flags</h2><ul class="list">{% for x in project.ai_risk_flags %}<li>{{ x }}</li>{% else %}<li>No specific risk flags identified.</li>{% endfor %}</ul></section><section class="card"><h2>Cost drivers</h2><ul class="list">{% for x in project.ai_cost_drivers %}<li>{{ x }}</li>{% else %}<li>No special cost drivers identified.</li>{% endfor %}</ul></section><section class="card"><h2>Scope reducers</h2><ul class="list">{% for x in project.ai_scope_reducers %}<li>{{ x }}</li>{% else %}<li>No scope reducers identified yet.</li>{% endfor %}</ul></section></div>
<section class="card"><h2>Internal note</h2><form method="POST" action="{{ url_for('admin_project_note', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><textarea name="note" maxlength="2000" required placeholder="Private IBROWS note — never shown to the client."></textarea><button class="btn primary" type="submit" style="margin-top:8px">Add Note</button></form>{% for note in notes %}<div class="note"><strong>{{ note.created_label }}</strong><br>{{ note.note_text }}</div>{% endfor %}</section>
<section class="card"><h2>Prepare for ChatGPT review</h2><p class="sub">Long-press/select all on Android and copy this brief into your IBROWS project chat for a deeper quotation review.</p><textarea class="review" readonly>{{ review_brief }}</textarea></section>
<section class="card"><h2>Client update link</h2><p class="sub">Use this only when you intentionally want the client to reopen/update the assessment. The long token protects the draft from casual access.</p><div class="publiclink">{{ update_url }}</div></section>
<section class="card"><h2>Activity</h2>{% for item in activity %}<div class="activity"><strong>{{ item.event_type }}</strong> · {{ item.description }}<br><small>{{ item.created_label }}</small></div>{% else %}<div class="sub">No activity recorded.</div>{% endfor %}</section>
</main></body></html>
"""


@app.route("/admin/projects", methods=["GET"])
@admin_required
def admin_projects():
    projects = _get_all_project_assessments()
    counts = {
        "total": len(projects),
        "new": sum(1 for p in projects if p["status"] == "NEW"),
        "clarify": sum(1 for p in projects if p["status"] == "NEEDS_CLARIFICATION"),
        "costing": sum(1 for p in projects if p["status"] == "READY_FOR_COSTING"),
    }
    return render_template_string(PROJECTS_ADMIN_TEMPLATE, projects=projects, counts=counts), 200


@app.route("/admin/projects/<int:project_id>", methods=["GET"])
@admin_required
def admin_project_detail(project_id):
    project = _get_project_by_id(project_id)
    if not project or project.get("status") == "DRAFT":
        abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT event_type, description, created_at FROM project_activity WHERE project_id=%s ORDER BY created_at DESC, id DESC LIMIT 100", (project_id,))
            activity_rows = cur.fetchall()
            cur.execute("SELECT note_text, created_at FROM project_notes WHERE project_id=%s ORDER BY created_at DESC, id DESC LIMIT 30", (project_id,))
            note_rows = cur.fetchall()
    activity = [{
        "event_type": r[0], "description": r[1],
        "created_label": r[2].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if r[2] else "",
    } for r in activity_rows]
    notes = [{
        "note_text": r[0],
        "created_label": r[1].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if r[1] else "",
    } for r in note_rows]
    commercial_state = _project_commercial_state(project_id)
    if commercial_state and project.get("status") != commercial_state.get("project_status"):
        project = _get_project_by_id(project_id) or project
    public_base = LEAD_DASHBOARD_URL.rsplit('/admin/leads', 1)[0]
    update_url = f"{public_base}/project-discovery/{project['public_token']}/step/2"
    return render_template_string(
        PROJECT_DETAIL_TEMPLATE,
        project=project, answer_rows=_project_answer_rows(project), statuses=PROJECT_MANUAL_STATUSES,
        commercial_statuses=PROJECT_COMMERCIAL_STATUSES,
        csrf_token=get_csrf_token(), review_brief=_project_review_brief(project),
        whatsapp_url=_project_phone_whatsapp_url(project), update_url=update_url,
        activity=activity, notes=notes, costing=_get_project_costing(project),
        quotations=_list_project_quotations(project_id),
        commercial_state=commercial_state,
        sandbox_state=_project_sandbox_state(project_id, commercial_state.get("quote") if commercial_state else None) if commercial_state else None,
        payment_stages=PROJECT_PAYMENT_STAGE_LABELS, payment_methods=PAYMENT_METHODS,
        project_payment_token=secrets.token_urlsafe(24),
    ), 200


@app.route("/admin/projects/<int:project_id>/status", methods=["POST"])
@admin_required
def admin_project_status(project_id):
    validate_csrf()
    status = _project_clean(request.form.get("status"), 40).upper()
    allowed = set(PROJECT_MANUAL_STATUSES)
    if status not in allowed:
        abort(400)
    project = _get_project_by_id(project_id)
    if not project:
        abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("UPDATE project_assessments SET status=%s, updated_at=NOW() WHERE id=%s", (status, project_id))
            _project_activity_insert(cur, project_id, "STATUS", f"Project Discovery status changed to {PROJECT_DISCOVERY_STATUSES[status]}.")
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id))


@app.route("/admin/projects/<int:project_id>/analyze", methods=["POST"])
@admin_required
def admin_project_analyze(project_id):
    validate_csrf()
    project = _get_project_by_id(project_id)
    if not project:
        abort(404)
    analyze_project_assessment(project_id)
    return redirect(url_for("admin_project_detail", project_id=project_id))


@app.route("/admin/projects/<int:project_id>/note", methods=["POST"])
@admin_required
def admin_project_note(project_id):
    validate_csrf()
    note = _project_clean(request.form.get("note"), 2000)
    if not note:
        abort(400)
    project = _get_project_by_id(project_id)
    if not project:
        abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("INSERT INTO project_notes (project_id, note_text) VALUES (%s, %s)", (project_id, note))
            _project_activity_insert(cur, project_id, "NOTE", "Internal project note added.")
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id))



PROJECT_COSTING_TEMPLATE = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101828"><title>Costing · {{ project.reference }}</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#101828;font-family:Arial,sans-serif;padding-bottom:40px}.wrap{max-width:980px;margin:auto;padding:0 14px}header{background:#101828;color:#fff}.top{display:flex;justify-content:space-between;align-items:center;padding:15px 0}.brand{font-size:19px;font-weight:850}.back{color:#fff;text-decoration:none;border:1px solid #667085;border-radius:8px;padding:8px 10px;font-size:12px;font-weight:800}h1{font-size:27px;margin:22px 0 4px}.sub{color:#667085}.card{background:#fff;border-radius:13px;padding:15px;margin:12px 0;box-shadow:0 2px 8px rgba(0,0,0,.05)}.card h2{margin:0 0 10px;font-size:17px}.notice{border-left:4px solid #155eef;background:#eff8ff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.line{display:grid;grid-template-columns:auto 1fr 130px 155px;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #eaecf0}.line:last-child{border-bottom:0}input,select,textarea{width:100%;border:1px solid #d0d5dd;border-radius:9px;padding:10px;background:#fff;font-size:14px}input[type=checkbox]{width:auto}.money{font-variant-numeric:tabular-nums}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #d0d5dd;background:#fff;color:#101828;border-radius:9px;padding:10px 12px;font-size:12px;font-weight:850;cursor:pointer}.primary{background:#101828;color:#fff;border-color:#101828}.approve{background:#05603a;border-color:#05603a;color:#fff}.actions{display:flex;gap:8px;flex-wrap:wrap}.metric{background:#f9fafb;border-radius:9px;padding:10px}.metric small{display:block;color:#667085;font-weight:800}.metric b{display:block;margin-top:4px;font-size:17px}.hint{font-size:12px;color:#667085;line-height:1.45}textarea{min-height:110px;resize:vertical}.required{color:#b42318;font-size:11px;font-weight:800}.save-state{border-radius:10px;padding:11px 13px;margin:12px 0;font-size:13px;font-weight:850}.save-state.saved{background:#ecfdf3;color:#05603a;border:1px solid #abefc6}.save-state.unsaved{background:#fffaeb;color:#b54708;border:1px solid #fedf89}.save-state.saving{background:#eff8ff;color:#175cd3;border:1px solid #b2ddff}@media(max-width:720px){.top{display:block}.back{display:inline-block;margin-top:8px}.grid{grid-template-columns:1fr}.line{grid-template-columns:auto 1fr}.line .amount,.line .scope{grid-column:2}.actions .btn,.actions button{width:100%}}</style></head><body>
<header><div class="wrap top"><div class="brand">IBROWS Internal Costing</div><a class="back" href="{{ url_for('admin_project_detail', project_id=project.id) }}">Back to Project</a></div></header><main class="wrap"><h1>{{ project.organisation or project.contact_name }}</h1><p class="sub">{{ project.reference }} · {{ project.project_type_label }} · Staff only</p>
<section class="card notice"><h2>Costing guardrail</h2><div class="hint">This screen is internal. Required scope comes from the approved discovery record; recommended and optional work must not be silently added to the client's paid scope. Commercial price remains a human decision.</div></section>
<div id="costingSaveState" class="save-state saved">{% if imported_flash %}✓ Imported figures applied and saved.{% elif saved_flash %}✓ Internal costing saved successfully.{% elif costing.line_items %}✓ Saved costing record loaded.{% else %}No costing has been saved yet.{% endif %}</div>
<section class="card"><h2>Import a price sheet</h2><div class="hint">Mobile-friendly option: upload a CSV, TXT or XLSX sheet and IBROWS will match recognised component names to the fields below. Nothing is saved until you review the import and press Apply.</div><form method="POST" enctype="multipart/form-data" action="{{ url_for('admin_project_costing_import', project_id=project.id) }}" style="margin-top:10px"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="file" name="price_sheet" accept=".csv,.txt,.xlsx" required><div class="actions" style="margin-top:9px"><button class="btn primary" type="submit">Upload & Review Price Sheet</button><a class="btn" href="{{ url_for('admin_project_costing_template', project_id=project.id) }}">Download Cost Sheet Template</a></div></form></section>
<form id="costingForm" method="POST" action="{{ url_for('admin_project_costing', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}">
<section class="card"><h2>Cost components</h2><div class="hint">Tick only components you are actually costing. Amounts below are internal working costs/effort values in MWK.</div>
{% for key,label in components %}{% set existing = item_map.get(key) %}<div class="line"><input type="checkbox" name="include_{{ key }}" value="1" {% if existing %}checked{% endif %}><div><strong>{{ label }}</strong></div><div class="amount"><input type="number" min="0" step="1000" name="amount_{{ key }}" placeholder="MWK" value="{{ existing.amount if existing else '' }}"></div><div class="scope"><select name="scope_{{ key }}"><option value="REQUIRED" {% if existing and existing.scope_type=='REQUIRED' %}selected{% endif %}>Required</option><option value="RECOMMENDED" {% if existing and existing.scope_type=='RECOMMENDED' %}selected{% endif %}>Recommended</option><option value="OPTIONAL" {% if existing and existing.scope_type=='OPTIONAL' %}selected{% endif %}>Optional/Future</option></select></div></div>{% endfor %}
<div class="line"><input type="checkbox" disabled><div><input name="other_label" placeholder="Additional/custom component" value="{{ custom_other.label if custom_other else '' }}"></div><div class="amount"><input type="number" min="0" step="1000" name="other_amount" placeholder="MWK" value="{{ custom_other.amount if custom_other else '' }}"></div><div class="scope"><select name="other_scope"><option value="REQUIRED">Required</option><option value="RECOMMENDED">Recommended</option><option value="OPTIONAL">Optional/Future</option></select></div></div>
</section>
<section class="card"><h2>Commercial decision</h2><div class="grid"><label>Commercial price (before discount)<input type="number" min="0" step="1000" name="commercial_price" value="{{ costing.commercial_price }}"></label><label>Discount<input type="number" min="0" step="1000" name="discount_amount" value="{{ costing.discount_amount }}"></label><label>Deposit %<input type="number" min="0" max="100" step="1" name="deposit_percent" value="{{ costing.deposit_percent }}"></label><label>Monthly support<input type="number" min="0" step="1000" name="monthly_support" value="{{ costing.monthly_support }}"></label></div></section>
<section class="card"><h2>Assumptions & commercial terms</h2><label>Assumptions<textarea name="assumptions">{{ costing.assumptions }}</textarea></label><label>Exclusions<textarea name="exclusions">{{ costing.exclusions }}</textarea></label><label>Payment terms<textarea name="payment_terms">{{ costing.payment_terms }}</textarea></label><label>Third-party costs<textarea name="third_party_costs">{{ costing.third_party_costs }}</textarea></label></section>
<div class="actions"><button class="btn primary" id="saveCostingButton" type="submit">{% if saved_flash %}Saved ✓{% else %}Save Internal Costing{% endif %}</button>{% if costing.status=='APPROVED_FOR_QUOTE' %}<a class="btn" href="{{ url_for('admin_project_quotation_preview', project_id=project.id) }}">Preview Quotation</a>{% endif %}</div></form>
{% if costing.line_items %}<section class="card"><h2>Current totals</h2><div class="grid"><div class="metric"><small>Internal estimate</small><b class="money">MK{{ '{:,.0f}'.format(costing.internal_estimate) }}</b></div><div class="metric"><small>Client price after discount</small><b class="money">MK{{ '{:,.0f}'.format(costing.final_price) }}</b></div><div class="metric"><small>Deposit</small><b class="money">MK{{ '{:,.0f}'.format(costing.deposit_amount) }}</b></div><div class="metric"><small>Monthly support</small><b class="money">MK{{ '{:,.0f}'.format(costing.monthly_support) }}</b></div></div><div class="actions" style="margin-top:12px"><form method="POST" action="{{ url_for('admin_project_costing_approve', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><button class="btn approve" type="submit">Approve for Quotation Draft</button></form></div>{% if error %}<p class="required">{{ error }}</p>{% endif %}</section>{% endif %}
<script src="{{ url_for('admin_costing_ui_js') }}"></script></main></body></html>
"""

PROJECT_QUOTATION_PREVIEW_TEMPLATE = """
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ costing.quote_reference }} · IBROWS Quotation Preview</title><style>*{box-sizing:border-box}body{margin:0;background:#edf1f5;color:#101828;font-family:Arial,sans-serif}.sheet{max-width:850px;margin:24px auto;background:#fff;padding:34px;border-radius:10px;box-shadow:0 4px 18px rgba(0,0,0,.08)}.top{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #101828;padding-bottom:18px}.brand{font-size:25px;font-weight:900}.muted{color:#667085}.section{margin-top:24px}.section h2{font-size:16px;border-bottom:1px solid #eaecf0;padding-bottom:7px}.price{font-size:28px;font-weight:900}.moneyline{margin-top:7px;font-weight:750}.included-note{background:#ecfdf3;border-left:4px solid #12b76a;padding:10px 12px;border-radius:8px;line-height:1.45}.optional-note{background:#fffaeb;border-left:4px solid #f79009;padding:10px 12px;border-radius:8px;line-height:1.45}.scope{padding-left:20px}.scope li{margin:6px 0}.box{background:#f9fafb;padding:12px;border-radius:9px;white-space:pre-wrap;line-height:1.5}.actions,.issue{max-width:850px;margin:18px auto;display:flex;gap:8px;flex-wrap:wrap}.issue{background:#fff;padding:16px;border-radius:10px}.issue form{width:100%}.issue label{display:block;margin:8px 0;font-weight:700}.issue select{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:8px}.btn{display:inline-flex;justify-content:center;text-decoration:none;background:#101828;color:#fff;border:0;padding:10px 13px;border-radius:8px;font-weight:800;font-size:12px;cursor:pointer}.issuebtn{background:#05603a}.notice{background:#fffaeb;border-left:4px solid #f79009;padding:10px 12px;border-radius:8px;line-height:1.45;width:100%}@media(max-width:700px){.sheet{margin:0;border-radius:0;padding:20px}.top{display:block}.actions,.issue{padding:0 12px}.issue{padding-top:14px;padding-bottom:14px}.btn{width:100%;text-align:center}}@media print{body{background:#fff}.actions,.issue{display:none}.sheet{box-shadow:none;margin:0;max-width:none}}</style></head><body><div class="actions"><a class="btn" href="{{ url_for('admin_project_costing', project_id=project.id) }}">Back to Costing</a></div>
{% if issued_quote %}<div class="issue"><div class="notice">This quotation reference has already been issued and locked as an immutable client version.</div><a class="btn issuebtn" href="{{ url_for('admin_project_quotation_detail', project_id=project.id, quotation_id=issued_quote.id) }}">Open Issued Quotation</a></div>{% else %}<div class="issue"><form method="POST" action="{{ url_for('admin_project_quotation_issue', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><label>Quotation validity<select name="valid_days"><option value="7">7 days</option><option value="14" selected>14 days</option><option value="30">30 days</option></select></label><label><input type="checkbox" name="confirm_issue" value="1" required> I confirm the scope, investment, assumptions, exclusions and payment terms are approved for client issue.</label><button class="btn issuebtn" type="submit">Issue Quotation</button></form></div>{% endif %}
<main class="sheet"><div class="top"><div><div class="brand">IBROWS Enterprise</div><div class="muted">Kupanga zofanana, mosiyana</div><div class="muted">Lilongwe, Malawi · {{ business_email }}</div></div><div><strong>QUOTATION PREVIEW</strong><br>{{ costing.quote_reference }}<br><span class="muted">Not yet sent to client</span></div></div>
<div class="section"><strong>Prepared for</strong><br>{{ project.organisation or project.contact_name }}<br>{{ project.contact_name }}{% if project.email %}<br>{{ project.email }}{% endif %}{% if project.phone %}<br>{{ project.phone }}{% endif %}</div>
<div class="section"><h2>Project</h2><strong>{{ project.project_type_label }}</strong><p>{{ project.ai_summary }}</p></div>
<div class="section"><h2>Included scope</h2><ul class="scope">{% for item in costing.line_items if item.scope_type=='REQUIRED' %}<li>{{ item.label }}</li>{% else %}{% for item in project.ai_required_features %}<li>{{ item }}</li>{% endfor %}{% endfor %}</ul></div>
{% set recs = costing.line_items | selectattr('scope_type','equalto','RECOMMENDED') | list %}{% if recs %}<div class="section"><h2>Recommended additions included in this quotation</h2><div class="included-note">These items were reviewed and explicitly included by IBROWS in this quotation draft; they are not being silently added to scope.</div><ul class="scope">{% for item in recs %}<li>{{ item.label }}</li>{% endfor %}</ul></div>{% endif %}
{% set opts = costing.line_items | selectattr('scope_type','equalto','OPTIONAL') | list %}{% if opts %}<div class="section"><h2>Optional / future enhancements</h2><div class="optional-note">These items are shown for future consideration and are not part of the core delivery unless the final issued quotation expressly includes them.</div><ul class="scope">{% for item in opts %}<li>{{ item.label }}</li>{% endfor %}</ul></div>{% endif %}
<div class="section"><h2>Investment</h2><div class="price">MK{{ '{:,.0f}'.format(costing.final_price) }}</div><div class="moneyline">Deposit: {{ '{:,.0f}'.format(costing.deposit_percent) }}% · MK{{ '{:,.0f}'.format(costing.deposit_amount) }}</div><div class="moneyline">Balance after deposit: MK{{ '{:,.0f}'.format(costing.balance_after_deposit) }}</div>{% if costing.monthly_support > 0 %}<div class="moneyline">Ongoing support: MK{{ '{:,.0f}'.format(costing.monthly_support) }} / month</div>{% endif %}</div>
<div class="section"><h2>Payment terms</h2><div class="box">{{ costing.payment_terms }}</div></div><div class="section"><h2>Assumptions</h2><div class="box">{{ costing.assumptions or 'None stated.' }}</div></div><div class="section"><h2>Exclusions</h2><div class="box">{{ costing.exclusions or 'None stated.' }}</div></div><div class="section"><h2>Third-party costs</h2><div class="box">{{ costing.third_party_costs or 'Not stated.' }}</div></div><div class="section muted">This is an internal preview. It becomes a locked client quotation only after IBROWS explicitly issues it.</div></main></body></html>
"""

