@app.route("/admin/projects/<int:project_id>/costing", methods=["GET", "POST"])
@admin_required
def admin_project_costing(project_id):
    project = _get_project_by_id(project_id)
    if not project or project.get("status") == "DRAFT":
        abort(404)
    if project.get("status") not in {"READY_FOR_COSTING", "QUOTED", "ACCEPTED", "DECLINED"}:
        return redirect(url_for("admin_project_detail", project_id=project_id))
    if request.method == "POST":
        validate_csrf()
        _save_project_costing(project, request.form)
        return redirect(url_for("admin_project_costing", project_id=project_id, saved=1))
    costing = _costing_view(_get_project_costing(project))
    item_map = {x.get("key"): x for x in costing.get("line_items", []) if x.get("key") and x.get("key") != "custom_other"}
    custom_other = next((x for x in costing.get("line_items", []) if x.get("key") == "custom_other"), None)
    return render_template_string(
        PROJECT_COSTING_TEMPLATE,
        project=project, costing=costing, components=PROJECT_COST_COMPONENTS,
        item_map=item_map, custom_other=custom_other,
        csrf_token=get_csrf_token(), error="",
        saved_flash=(request.args.get("saved") == "1"),
        imported_flash=(request.args.get("imported") == "1"),
    ), 200


