@app.route("/admin/projects/<int:project_id>/sandbox/enable", methods=["POST"])
@admin_required
def admin_project_sandbox_enable(project_id):
    validate_csrf()
    if request.form.get("confirm_sandbox") != "1":
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    if not quote_item:
        abort(400)
    real_state = _project_commercial_state(project_id, quote_item)
    if not real_state or real_state.get("payments") or real_state.get("execution"):
        abort(409)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM project_sandbox_payments WHERE project_id=%s", (project_id,))
            cur.execute(
                """
                INSERT INTO project_sandbox_state (
                    project_id, quotation_id, enabled, sandbox_started_at,
                    start_note, created_at, updated_at
                ) VALUES (%s,%s,TRUE,NULL,NULL,NOW(),NOW())
                ON CONFLICT (project_id) DO UPDATE
                SET quotation_id=EXCLUDED.quotation_id,
                    enabled=TRUE,
                    sandbox_started_at=NULL,
                    start_note=NULL,
                    updated_at=NOW()
                """,
                (project_id, quote_item["id"]),
            )
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="enabled"))


@app.route("/admin/projects/<int:project_id>/sandbox/payments/record", methods=["POST"])
@admin_required
def admin_project_sandbox_payment_record(project_id):
    validate_csrf()
    quote_item = _latest_accepted_project_quotation(project_id)
    sandbox = _project_sandbox_state(project_id, quote_item)
    # Sandbox payments must remain available after the simulated project starts.
    # Real projects can receive later milestone/final payments while execution is
    # in progress, so the isolated test workflow must mirror that behavior.
    if not sandbox or not sandbox.get("enabled"):
        abort(409)
    try:
        amount = _crm_payment_amount(request.form.get("amount"))
    except ValueError:
        abort(400)
    if amount is None or amount <= 0 or amount > sandbox["total_remaining"]:
        abort(400)
    method = _crm_payment_method(request.form.get("payment_method"))
    stage = _project_clean(request.form.get("stage"), 40).upper()
    if stage not in PROJECT_PAYMENT_STAGE_LABELS:
        abort(400)
    reference = _project_clean(request.form.get("reference"), 180)
    payment_note = _project_clean(request.form.get("payment_note"), 1000)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_sandbox_payments (
                    project_id, quotation_id, stage, amount, currency,
                    payment_method, reference, payment_note, received_at
                ) VALUES (%s,%s,%s,%s,%s,%s,NULLIF(%s,''),NULLIF(%s,''),NOW())
                """,
                (project_id, quote_item["id"], stage, amount, sandbox["currency"], method, reference, payment_note),
            )
            cur.execute("UPDATE project_sandbox_state SET updated_at=NOW() WHERE project_id=%s", (project_id,))
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="payment"))


