@admin_required
def admin_project_sandbox_payment_void(project_id, payment_id):
    validate_csrf()
    reason = _project_clean(request.form.get("void_reason"), 300)
    if not reason:
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    sandbox = _project_sandbox_state(project_id, quote_item)
    if not sandbox or not sandbox.get("enabled"):
        abort(409)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE project_sandbox_payments
                SET voided_at=NOW(), void_reason=%s
                WHERE id=%s AND project_id=%s AND quotation_id=%s AND voided_at IS NULL
                RETURNING id
                """,
                (reason, payment_id, project_id, quote_item["id"]),
            )
            if not cur.fetchone():
                abort(404)
            cur.execute("UPDATE project_sandbox_state SET updated_at=NOW() WHERE project_id=%s", (project_id,))
        conn.commit()
    # If a test payment is voided after a simulated start and the test ledger no
    # longer covers the deposit, unwind only the sandbox start state.
    new_state = _project_sandbox_state(project_id, quote_item)
    if new_state and new_state.get("started") and not new_state.get("deposit_verified"):
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE project_sandbox_state SET sandbox_started_at=NULL, start_note=NULL, execution_plan='{}'::jsonb, execution_updates='[]'::jsonb, updated_at=NOW() WHERE project_id=%s",
                    (project_id,),
                )
            conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id, sandbox="voided"))


