@app.route("/admin/projects/<int:project_id>/payments/record", methods=["POST"])
@admin_required
def admin_project_payment_record(project_id):
    validate_csrf()
    quote_item = _latest_accepted_project_quotation(project_id)
    if not quote_item:
        abort(400)
    if _project_sandbox_enabled(project_id, quote_item):
        abort(409)
    state = _project_commercial_state(project_id, quote_item)
    if not state:
        abort(400)
    try:
        amount = _crm_payment_amount(request.form.get("amount"))
    except ValueError:
        abort(400)
    if amount is None or amount > state["total_remaining"]:
        abort(400)
    method = _crm_payment_method(request.form.get("payment_method"))
    stage = _project_clean(request.form.get("stage"), 40).upper()
    if stage not in PROJECT_PAYMENT_STAGE_LABELS:
        abort(400)
    reference = _project_clean(request.form.get("reference"), 180)
    payment_note = _project_clean(request.form.get("payment_note"), 1000)
    invoice_id = state["invoice"]["id"] if state.get("invoice") and stage == "DEPOSIT" else None
    previous_deposit_verified = state["deposit_verified"]
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_payments (
                    project_id, quotation_id, invoice_id, stage, amount, currency,
                    payment_method, reference, payment_note, received_at
                ) VALUES (%s,%s,%s,%s,%s,%s,%s,NULLIF(%s,''),NULLIF(%s,''),NOW())
                RETURNING id
                """,
                (project_id, quote_item["id"], invoice_id, stage, amount, state["currency"], method, reference, payment_note),
            )
            payment_id = cur.fetchone()[0]
            _project_activity_insert(cur, project_id, "PAYMENT_VERIFIED", f"Verified project payment recorded: {state['currency']} {amount:,.0f} ({PROJECT_PAYMENT_STAGE_LABELS[stage]}). Ledger payment ID {payment_id}.")
            _quote_event_insert(cur, quote_item["id"], "PAYMENT_VERIFIED", f"IBROWS recorded a verified payment of {state['currency']} {amount:,.0f}. Customer claims/screenshots were not used as payment proof by themselves.")
        conn.commit()
    new_state = _project_commercial_state(project_id, quote_item)
    if new_state and new_state["deposit_verified"] and not previous_deposit_verified:
        with get_db() as conn:
            with conn.cursor() as cur:
                _project_activity_insert(cur, project_id, "DEPOSIT_VERIFIED", f"Required deposit threshold reached: {new_state['currency']} {new_state['deposit_required']:,.0f}. Project is ready for explicit IBROWS start approval.")
                _quote_event_insert(cur, quote_item["id"], "DEPOSIT_VERIFIED", "Required deposit verified in the IBROWS project ledger. Payment alone does not start the project.")
            conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id))


