@app.route("/admin/projects/<int:project_id>/start", methods=["POST"])
@admin_required
def admin_project_start(project_id):
    validate_csrf()
    if request.form.get("confirm_start") != "1":
        abort(400)
    quote_item = _latest_accepted_project_quotation(project_id)
    if not quote_item:
        abort(400)
    if _project_sandbox_enabled(project_id, quote_item):
        abort(409)
    state = _project_commercial_state(project_id, quote_item)
    if not state or not state["deposit_verified"]:
        abort(400)
    if state.get("execution"):
        return redirect(url_for("admin_project_detail", project_id=project_id))
    start_note = _project_clean(request.form.get("start_note"), 1200)
    scope_snapshot = {
        "required": quote_item.get("scope", {}).get("required", []),
        "recommended": quote_item.get("scope", {}).get("recommended", []),
        "optional": quote_item.get("scope", {}).get("optional", []),
    }
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO project_execution (
                    project_id, quotation_id, status, scope_snapshot, investment,
                    currency, payment_schedule, start_note, started_at, updated_at
                ) VALUES (%s,%s,'IN_PROGRESS',%s::jsonb,%s,%s,%s,NULLIF(%s,''),NOW(),NOW())
                ON CONFLICT (project_id) DO NOTHING
                RETURNING id
                """,
                (project_id, quote_item["id"], json.dumps(scope_snapshot), state["final_price"], state["currency"], quote_item.get("terms",{}).get("payment_terms") or "", start_note),
            )
            created = cur.fetchone()
            if created:
                cur.execute("UPDATE project_assessments SET status='IN_PROGRESS', updated_at=NOW() WHERE id=%s", (project_id,))
                _project_activity_insert(cur, project_id, "PROJECT_STARTED", f"Project explicitly started by IBROWS after verified deposit of at least {state['currency']} {state['deposit_required']:,.0f}.")
                _quote_event_insert(cur, quote_item["id"], "PROJECT_STARTED", "IBROWS explicitly started the project after verifying the required deposit.")
        conn.commit()
    return redirect(url_for("admin_project_detail", project_id=project_id))


def _quotation_request_looks_automated():
    ua = (request.headers.get("User-Agent") or "").lower()
    tokens = (
        "google-read-aloud", "bot", "crawler", "spider", "preview",
        "scanner", "facebookexternalhit", "slackbot", "whatsapp",
        "curl/", "wget/",
    )
    return any(token in ua for token in tokens)


@app.route("/quotation/<public_token>", methods=["GET"])
def public_project_quotation(public_token):
    quote_item = _get_project_quotation_by_token(public_token)
    if not quote_item:
        abort(404)
    quote_item = _sync_project_quotation_expiry(quote_item)
    if quote_item.get("status") == "ISSUED" and not _quotation_request_looks_automated():
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE project_quotations SET status='VIEWED', viewed_at=COALESCE(viewed_at,NOW()), updated_at=NOW() WHERE id=%s AND status='ISSUED' RETURNING id",
                    (quote_item["id"],),
                )
                changed = cur.fetchone()
                if changed:
                    _quote_event_insert(cur, quote_item["id"], "VIEWED", "Client secure quotation page opened for the first time.")
                    _project_activity_insert(cur, quote_item["project_id"], "QUOTE_VIEWED", f"Quotation {quote_item['quote_reference']} viewed on secure client page.")
            conn.commit()
        quote_item = _get_project_quotation_by_id(quote_item["id"])
    response_nonce = secrets.token_urlsafe(20)
    session[f"quote_response_nonce_{quote_item['id']}"] = response_nonce
    return render_template_string(
        PROJECT_QUOTATION_PUBLIC_TEMPLATE,
        quote=quote_item, preview_only=False, response_nonce=response_nonce,
        pdf_url=url_for("public_project_quotation_pdf", public_token=public_token),
        commercial_state=_project_commercial_state(quote_item["project_id"], quote_item) if quote_item.get("status") == "ACCEPTED" else None,
        deposit_invoice_url=(url_for("public_project_deposit_invoice_pdf", public_token=public_token) if quote_item.get("status") == "ACCEPTED" else ""),
    ), 200


