PROJECT_MILESTONE_STATUS_LABELS = {
    "PENDING": "Pending",
    "IN_PROGRESS": "In Progress",
    "WAITING_CLIENT": "Waiting on Client",
    "BLOCKED": "Blocked",
    "COMPLETED": "Completed",
}
PROJECT_TASK_STATUS_LABELS = {
    "TODO": "To Do",
    "IN_PROGRESS": "In Progress",
    "BLOCKED": "Blocked",
    "DONE": "Done",
}
PROJECT_TASK_PRIORITY_LABELS = {
    "NORMAL": "Normal",
    "HIGH": "High",
    "URGENT": "Urgent",
}
PROJECT_STAGE_INVOICE_LABELS = {
    "MILESTONE_2": "Functional demonstration",
    "FINAL": "Production deployment / final",
}


def _init_project_execution_v33_schema():
    """Idempotent schema additions for the post-deposit execution workspace."""
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("ALTER TABLE project_execution ADD COLUMN IF NOT EXISTS progress_percent NUMERIC(5,2) NOT NULL DEFAULT 0")
            cur.execute("ALTER TABLE project_execution ALTER COLUMN progress_percent TYPE NUMERIC(5,2) USING progress_percent::numeric")
            cur.execute("ALTER TABLE project_execution ADD COLUMN IF NOT EXISTS target_completion_date DATE")
            cur.execute("ALTER TABLE project_execution ADD COLUMN IF NOT EXISTS status_note TEXT")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS project_milestones (
                    id BIGSERIAL PRIMARY KEY,
                    project_id BIGINT NOT NULL REFERENCES project_assessments(id) ON DELETE CASCADE,
                    quotation_id BIGINT NOT NULL REFERENCES project_quotations(id) ON DELETE RESTRICT,
                    sequence_no INTEGER NOT NULL DEFAULT 1,
                    title TEXT NOT NULL,
                    description TEXT,
                    status TEXT NOT NULL DEFAULT 'PENDING'
                        CHECK (status IN ('PENDING','IN_PROGRESS','WAITING_CLIENT','BLOCKED','COMPLETED')),
                    progress_percent INTEGER NOT NULL DEFAULT 0 CHECK (progress_percent BETWEEN 0 AND 100),
                    weight_percent INTEGER NOT NULL DEFAULT 0 CHECK (weight_percent BETWEEN 0 AND 100),
                    assigned_to TEXT,
                    due_date DATE,
                    payment_stage TEXT,
                    client_visible BOOLEAN NOT NULL DEFAULT TRUE,
                    completed_at TIMESTAMPTZ,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_project_milestones_project
                ON project_milestones(project_id, sequence_no, id)
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS project_tasks (
                    id BIGSERIAL PRIMARY KEY,
                    project_id BIGINT NOT NULL REFERENCES project_assessments(id) ON DELETE CASCADE,
                    milestone_id BIGINT REFERENCES project_milestones(id) ON DELETE SET NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    status TEXT NOT NULL DEFAULT 'TODO'
                        CHECK (status IN ('TODO','IN_PROGRESS','BLOCKED','DONE')),
                    priority TEXT NOT NULL DEFAULT 'NORMAL'
                        CHECK (priority IN ('NORMAL','HIGH','URGENT')),
                    assigned_to TEXT,
                    due_date DATE,
                    client_visible BOOLEAN NOT NULL DEFAULT FALSE,
                    completed_at TIMESTAMPTZ,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_project_tasks_project
                ON project_tasks(project_id, status, due_date, id)
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS project_client_updates (
                    id BIGSERIAL PRIMARY KEY,
                    project_id BIGINT NOT NULL REFERENCES project_assessments(id) ON DELETE CASCADE,
                    title TEXT NOT NULL,
                    update_text TEXT NOT NULL,
                    progress_percent NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (progress_percent BETWEEN 0 AND 100),
                    published BOOLEAN NOT NULL DEFAULT TRUE,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_project_client_updates_project
                ON project_client_updates(project_id, created_at DESC, id DESC)
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS project_stage_invoices (
                    id BIGSERIAL PRIMARY KEY,
                    project_id BIGINT NOT NULL REFERENCES project_assessments(id) ON DELETE CASCADE,
                    quotation_id BIGINT NOT NULL REFERENCES project_quotations(id) ON DELETE RESTRICT,
                    stage TEXT NOT NULL CHECK (stage IN ('MILESTONE_2','FINAL')),
                    invoice_number TEXT NOT NULL UNIQUE,
                    amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
                    currency TEXT NOT NULL DEFAULT 'MWK',
                    status TEXT NOT NULL DEFAULT 'UNPAID'
                        CHECK (status IN ('UNPAID','PART_PAID','PAID','VOID')),
                    issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    paid_at TIMESTAMPTZ,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE (quotation_id, stage)
                )
            """)
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_project_stage_invoices_project
                ON project_stage_invoices(project_id, issued_at DESC, id DESC)
            """)
            cur.execute("ALTER TABLE project_client_updates ALTER COLUMN progress_percent TYPE NUMERIC(5,2) USING progress_percent::numeric")
            cur.execute("ALTER TABLE project_sandbox_state ADD COLUMN IF NOT EXISTS execution_plan JSONB NOT NULL DEFAULT '{}'::jsonb")
            cur.execute("ALTER TABLE project_sandbox_state ADD COLUMN IF NOT EXISTS execution_updates JSONB NOT NULL DEFAULT '[]'::jsonb")
        conn.commit()


try:
    _init_project_execution_v33_schema()
    print("PROJECT EXECUTION V42 READY", flush=True)
except Exception as error:
    print(f"PROJECT EXECUTION V42 SCHEMA ERROR: {type(error).__name__}", flush=True)


def _execution_safe_date(value):
    value = str(value or "").strip()
    if not value:
        return None
    try:
        datetime.strptime(value, "%Y-%m-%d")
        return value
    except Exception:
        raise ValueError("Invalid date.")


