def _ensure_live_execution_plan(project_id):
    execution = _get_project_execution(project_id)
    if not execution:
        return None
    quote_item = _get_project_quotation_by_id(execution["quotation_id"])
    if not quote_item:
        return execution
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM project_milestones WHERE project_id=%s", (project_id,))
            existing = int(cur.fetchone()[0] or 0)
            if existing == 0:
                milestone_ids = []
                for seq, data in enumerate(_execution_default_milestone_defs(), 1):
                    cur.execute(
                        """
                        INSERT INTO project_milestones (
                            project_id, quotation_id, sequence_no, title, description,
                            status, progress_percent, weight_percent, payment_stage,
                            client_visible, updated_at
                        ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE,NOW())
                        RETURNING id
                        """,
                        (
                            project_id, quote_item["id"], seq, data["title"], data["description"],
                            data["status"], data["progress_percent"], data["weight_percent"], data["payment_stage"],
                        ),
                    )
                    milestone_ids.append(cur.fetchone()[0])
                build_id = milestone_ids[1] if len(milestone_ids) > 1 else None
                required_scope = list((quote_item.get("scope") or {}).get("required") or [])
                for feature in required_scope[:20]:
                    cur.execute(
                        """
                        INSERT INTO project_tasks (
                            project_id, milestone_id, title, status, priority,
                            client_visible, updated_at
                        ) VALUES (%s,%s,%s,'TODO','NORMAL',FALSE,NOW())
                        """,
                        (project_id, build_id, _project_clean(feature, 300)),
                    )
                _project_activity_insert(cur, project_id, "EXECUTION_PLAN_CREATED", "Project execution workspace created from the accepted quotation scope.")
        conn.commit()
    _execution_recalculate_progress(project_id)
    return _get_project_execution(project_id)


def _execution_progress_value(value):
    try:
        pct = round(float(value or 0), 1)
    except (TypeError, ValueError):
        pct = 0.0
    return max(0.0, min(100.0, pct))


def _execution_progress_label(value):
    pct = _execution_progress_value(value)
    return f"{pct:.1f}".rstrip("0").rstrip(".")


def _execution_recalculate_progress(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT weight_percent, progress_percent FROM project_milestones WHERE project_id=%s ORDER BY sequence_no,id",
                (project_id,),
            )
            rows = cur.fetchall()
            if not rows:
                pct = 0
            else:
                total_weight = sum(int(r[0] or 0) for r in rows)
                weighted = sum(int(r[0] or 0) * int(r[1] or 0) for r in rows)
                pct = round(weighted / total_weight, 1) if total_weight > 0 else 0.0
                pct = max(0.0, min(100.0, pct))
            cur.execute("UPDATE project_execution SET progress_percent=%s, updated_at=NOW() WHERE project_id=%s", (pct, project_id))
        conn.commit()
    return pct


def _execution_live_rows(project_id):
    execution = _ensure_live_execution_plan(project_id)
    if not execution:
        return None
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, project_id, quotation_id, status, scope_snapshot,
                       investment, currency, payment_schedule, start_note,
                       started_at, completed_at, created_at, updated_at,
                       progress_percent, target_completion_date, status_note
                FROM project_execution WHERE project_id=%s
                """,
                (project_id,),
            )
            erow = cur.fetchone()
            cur.execute(
                """
                SELECT id, sequence_no, title, description, status, progress_percent,
                       weight_percent, assigned_to, due_date, payment_stage,
                       client_visible, completed_at, created_at, updated_at
                FROM project_milestones WHERE project_id=%s
                ORDER BY sequence_no,id
                """,
                (project_id,),
            )
            mrows = cur.fetchall()
            cur.execute(
                """
                SELECT id, milestone_id, title, description, status, priority,
                       assigned_to, due_date, client_visible, completed_at,
                       created_at, updated_at
                FROM project_tasks WHERE project_id=%s
                ORDER BY CASE status WHEN 'IN_PROGRESS' THEN 1 WHEN 'TODO' THEN 2 WHEN 'BLOCKED' THEN 3 ELSE 4 END,
                         due_date NULLS LAST, id
                """,
                (project_id,),
            )
            trows = cur.fetchall()
            cur.execute(
                """
                SELECT id, title, update_text, progress_percent, published,
                       created_at, updated_at
                FROM project_client_updates WHERE project_id=%s
                ORDER BY created_at DESC,id DESC
                """,
                (project_id,),
            )
            urows = cur.fetchall()
    ekeys = [
        "id","project_id","quotation_id","status","scope_snapshot","investment","currency","payment_schedule","start_note",
        "started_at","completed_at","created_at","updated_at","progress_percent","target_completion_date","status_note",
    ]
    item = dict(zip(ekeys, erow))
    item["investment"] = _money_decimal(item.get("investment"))
    item["progress_percent"] = _execution_progress_value(item.get("progress_percent"))
    item["progress_label"] = _execution_progress_label(item.get("progress_percent"))
    item["started_label"] = item["started_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("started_at") else ""
    item["completed_label"] = item["completed_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("completed_at") else ""
    item["target_date_value"] = item["target_completion_date"].isoformat() if item.get("target_completion_date") else ""
    milestones=[]
    for r in mrows:
        keys=["id","sequence_no","title","description","status","progress_percent","weight_percent","assigned_to","due_date","payment_stage","client_visible","completed_at","created_at","updated_at"]
        m=dict(zip(keys,r)); m["status_label"]=PROJECT_MILESTONE_STATUS_LABELS.get(m["status"],m["status"]); m["due_date_value"]=m["due_date"].isoformat() if m.get("due_date") else ""; m["completed_label"]=m["completed_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if m.get("completed_at") else ""; milestones.append(m)
    tasks=[]
    for r in trows:
        keys=["id","milestone_id","title","description","status","priority","assigned_to","due_date","client_visible","completed_at","created_at","updated_at"]
        t=dict(zip(keys,r)); t["status_label"]=PROJECT_TASK_STATUS_LABELS.get(t["status"],t["status"]); t["priority_label"]=PROJECT_TASK_PRIORITY_LABELS.get(t["priority"],t["priority"]); t["due_date_value"]=t["due_date"].isoformat() if t.get("due_date") else ""; tasks.append(t)
    updates=[]
    for r in urows:
        u=dict(zip(["id","title","update_text","progress_percent","published","created_at","updated_at"],r)); u["progress_percent"]=_execution_progress_value(u.get("progress_percent")); u["progress_label"]=_execution_progress_label(u.get("progress_percent")); u["created_label"]=u["created_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M"); updates.append(u)
    item["milestones"]=milestones; item["tasks"]=tasks; item["updates"]=updates
    return item


def _execution_schedule_percentages(quote_item):
    pricing = quote_item.get("pricing") or {}
    deposit_pct = float(pricing.get("deposit_percent") or 0)
    terms = str((quote_item.get("terms") or {}).get("payment_terms") or "")
    m2 = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+after\s+functional\s+demonstration", terms, re.I)
    mf = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+at\s+production\s+deployment", terms, re.I)
    milestone_pct = float(m2.group(1)) if m2 else 0.0
    final_pct = float(mf.group(1)) if mf else max(0.0, 100.0 - deposit_pct - milestone_pct)
    total = deposit_pct + milestone_pct + final_pct
    if total <= 0:
        deposit_pct, milestone_pct, final_pct = 50.0, 30.0, 20.0
    return {"DEPOSIT": deposit_pct, "MILESTONE_2": milestone_pct, "FINAL": final_pct}


def _execution_payment_summary(project_id, quote_item=None, sandbox_state=None):
    quote_item = quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item:
        return None
    final_price = _money_decimal((quote_item.get("pricing") or {}).get("final_price"))
    pcts = _execution_schedule_percentages(quote_item)
    amounts = {k: (final_price * Decimal(str(v)) / Decimal("100")).quantize(Decimal("0.01")) for k,v in pcts.items()}
    if sandbox_state is not None:
        payment_rows = [p for p in sandbox_state.get("payments",[]) if not p.get("is_void")]
    else:
        payment_rows = _project_payment_rows(project_id, quote_item["id"])
    paid_by_stage={k:Decimal("0") for k in amounts}
    for p in payment_rows:
        stage=p.get("stage")
        if stage in paid_by_stage:
            paid_by_stage[stage]+=_money_decimal(p.get("amount"))
    out=[]
    for stage in ("DEPOSIT","MILESTONE_2","FINAL"):
        required=amounts.get(stage,Decimal("0")); paid=paid_by_stage.get(stage,Decimal("0")); remaining=max(Decimal("0"),required-paid)
        out.append({"stage":stage,"label":PROJECT_PAYMENT_STAGE_LABELS.get(stage,stage),"percent":pcts.get(stage,0),"required":required,"paid":paid,"remaining":remaining,"paid_ok":required<=0 or paid>=required})
    return {"rows":out,"currency":quote_item.get("currency") or "MWK","final_price":final_price}


def _stage_invoice_row_to_dict(row):
    if not row: return None
    keys=["id","project_id","quotation_id","stage","invoice_number","amount","currency","status","issued_at","paid_at","created_at","updated_at"]
    item=dict(zip(keys,row)); item["amount"]=_money_decimal(item.get("amount")); item["status_label"]=PROJECT_INVOICE_STATUS_LABELS.get(item.get("status"),item.get("status") or "Unknown"); item["stage_label"]=PROJECT_STAGE_INVOICE_LABELS.get(item.get("stage"),item.get("stage")); item["issued_label"]=item["issued_at"].astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M") if item.get("issued_at") else ""; return item


def _execution_stage_invoices(project_id, quote_item=None, sync=True):
    quote_item=quote_item or _latest_accepted_project_quotation(project_id)
    if not quote_item: return []
    summary=_execution_payment_summary(project_id, quote_item)
    paid_map={x["stage"]:x["paid"] for x in summary["rows"]}
    req_map={x["stage"]:x["required"] for x in summary["rows"]}
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id,project_id,quotation_id,stage,invoice_number,amount,currency,status,issued_at,paid_at,created_at,updated_at FROM project_stage_invoices WHERE project_id=%s ORDER BY issued_at,id",(project_id,))
            rows=cur.fetchall()
            if sync:
                for r in rows:
                    stage=r[3]; paid=paid_map.get(stage,Decimal("0")); req=req_map.get(stage,_money_decimal(r[5])); status="PAID" if req>0 and paid>=req else ("PART_PAID" if paid>0 else "UNPAID")
                    cur.execute("UPDATE project_stage_invoices SET status=%s,paid_at=CASE WHEN %s='PAID' THEN COALESCE(paid_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND status<>'VOID'",(status,status,r[0]))
            if sync: conn.commit()
    if sync:
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT id,project_id,quotation_id,stage,invoice_number,amount,currency,status,issued_at,paid_at,created_at,updated_at FROM project_stage_invoices WHERE project_id=%s ORDER BY issued_at,id",(project_id,)); rows=cur.fetchall()
    return [_stage_invoice_row_to_dict(r) for r in rows]


def _sandbox_execution_state(project_id, quote_item=None):
    sandbox=_project_sandbox_state(project_id, quote_item)
    if not sandbox or not sandbox.get("enabled") or not sandbox.get("started"):
        return None
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT execution_plan,execution_updates FROM project_sandbox_state WHERE project_id=%s",(project_id,)); row=cur.fetchone()
            plan=(row[0] if row and isinstance(row[0],dict) else {}) or {}; updates=(row[1] if row and isinstance(row[1],list) else []) or []
            if not plan:
                milestones=[]
                for i,d in enumerate(_execution_default_milestone_defs(),1):
                    milestones.append({"id":f"m{i}","sequence_no":i,"title":d["title"],"description":d["description"],"status":d["status"],"progress_percent":d["progress_percent"],"weight_percent":d["weight_percent"],"assigned_to":"","due_date":"","payment_stage":d["payment_stage"],"client_visible":True})
                plan={"status":"IN_PROGRESS","progress_percent":0,"target_completion_date":"","status_note":"","milestones":milestones,"tasks":[]}
                cur.execute("UPDATE project_sandbox_state SET execution_plan=%s::jsonb,execution_updates=%s::jsonb,updated_at=NOW() WHERE project_id=%s",(json.dumps(plan),json.dumps(updates),project_id)); conn.commit()
    plan["updates"]=updates; plan["sandbox"]=sandbox; return plan


def _sandbox_save_execution(project_id, plan, updates=None):
    # The rendered sandbox state carries live-only helper objects (Decimals,
    # datetimes and the payment-state dict). Persist only the isolated execution
    # plan itself so JSON serialization can never leak or depend on live data.
    clean_plan = {k: v for k, v in dict(plan or {}).items() if k not in {"sandbox", "updates"}}
    with get_db() as conn:
        with conn.cursor() as cur:
            if updates is None:
                cur.execute("UPDATE project_sandbox_state SET execution_plan=%s::jsonb,updated_at=NOW() WHERE project_id=%s",(json.dumps(clean_plan),project_id))
            else:
                cur.execute("UPDATE project_sandbox_state SET execution_plan=%s::jsonb,execution_updates=%s::jsonb,updated_at=NOW() WHERE project_id=%s",(json.dumps(clean_plan),json.dumps(updates),project_id))
        conn.commit()


def _sandbox_recalc_execution(plan):
    milestones = plan.get("milestones") or []
    tw = sum(float(m.get("weight_percent") or 0) for m in milestones)
    weighted = sum(float(m.get("weight_percent") or 0) * float(m.get("progress_percent") or 0) for m in milestones)
    plan["progress_percent"] = _execution_progress_value((weighted / tw) if tw else 0)
    plan["progress_label"] = _execution_progress_label(plan["progress_percent"])
    return plan


def _execution_can_complete(execution_data, payment_summary):
    if not execution_data or not payment_summary: return False
    milestones=execution_data.get("milestones") or []; tasks=execution_data.get("tasks") or []
    all_milestones=bool(milestones) and all(m.get("status")=="COMPLETED" for m in milestones)
    all_tasks=all(t.get("status")=="DONE" for t in tasks)
    fully_paid=all(r.get("paid_ok") for r in payment_summary.get("rows",[]))
    return bool(all_milestones and all_tasks and fully_paid)


def _execution_stage_invoice_pdf_bytes(invoice, quote_item, payment_summary):
    # Compact branded one-page milestone/final invoice using the same locked quotation snapshot.
    PAGE_W,PAGE_H=595.0,842.0; LEFT,RIGHT=42.0,553.0; CONTENT_W=RIGHT-LEFT
    INK=(0.07,0.10,0.16); MUTED=(0.40,0.44,0.52); PURPLE=(0.39,0.08,0.35); PURPLE_DARK=(0.30,0.05,0.28); BORDER=(0.88,0.89,0.92); PALE=(0.97,0.96,0.98); BLUE_PALE=(0.94,0.97,1.0)
    commands=[]
    def fill(rgb): return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} rg"
    def stroke(rgb): return f"{rgb[0]:g} {rgb[1]:g} {rgb[2]:g} RG"
    def text_line(value,x,y,size=10,bold=False,rgb=INK): commands.append(fill(rgb)); font="F2" if bold else "F1"; commands.append(f"BT /{font} {size:g} Tf {x:g} {y:g} Td ({_pdf_escape(_quote_latin1(value))}) Tj ET")
    def right_text(value,x,y,size=10,bold=False,rgb=INK): text_line(value,x-_pdf_text_width_points(_quote_latin1(value),size=size,bold=bold),y,size,bold,rgb)
    def wrap(value,size=9,width=CONTENT_W-28): return _business_pdf_wrap(_pdf_normalize_text(value or ""),size=size,width=width)
    logo_bytes=base64.b64decode(IBROWS_LOGO_JPEG_B64); logo_w=142.0; logo_h=logo_w*(IBROWS_LOGO_JPEG_HEIGHT/IBROWS_LOGO_JPEG_WIDTH)
    commands.append(f"q {logo_w:g} 0 0 {logo_h:g} {LEFT:g} {PAGE_H-55-logo_h:g} cm /Logo Do Q")
    stage_label=PROJECT_STAGE_INVOICE_LABELS.get(invoice["stage"],invoice["stage"])
    text_line("PROJECT INVOICE",RIGHT-155,792,17,True,PURPLE_DARK); right_text(invoice["invoice_number"],RIGHT,773,8.8,True,INK); right_text(f"Quotation: {quote_item['quote_reference']} | Revision {quote_item.get('revision_no') or 1}",RIGHT,758,8.1,False,MUTED); right_text(f"Issued: {invoice['issued_label']}",RIGHT,744,8.1,False,MUTED); commands.append(stroke(PURPLE)); commands.append(f"2 w {LEFT:g} 718 m {RIGHT:g} 718 l S")
    y=688.0; text_line("BILL TO",LEFT,y,8.3,True,PURPLE); y-=18; client=quote_item.get("client") or {}
    for line in [client.get("organisation") or client.get("contact_name") or "Client",client.get("contact_name") or "",client.get("email") or "",client.get("phone") or ""]:
        if line: text_line(str(line),LEFT,y,9.5,False,INK); y-=14
    y-=7; text_line("PAYMENT STAGE",LEFT,y,8.3,True,PURPLE); y-=20; text_line(stage_label,LEFT,y,12,True,INK); y-=24
    box_h=126.0; box_y=y-box_h; commands.append(fill(PALE)); commands.append(f"{LEFT:g} {box_y:g} {CONTENT_W:g} {box_h:g} re f"); text_line("AMOUNT DUE",LEFT+15,y-22,8.4,True,PURPLE); text_line(f"{invoice['currency']} {invoice['amount']:,.0f}",LEFT+15,y-53,23,True,PURPLE_DARK); text_line("Accepted project payment schedule",LEFT+15,y-74,8.5,False,MUTED); text_line("Total quotation value",LEFT+265,y-22,8.2,True,MUTED); right_text(f"{payment_summary['currency']} {payment_summary['final_price']:,.0f}",RIGHT-15,y-39,10.5,True,INK); text_line("Invoice status",LEFT+265,y-62,8.2,True,MUTED); right_text(invoice.get("status_label") or invoice.get("status") or "Unpaid",RIGHT-15,y-79,10.5,True,INK); y=box_y-28
    text_line("PAYMENT REFERENCE",LEFT,y,8.3,True,PURPLE); y-=18
    for line in wrap(f"Please use {invoice['invoice_number']} or {quote_item['quote_reference']} as the payment reference where the channel allows it.",9.1): text_line(line,LEFT,y,9.1,False,INK); y-=13
    y-=7; text_line("APPROVED PAYMENT CHANNELS",LEFT,y,8.3,True,PURPLE); y-=18
    for channel,number,account_name in IBROWS_PAYMENT_CHANNELS:
        label="Number" if channel in {"Airtel Money","TNM Mpamba"} else "Account"; text_line(f"{channel}: {label} {number} - {account_name}",LEFT,y,8.7,False,INK); y-=13
    y-=7; text_line("PAYMENT VERIFICATION",LEFT,y,8.3,True,PURPLE); y-=18; notice="Payment is treated as received only after IBROWS independently verifies it in the internal project ledger. A screenshot, copied transaction reference, customer message or payment claim by itself does not mark this invoice as paid."
    lines=wrap(notice,8.8,CONTENT_W-28); h=22+len(lines)*12; commands.append(fill(BLUE_PALE)); commands.append(f"{LEFT:g} {y-h+8:g} {CONTENT_W:g} {h:g} re f"); ly=y-8
    for line in lines: text_line(line,LEFT+14,ly,8.8,False,INK); ly-=12
    commands.append(stroke(BORDER)); commands.append(f"0.7 w {LEFT:g} 77 m {RIGHT:g} 77 l S"); text_line(f"{IBROWS_BUSINESS_TAGLINE} | {IBROWS_BUSINESS_EMAIL}",LEFT,56,7.8,False,MUTED); right_text("Page 1 of 1",RIGHT,56,7.8,False,MUTED)
    stream="\n".join(commands).encode("latin-1","strict"); objects={1:b"<< /Type /Catalog /Pages 2 0 R >>",2:b"<< /Type /Pages /Kids [6 0 R] /Count 1 >>",3:b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",4:b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",5:(b"<< /Type /XObject /Subtype /Image "+f"/Width {IBROWS_LOGO_JPEG_WIDTH} /Height {IBROWS_LOGO_JPEG_HEIGHT} ".encode("ascii")+b"/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode "+f"/Length {len(logo_bytes)} >>\nstream\n".encode("ascii")+logo_bytes+b"\nendstream"),6:f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {PAGE_W:g} {PAGE_H:g}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo 5 0 R >> >> /Contents 7 0 R >>".encode("ascii"),7:b"<< /Length "+str(len(stream)).encode("ascii")+b" >>\nstream\n"+stream+b"\nendstream"}
    max_id=max(objects); out=bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"); offsets=[0]*(max_id+1)
    for obj_id in range(1,max_id+1): offsets[obj_id]=len(out); out.extend(f"{obj_id} 0 obj\n".encode("ascii")); out.extend(objects[obj_id]); out.extend(b"\nendobj\n")
    xref=len(out); out.extend(f"xref\n0 {max_id+1}\n".encode("ascii")); out.extend(b"0000000000 65535 f \n")
    for obj_id in range(1,max_id+1): out.extend(f"{offsets[obj_id]:010d} 00000 n \n".encode("ascii"))
    out.extend(f"trailer\n<< /Size {max_id+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF".encode("ascii")); return bytes(out)


PROJECT_EXECUTION_ADMIN_TEMPLATE = r"""
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IBROWS Project Execution</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#101828;font-family:Arial,sans-serif;padding-bottom:46px}header{background:#101828;color:#fff}.wrap{max-width:980px;margin:auto;padding:0 14px}.top{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 0}.brand{font-size:20px;font-weight:900}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #d0d5dd;background:#fff;color:#101828;border-radius:9px;padding:10px 12px;font-size:12px;font-weight:850;cursor:pointer}.primary{background:#101828;color:#fff;border-color:#101828}.green{background:#067647;color:#fff;border-color:#067647}.danger{background:#fff;color:#b42318;border-color:#fda29b}.back{color:#fff;background:transparent;border-color:#667085}.card{background:#fff;border-radius:14px;padding:16px;margin:14px 0;box-shadow:0 2px 8px rgba(0,0,0,.05)}h1{font-size:27px;margin:20px 0 4px}.sub{color:#667085;line-height:1.45}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.metric{background:#f9fafb;border-radius:10px;padding:11px}.metric small{display:block;color:#667085;font-weight:800}.metric b{display:block;margin-top:4px;font-size:17px}.progress{height:14px;border-radius:99px;background:#eaecf0;overflow:hidden}.progress span{display:block;height:100%;background:#12b76a}.sandbox{border:2px dashed #9e77ed;background:#f9f5ff}.sandbox-banner{background:#f4ebff;color:#53389e;padding:11px;border-radius:9px;line-height:1.45}.milestone{border:1px solid #eaecf0;border-radius:11px;padding:12px;margin:10px 0}.task{border-top:1px solid #eaecf0;padding:10px 0}.update{border-left:4px solid #2e90fa;background:#eff8ff;padding:11px;border-radius:9px;margin:9px 0}.label{font-size:11px;color:#667085;font-weight:850}.actions{display:flex;gap:7px;flex-wrap:wrap}input,select,textarea{width:100%;border:1px solid #d0d5dd;border-radius:9px;padding:10px;font-size:14px;background:#fff}textarea{min-height:90px;resize:vertical}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.stage{border:1px solid #eaecf0;border-radius:10px;padding:11px;margin:8px 0}.ok{color:#067647}.warn{color:#b54708}.publiclink{word-break:break-all;background:#f9fafb;padding:10px;border-radius:8px;font-size:12px}.mini{font-size:11px;color:#667085}.success{background:#ecfdf3;color:#067647;border-radius:9px;padding:11px;line-height:1.45}.guard{background:#fffaeb;color:#7a2e0e;border-radius:9px;padding:11px;line-height:1.45}@media(max-width:700px){.top{display:block}.back{margin-top:8px}.grid,.formgrid{grid-template-columns:1fr}.actions .btn,.actions form{width:100%}.actions form .btn{width:100%}}
</style></head><body><header><div class="wrap top"><div class="brand">IBROWS Project Execution</div><a class="btn back" href="{{ url_for('admin_project_detail', project_id=project.id) }}">Back to Project</a></div></header><main class="wrap">
<h1>{{ project.organisation or project.contact_name }}</h1><p class="sub">{{ project.reference }} · {{ project.project_type_label }}</p>
{% if sandbox_mode %}<section class="card sandbox"><div class="sandbox-banner"><strong>🧪 EXECUTION SANDBOX</strong><br>This workspace is test-only. Milestones, tasks, updates and progress here do not change the live project, Finance, invoices or client status.</div><a class="btn primary" style="margin-top:10px" href="{{ url_for('admin_project_execution_client_preview', project_id=project.id, mode='sandbox') }}">Preview TEST Client Status Page</a><p class="mini" style="margin-top:8px">Admin-only preview. It uses Sandbox milestones, test updates and test payment figures and does not create or expose a live client link.</p></section>{% endif %}
<section class="card"><div class="grid"><div class="metric"><small>Status</small><b>{{ execution.status if not sandbox_mode else 'TEST: ' + execution.status.replace('_',' ').title() }}</b></div><div class="metric"><small>Progress</small><b>{{ execution.progress_label }}%</b></div><div class="metric"><small>Verified paid</small><b>{{ payment_summary.currency }} {{ '{:,.0f}'.format(total_paid) }}</b></div><div class="metric"><small>Project value</small><b>{{ payment_summary.currency }} {{ '{:,.0f}'.format(payment_summary.final_price) }}</b></div><div class="metric"><small>Balance</small><b>{{ payment_summary.currency }} {{ '{:,.0f}'.format(total_remaining) }}</b></div><div class="metric"><small>Started</small><b>{{ started_label or '—' }}</b></div></div><div class="progress" style="margin-top:12px"><span style="width:{{ execution.progress_percent }}%"></span></div></section>
{% if not sandbox_mode %}<section class="card"><h2>Client status link</h2><p class="sub">Share this secure link with the client for published progress updates. Internal tasks, notes and assignees are never shown there.</p><div class="publiclink">{{ client_status_url }}</div></section>{% endif %}
<section class="card"><h2>Payment schedule</h2><p class="sub">Payments are counted only from the verified project ledger{% if sandbox_mode %} inside this test simulation{% endif %}.</p>{% for row in payment_summary.rows %}<div class="stage"><strong>{{ row.label }} — {{ '{:,.0f}'.format(row.percent) }}%</strong><div class="grid" style="margin-top:8px"><div class="metric"><small>Required</small><b>{{ payment_summary.currency }} {{ '{:,.0f}'.format(row.required) }}</b></div><div class="metric"><small>Verified</small><b>{{ payment_summary.currency }} {{ '{:,.0f}'.format(row.paid) }}</b></div><div class="metric"><small>Remaining</small><b class="{% if row.paid_ok %}ok{% else %}warn{% endif %}">{{ payment_summary.currency }} {{ '{:,.0f}'.format(row.remaining) }}</b></div></div>{% if not sandbox_mode and row.stage in ['MILESTONE_2','FINAL'] %}{% set inv = invoice_map.get(row.stage) %}<div class="actions" style="margin-top:8px">{% if inv %}<a class="btn" href="{{ url_for('admin_project_stage_invoice_pdf', project_id=project.id, stage=row.stage) }}">Download {{ inv.invoice_number }}</a>{% else %}<form method="POST" action="{{ url_for('admin_project_stage_invoice_create', project_id=project.id, stage=row.stage) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><button class="btn" type="submit">Create {{ row.label }} Invoice</button></form>{% endif %}</div>{% endif %}</div>{% endfor %}</section>
<section class="card"><h2>Milestones</h2><p class="mini">Overall project progress is weighted across milestones. A milestone's progress is multiplied by its project weight, so 55% progress on a 10% milestone contributes 5.5 percentage points to the overall project.</p>{% for m in execution.milestones %}<div class="milestone" id="milestone-{{ m.id }}"><strong>{{ m.sequence_no }}. {{ m.title }}</strong><div class="mini" style="margin-top:4px">Project weight: {{ m.weight_percent }}% · Current overall contribution: {{ '%.1f'|format((m.progress_percent|float) * (m.weight_percent|float) / 100) }}%</div>{% if saved_milestone and saved_milestone|string == m.id|string %}<div class="success" style="margin-top:9px"><strong>✓ Milestone saved successfully.</strong><br>Your latest status, progress, assignment, due date and client-visibility setting are stored.</div>{% endif %}<p class="sub">{{ m.description }}</p><form method="POST" action="{{ url_for('admin_project_execution_milestone_update', project_id=project.id, milestone_id=m.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><div class="formgrid"><div><label class="label">Status</label><select name="status">{% for value,label in milestone_statuses.items() %}<option value="{{ value }}" {% if m.status==value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div><label class="label">Milestone progress %</label><input type="number" name="progress_percent" min="0" max="100" step="1" value="{{ m.progress_percent }}"></div><div><label class="label">Assigned to</label><input name="assigned_to" maxlength="160" value="{{ m.assigned_to or '' }}" placeholder="Staff name / team"></div><div><label class="label">Due date</label><input type="date" name="due_date" value="{{ m.due_date_value if not sandbox_mode else (m.due_date or '') }}"></div></div><label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px"><input type="checkbox" name="client_visible" value="1" style="width:auto;margin-top:3px" {% if m.client_visible %}checked{% endif %}> <span>Show this milestone on the secure client status page</span></label><button class="btn primary" style="margin-top:8px" type="submit">Save Milestone</button></form></div>{% endfor %}</section>
<section class="card" id="tasks"><h2>Tasks</h2>{% if task_deleted %}<div class="success" style="margin-bottom:10px"><strong>✓ Task deleted successfully.</strong><br>The {{ 'TEST task' if sandbox_mode else 'task' }} has been removed from this workspace.</div>{% endif %}<form method="POST" action="{{ url_for('admin_project_execution_task_add', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><div class="formgrid"><div><label class="label">Task</label><input name="title" maxlength="300" required placeholder="Add a project task"></div><div><label class="label">Milestone</label><select name="milestone_id"><option value="">No milestone</option>{% for m in execution.milestones %}<option value="{{ m.id }}">{{ m.sequence_no }}. {{ m.title }}</option>{% endfor %}</select></div><div><label class="label">Assigned to</label><input name="assigned_to" maxlength="160"></div><div><label class="label">Due date</label><input type="date" name="due_date"></div></div><button class="btn primary" style="margin-top:8px" type="submit">Add Task</button></form>{% for t in execution.tasks %}<div class="task" id="task-{{ t.id }}"><strong>{{ t.title }}</strong>{% if task_added and task_added|string == t.id|string %}<div class="success" style="margin-top:9px"><strong>✓ Task added successfully.</strong><br>The task, milestone link, assignment and due date are stored.</div>{% elif saved_task and saved_task|string == t.id|string %}<div class="success" style="margin-top:9px"><strong>✓ Task saved successfully.</strong><br>Your latest status, priority, assignment and due date are stored.</div>{% endif %}<div class="mini" style="margin-top:6px"><strong>Milestone:</strong> {% if t.milestone_id %}{% set ns = namespace(found=false) %}{% for m in execution.milestones %}{% if m.id|string == t.milestone_id|string %}{{ m.sequence_no }}. {{ m.title }}{% set ns.found = true %}{% endif %}{% endfor %}{% if not ns.found %}Linked milestone{% endif %}{% else %}No milestone{% endif %}</div><form method="POST" action="{{ url_for('admin_project_execution_task_update', project_id=project.id, task_id=t.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><div class="formgrid" style="margin-top:7px"><div><label class="label">Status</label><select name="status">{% for value,label in task_statuses.items() %}<option value="{{ value }}" {% if t.status==value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div><label class="label">Priority</label><select name="priority">{% for value,label in task_priorities.items() %}<option value="{{ value }}" {% if t.priority==value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div><label class="label">Assigned to</label><input name="assigned_to" maxlength="160" value="{{ t.assigned_to or '' }}"></div><div><label class="label">Due date</label><input type="date" name="due_date" value="{{ t.due_date_value if not sandbox_mode else (t.due_date or '') }}"></div></div><button class="btn" style="margin-top:7px" type="submit">Save Task</button></form><form method="POST" action="{{ url_for('admin_project_execution_task_delete', project_id=project.id, task_id=t.id) }}" data-confirm="Delete this {{ 'TEST ' if sandbox_mode else '' }}task? This cannot be undone." style="margin-top:7px"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><button class="btn danger" type="submit">Delete Task</button></form></div>{% else %}<p class="sub">No tasks yet.</p>{% endfor %}</section>
<section class="card"><h2>Client updates</h2><form method="POST" action="{{ url_for('admin_project_execution_update_add', project_id=project.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><label class="label">Update title</label><input name="title" maxlength="200" required placeholder="e.g. Integration testing completed"><label class="label" style="display:block;margin-top:8px">Update</label><textarea name="update_text" maxlength="3000" required placeholder="Client-safe progress update"></textarea>{% if not sandbox_mode %}<label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px"><input type="checkbox" name="published" value="1" checked style="width:auto;margin-top:3px"> <span>Publish to secure client status page</span></label>{% endif %}<button class="btn primary" style="margin-top:8px" type="submit">{{ 'Add Test Update' if sandbox_mode else 'Publish Update' }}</button></form>{% for u in execution.updates %}<div class="update"><strong>{{ u.title }}</strong><div class="mini">{{ u.created_label if not sandbox_mode else u.created_label }} · {{ u.progress_label or u.progress_percent }}%{% if not sandbox_mode %} · {{ 'Published' if u.published else 'Internal only' }}{% endif %}</div><p>{{ u.update_text }}</p></div>{% else %}<p class="sub">No updates yet.</p>{% endfor %}</section>
<section class="card"><h2>Project completion</h2>{% if can_complete %}<div class="success"><strong>Completion gates passed.</strong> All milestones/tasks are complete and the accepted project value is fully paid.</div><form method="POST" action="{{ url_for('admin_project_execution_complete', project_id=project.id) }}" data-confirm="Mark this {{ 'TEST ' if sandbox_mode else '' }}project completed?"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><input type="hidden" name="mode" value="{{ 'sandbox' if sandbox_mode else 'live' }}"><label style="display:flex;gap:8px;align-items:flex-start;margin:10px 0"><input type="checkbox" name="confirm_complete" value="1" required style="width:auto;margin-top:3px"> <span>I confirm the agreed execution work and payment gates are complete.</span></label><button class="btn green" type="submit">{{ 'Simulate Project Completion' if sandbox_mode else 'Complete Project' }}</button></form>{% else %}<div class="guard"><strong>Completion locked.</strong> Finish all milestones/tasks and verify the full accepted project value before completion.</div>{% endif %}</section>
</main></body></html>
"""


PROJECT_STATUS_PUBLIC_TEMPLATE = r"""
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f4c3a"><title>IBROWS Project Status</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f4;color:#10231d;font-family:Arial,sans-serif}.sheet{max-width:820px;margin:18px auto;background:#fff;padding:28px;border-radius:12px;box-shadow:0 3px 14px rgba(0,0,0,.07)}.brand{font-size:27px;font-weight:900}.tag{color:#667085}.top{border-bottom:3px solid #0f4c3a;padding-bottom:16px}.section{margin-top:24px}.section h2{font-size:18px;border-bottom:1px solid #e4e7ec;padding-bottom:7px}.progress{height:16px;border-radius:99px;background:#e4e7ec;overflow:hidden}.progress span{display:block;height:100%;background:#12b76a}.metric{background:#f9fafb;border-radius:9px;padding:11px;margin:7px 0}.milestone{padding:10px 0;border-bottom:1px solid #eaecf0}.update{border-left:4px solid #2e90fa;background:#eff8ff;padding:12px;border-radius:9px;margin:10px 0}.muted{color:#667085}.money{font-weight:850}.btn{display:inline-flex;text-decoration:none;background:#101828;color:#fff;border-radius:9px;padding:11px 13px;font-weight:850}.preview{background:#f4ebff;color:#53389e;border:2px dashed #9e77ed;border-radius:10px;padding:12px;margin-bottom:18px;line-height:1.45;font-weight:700}.backpreview{display:inline-flex;text-decoration:none;background:#53389e;color:#fff;border-radius:9px;padding:10px 12px;font-weight:850;margin-top:9px}@media(max-width:700px){.sheet{margin:0;border-radius:0;padding:20px}}</style></head><body><main class="sheet">{% if preview_mode %}<div class="preview">🧪 TEST CLIENT STATUS PREVIEW<br><span style="font-weight:400">Admin-only Sandbox preview. Nothing on this page represents real payment or a live client-visible project status.</span><br><a class="backpreview" href="{{ url_for('admin_project_execution', project_id=project.id, mode='sandbox') }}">Back to TEST Execution Workspace</a></div>{% endif %}<div class="top"><div class="brand">IBROWS Enterprise</div><div class="tag">Kupanga zofanana, mosiyana · Lilongwe, Malawi</div><div style="margin-top:13px"><strong>PROJECT STATUS</strong><br>{{ project.reference }} · {{ project.project_type_label }}</div></div><section class="section"><h2>{{ project.organisation or project.contact_name }}</h2><div class="metric"><span class="muted">Current status</span><br><strong>{{ display_status_label or project.status_label }}</strong></div><div class="metric"><span class="muted">Overall progress (weighted)</span><br><strong>{{ execution.progress_label }}%</strong></div><div class="progress"><span style="width:{{ execution.progress_percent }}%"></span></div><p class="muted" style="font-size:12px;line-height:1.45">Overall progress is calculated from each milestone's project weight, not by averaging milestone percentages equally.</p></section><section class="section"><h2>Milestones</h2>{% for m in milestones %}<div class="milestone"><strong>{{ m.title }}</strong><br><span class="muted">{{ m.status_label }} · {{ m.progress_percent }}% milestone progress · {{ m.weight_percent }}% project weight</span>{% if m.description %}<p>{{ m.description }}</p>{% endif %}</div>{% else %}<p class="muted">No client-visible milestones are available yet.</p>{% endfor %}</section><section class="section"><h2>Latest updates</h2>{% for u in updates %}<div class="update"><strong>{{ u.title }}</strong><div class="muted">{{ u.created_label }} · {{ u.progress_label or u.progress_percent }}%</div><p>{{ u.update_text }}</p></div>{% else %}<p class="muted">No published progress updates yet.</p>{% endfor %}</section><section class="section"><h2>Payments</h2><div class="metric"><span class="muted">Accepted investment</span><br><span class="money">{{ commercial.currency }} {{ '{:,.0f}'.format(commercial.final_price) }}</span></div><div class="metric"><span class="muted">{{ 'TEST payments' if preview_mode else 'Verified payments' }}</span><br><span class="money">{{ commercial.currency }} {{ '{:,.0f}'.format(commercial.total_paid) }}</span></div><div class="metric"><span class="muted">Balance</span><br><span class="money">{{ commercial.currency }} {{ '{:,.0f}'.format(commercial.total_remaining) }}</span></div>{% if not preview_mode %}{% if commercial.invoice and commercial.invoice.status != 'PAID' %}<a class="btn" href="{{ url_for('public_project_deposit_invoice_pdf', public_token=quote.public_token) }}">Download Deposit Invoice</a>{% endif %}{% for inv in stage_invoices %}{% if inv.status != 'PAID' %}<p><a class="btn" href="{{ url_for('public_project_stage_invoice_pdf', public_token=portal_token, stage=inv.stage) }}">Download {{ inv.stage_label }} Invoice</a></p>{% endif %}{% endfor %}{% endif %}</section><section class="section"><p class="muted">{% if preview_mode %}This is a Sandbox simulation of the client-facing page. Test payments, milestones and updates shown here do not change Finance, invoices or the real project.{% else %}This secure page shows client-facing project information only. Payment is recognised only after IBROWS verifies it in the internal ledger.{% endif %}</p></section></main></body></html>
"""


def _execution_render_context(project_id, sandbox_mode=False):
    project=_get_project_by_id(project_id)
    if not project: abort(404)
    quote=_latest_accepted_project_quotation(project_id)
    if not quote: abort(400)
    if sandbox_mode:
        state=_sandbox_execution_state(project_id, quote)
        if not state: abort(400)
        execution=state
        execution["progress_percent"]=_execution_progress_value(execution.get("progress_percent"))
        execution["progress_label"]=_execution_progress_label(execution.get("progress_percent"))
        # Normalize sandbox rows for template.
        for m in execution.get("milestones",[]):
            m["status_label"]=PROJECT_MILESTONE_STATUS_LABELS.get(m.get("status"),m.get("status")); m["due_date_value"]=m.get("due_date") or ""
        for t in execution.get("tasks",[]):
            t["status_label"]=PROJECT_TASK_STATUS_LABELS.get(t.get("status"),t.get("status")); t["priority_label"]=PROJECT_TASK_PRIORITY_LABELS.get(t.get("priority"),t.get("priority")); t["due_date_value"]=t.get("due_date") or ""
        updates=execution.get("updates") or []
        for u in updates:
            u["progress_percent"]=_execution_progress_value(u.get("progress_percent"))
            u["progress_label"]=_execution_progress_label(u.get("progress_percent"))
            u.setdefault("created_label",u.get("created_label") or datetime.now(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M")); u.setdefault("published",False)
        execution["updates"]=updates
        payment_summary=_execution_payment_summary(project_id, quote, sandbox_state=state["sandbox"])
        total_paid=state["sandbox"]["total_paid"]; total_remaining=state["sandbox"]["total_remaining"]; started_label=state["sandbox"].get("started_label") or ""; invoice_map={}
        can_complete=(execution.get("status")=="IN_PROGRESS" and bool(execution.get("milestones")) and all(m.get("status")=="COMPLETED" for m in execution.get("milestones",[])) and all(t.get("status")=="DONE" for t in execution.get("tasks",[])) and all(r.get("paid_ok") for r in payment_summary["rows"]))
        client_status_url=""
    else:
        execution=_execution_live_rows(project_id)
        if not execution: abort(400)
        commercial=_project_commercial_state(project_id, quote)
        payment_summary=_execution_payment_summary(project_id, quote)
        invoices=_execution_stage_invoices(project_id, quote); invoice_map={i["stage"]:i for i in invoices}
        total_paid=commercial["total_paid"]; total_remaining=commercial["total_remaining"]; started_label=execution.get("started_label") or ""; can_complete=_execution_can_complete(execution,payment_summary) and execution.get("status")=="IN_PROGRESS"; client_status_url=url_for("public_project_status", public_token=_ensure_project_portal_token(project_id), _external=True)
    return dict(project=project,quote=quote,execution=execution,payment_summary=payment_summary,total_paid=total_paid,total_remaining=total_remaining,started_label=started_label,invoice_map=invoice_map,can_complete=can_complete,client_status_url=client_status_url,sandbox_mode=sandbox_mode)


@app.route("/admin/projects/<int:project_id>/execution", methods=["GET"])
@admin_required
def admin_project_execution(project_id):
    sandbox_mode=request.args.get("mode")=="sandbox"
    ctx=_execution_render_context(project_id,sandbox_mode=sandbox_mode)
    return render_template_string(PROJECT_EXECUTION_ADMIN_TEMPLATE,csrf_token=get_csrf_token(),milestone_statuses=PROJECT_MILESTONE_STATUS_LABELS,task_statuses=PROJECT_TASK_STATUS_LABELS,task_priorities=PROJECT_TASK_PRIORITY_LABELS,saved_milestone=request.args.get("saved_milestone"),task_added=request.args.get("task_added"),saved_task=request.args.get("saved_task"),task_deleted=request.args.get("task_deleted"),**ctx),200


def _execution_mode_from_form():
    return str(request.form.get("mode") or "live").lower()=="sandbox"


@app.route("/admin/projects/<int:project_id>/execution/milestones/<milestone_id>/update", methods=["POST"])
@admin_required
def admin_project_execution_milestone_update(project_id,milestone_id):
    validate_csrf(); sandbox_mode=_execution_mode_from_form(); status=str(request.form.get("status") or "PENDING").upper();
    if status not in PROJECT_MILESTONE_STATUS_LABELS: abort(400)
    try: progress=max(0,min(100,int(request.form.get("progress_percent") or 0)))
    except Exception: abort(400)
    if status=="COMPLETED": progress=100
    assigned=_project_clean(request.form.get("assigned_to"),160); due=_execution_safe_date(request.form.get("due_date")); visible=request.form.get("client_visible")=="1"
    if sandbox_mode:
        quote=_latest_accepted_project_quotation(project_id); state=_sandbox_execution_state(project_id,quote)
        if not state: abort(400)
        found=False
        for m in state.get("milestones",[]):
            if str(m.get("id"))==str(milestone_id): m.update(status=status,progress_percent=progress,assigned_to=assigned,due_date=due or "",client_visible=visible); found=True; break
        if not found: abort(404)
        _sandbox_save_execution(project_id,_sandbox_recalc_execution(state),state.get("updates") or [])
        return redirect(url_for("admin_project_execution",project_id=project_id,mode="sandbox",saved_milestone=str(milestone_id),_anchor=f"milestone-{milestone_id}"))
    try: mid=int(milestone_id)
    except Exception: abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("UPDATE project_milestones SET status=%s,progress_percent=%s,assigned_to=NULLIF(%s,''),due_date=%s,client_visible=%s,completed_at=CASE WHEN %s='COMPLETED' THEN COALESCE(completed_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND project_id=%s RETURNING title",(status,progress,assigned,due,visible,status,mid,project_id)); row=cur.fetchone();
            if not row: abort(404)
            _project_activity_insert(cur,project_id,"MILESTONE_UPDATED",f"Execution milestone updated: {row[0]} — {PROJECT_MILESTONE_STATUS_LABELS[status]}, {progress}%.")
        conn.commit()
    _execution_recalculate_progress(project_id); return redirect(url_for("admin_project_execution",project_id=project_id,saved_milestone=str(milestone_id),_anchor=f"milestone-{milestone_id}"))


@app.route("/admin/projects/<int:project_id>/execution/tasks/add", methods=["POST"])
@admin_required
def admin_project_execution_task_add(project_id):
    validate_csrf(); sandbox_mode=_execution_mode_from_form(); title=_project_clean(request.form.get("title"),300); assigned=_project_clean(request.form.get("assigned_to"),160); due=_execution_safe_date(request.form.get("due_date")); milestone_raw=str(request.form.get("milestone_id") or "").strip()
    if not title: abort(400)
    if sandbox_mode:
        quote=_latest_accepted_project_quotation(project_id); state=_sandbox_execution_state(project_id,quote)
        if not state: abort(400)
        ids=[int(str(t.get("id","t0")).lstrip("t") or 0) for t in state.get("tasks",[]) if str(t.get("id","")).startswith("t")]; tid=f"t{max(ids+[0])+1}"; state.setdefault("tasks",[]).append({"id":tid,"milestone_id":milestone_raw or None,"title":title,"description":"","status":"TODO","priority":"NORMAL","assigned_to":assigned,"due_date":due or "","client_visible":False}); _sandbox_save_execution(project_id,state,state.get("updates") or []); return redirect(url_for("admin_project_execution",project_id=project_id,mode="sandbox",task_added=tid,_anchor=f"task-{tid}"))
    milestone_id=int(milestone_raw) if milestone_raw.isdigit() else None
    with get_db() as conn:
        with conn.cursor() as cur:
            if milestone_id:
                cur.execute("SELECT 1 FROM project_milestones WHERE id=%s AND project_id=%s",(milestone_id,project_id));
                if not cur.fetchone(): abort(400)
            cur.execute("INSERT INTO project_tasks(project_id,milestone_id,title,status,priority,assigned_to,due_date,client_visible,updated_at) VALUES(%s,%s,%s,'TODO','NORMAL',NULLIF(%s,''),%s,FALSE,NOW()) RETURNING id",(project_id,milestone_id,title,assigned,due)); new_task_id=cur.fetchone()[0]; _project_activity_insert(cur,project_id,"TASK_CREATED",f"Execution task added: {title}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id,task_added=str(new_task_id),_anchor=f"task-{new_task_id}"))


@app.route("/admin/projects/<int:project_id>/execution/tasks/<task_id>/update", methods=["POST"])
@admin_required
def admin_project_execution_task_update(project_id,task_id):
    validate_csrf(); sandbox_mode=_execution_mode_from_form(); status=str(request.form.get("status") or "TODO").upper(); priority=str(request.form.get("priority") or "NORMAL").upper(); assigned=_project_clean(request.form.get("assigned_to"),160); due=_execution_safe_date(request.form.get("due_date"))
    if status not in PROJECT_TASK_STATUS_LABELS or priority not in PROJECT_TASK_PRIORITY_LABELS: abort(400)
    if sandbox_mode:
        state=_sandbox_execution_state(project_id,_latest_accepted_project_quotation(project_id));
        if not state: abort(400)
        found=False
        for t in state.get("tasks",[]):
            if str(t.get("id"))==str(task_id): t.update(status=status,priority=priority,assigned_to=assigned,due_date=due or ""); found=True; break
        if not found: abort(404)
        _sandbox_save_execution(project_id,state,state.get("updates") or []); return redirect(url_for("admin_project_execution",project_id=project_id,mode="sandbox",saved_task=str(task_id),_anchor=f"task-{task_id}"))
    try: tid=int(task_id)
    except Exception: abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("UPDATE project_tasks SET status=%s,priority=%s,assigned_to=NULLIF(%s,''),due_date=%s,completed_at=CASE WHEN %s='DONE' THEN COALESCE(completed_at,NOW()) ELSE NULL END,updated_at=NOW() WHERE id=%s AND project_id=%s RETURNING title",(status,priority,assigned,due,status,tid,project_id)); row=cur.fetchone();
            if not row: abort(404)
            _project_activity_insert(cur,project_id,"TASK_UPDATED",f"Execution task updated: {row[0]} — {PROJECT_TASK_STATUS_LABELS[status]}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id,saved_task=str(task_id),_anchor=f"task-{task_id}"))


@app.route("/admin/projects/<int:project_id>/execution/tasks/<task_id>/delete", methods=["POST"])
@admin_required
def admin_project_execution_task_delete(project_id,task_id):
    validate_csrf(); sandbox_mode=_execution_mode_from_form()
    if sandbox_mode:
        state=_sandbox_execution_state(project_id,_latest_accepted_project_quotation(project_id));
        if not state: abort(400)
        old=len(state.get("tasks",[])); state["tasks"]=[t for t in state.get("tasks",[]) if str(t.get("id"))!=str(task_id)]
        if len(state["tasks"])==old: abort(404)
        _sandbox_save_execution(project_id,state,state.get("updates") or []); return redirect(url_for("admin_project_execution",project_id=project_id,mode="sandbox",task_deleted="1",_anchor="tasks"))
    try: tid=int(task_id)
    except Exception: abort(404)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM project_tasks WHERE id=%s AND project_id=%s RETURNING title",(tid,project_id)); row=cur.fetchone();
            if not row: abort(404)
            _project_activity_insert(cur,project_id,"TASK_DELETED",f"Execution task deleted by IBROWS: {row[0]}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id,task_deleted="1",_anchor="tasks"))


@app.route("/admin/projects/<int:project_id>/execution/updates/add", methods=["POST"])
@admin_required
def admin_project_execution_update_add(project_id):
    validate_csrf(); sandbox_mode=_execution_mode_from_form(); title=_project_clean(request.form.get("title"),200); body=_project_clean(request.form.get("update_text"),3000)
    if not title or not body: abort(400)
    if sandbox_mode:
        state=_sandbox_execution_state(project_id,_latest_accepted_project_quotation(project_id));
        if not state: abort(400)
        updates=state.get("updates") or []; current_progress=_execution_progress_value(state.get("progress_percent")); updates.insert(0,{"id":f"u{len(updates)+1}","title":title,"update_text":body,"progress_percent":current_progress,"progress_label":_execution_progress_label(current_progress),"published":False,"created_label":datetime.now(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M")}); _sandbox_save_execution(project_id,state,updates); return redirect(url_for("admin_project_execution",project_id=project_id,mode="sandbox"))
    execution=_execution_live_rows(project_id); published=request.form.get("published")=="1"
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("INSERT INTO project_client_updates(project_id,title,update_text,progress_percent,published,updated_at) VALUES(%s,%s,%s,%s,%s,NOW())",(project_id,title,body,_execution_progress_value(execution.get("progress_percent")),published)); _project_activity_insert(cur,project_id,"CLIENT_UPDATE",f"Project update {'published to client' if published else 'saved internally'}: {title}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id))


@app.route("/admin/projects/<int:project_id>/execution/invoices/<stage>/create", methods=["POST"])
@admin_required
def admin_project_stage_invoice_create(project_id,stage):
    validate_csrf(); stage=str(stage or "").upper()
    if stage not in PROJECT_STAGE_INVOICE_LABELS: abort(404)
    quote=_latest_accepted_project_quotation(project_id); execution=_get_project_execution(project_id)
    if not quote or not execution or execution.get("status") not in {"IN_PROGRESS","COMPLETED"}: abort(400)
    if _project_sandbox_enabled(project_id,quote): abort(409)
    summary=_execution_payment_summary(project_id,quote); row=next((x for x in summary["rows"] if x["stage"]==stage),None)
    if not row or row["required"]<=0: abort(400)
    year=datetime.now(ADMIN_TIMEZONE).year; suffix="M2" if stage=="MILESTONE_2" else "F"; number=f"IBR-INV-{year}-{project_id:04d}-{suffix}R{int(quote.get('revision_no') or 1)}"
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("INSERT INTO project_stage_invoices(project_id,quotation_id,stage,invoice_number,amount,currency,status,updated_at) VALUES(%s,%s,%s,%s,%s,%s,'UNPAID',NOW()) ON CONFLICT(quotation_id,stage) DO NOTHING RETURNING id",(project_id,quote["id"],stage,number,row["required"],summary["currency"])); created=cur.fetchone()
            if created: _project_activity_insert(cur,project_id,"STAGE_INVOICE_CREATED",f"{PROJECT_STAGE_INVOICE_LABELS[stage]} invoice {number} created for {summary['currency']} {row['required']:,.0f}.")
        conn.commit()
    return redirect(url_for("admin_project_execution",project_id=project_id))


@app.route("/admin/projects/<int:project_id>/execution/invoices/<stage>/pdf", methods=["GET"])
@admin_required
def admin_project_stage_invoice_pdf(project_id,stage):
    stage=str(stage or "").upper(); quote=_latest_accepted_project_quotation(project_id)
    if not quote or stage not in PROJECT_STAGE_INVOICE_LABELS: abort(404)
    invoices=_execution_stage_invoices(project_id,quote); inv=next((i for i in invoices if i["stage"]==stage),None)
    if not inv: abort(404)
