# =========================================================
# IBROWS AUDIT REMEDIATION V43
# =========================================================
# This section intentionally overrides selected V42 helpers/view functions at
# runtime. Existing working features remain intact while security, accounting,
# privacy and concurrency-sensitive paths use the hardened implementations.

_V42_SEND_WHATSAPP_MESSAGE = send_whatsapp_message
_V42_SEND_WHATSAPP_DOCUMENT = send_whatsapp_document
_V42_QUOTATION_SNAPSHOT = _quotation_snapshot
_V42_ADMIN_SUCCESS_FEEDBACK = _admin_success_feedback_message

V43_CV_RESERVATION_MINUTES = 30
V43_COST_IMPORT_TTL_MINUTES = 30
V43_PUBLIC_RATE_WINDOW_SECONDS = 3600


def _v43_validate_required_configuration():
    if str(os.environ.get("IBROWS_ALLOW_INCOMPLETE_CONFIG") or "").strip() == "1":
        return
    required = {
        "DATABASE_URL": DATABASE_URL,
        "FLASK_SECRET_KEY": FLASK_SECRET_KEY,
        "ADMIN_USERNAME": ADMIN_USERNAME,
        "ADMIN_PASSWORD": ADMIN_PASSWORD,
        "VERIFY_TOKEN": VERIFY_TOKEN,
        "WHATSAPP_TOKEN": WHATSAPP_TOKEN,
        "PHONE_NUMBER_ID": PHONE_NUMBER_ID,
        "META_APP_SECRET": META_APP_SECRET,
        "OPENAI_API_KEY": OPENAI_API_KEY,
    }
    missing = [name for name, value in required.items() if not str(value or "").strip()]
    if missing:
        raise RuntimeError("Missing required production configuration: " + ", ".join(missing))


def _init_v43_schema():
    with get_db() as conn:
        with conn.cursor() as cur:
            # Immutable CRM document snapshots and void state.
            cur.execute("ALTER TABLE business_documents ADD COLUMN IF NOT EXISTS snapshot JSONB")
            cur.execute("ALTER TABLE business_documents ADD COLUMN IF NOT EXISTS document_status TEXT NOT NULL DEFAULT 'ACTIVE'")
            cur.execute("ALTER TABLE business_documents ADD COLUMN IF NOT EXISTS voided_at TIMESTAMPTZ")
            cur.execute("ALTER TABLE business_documents ADD COLUMN IF NOT EXISTS void_reason TEXT")

            # CV entitlement reservation prevents simultaneous reuse while delivery is in progress.
            cur.execute("ALTER TABLE leads ADD COLUMN IF NOT EXISTS entitlement_reserved_at TIMESTAMPTZ")
            cur.execute("ALTER TABLE leads ADD COLUMN IF NOT EXISTS entitlement_reservation_token TEXT")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_leads_entitlement_reserved ON leads(entitlement_reserved_at)")

            # Project portal token is separate from a quotation response token.
            cur.execute("ALTER TABLE project_assessments ADD COLUMN IF NOT EXISTS portal_token TEXT")
            cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_project_assessments_portal_token ON project_assessments(portal_token) WHERE portal_token IS NOT NULL")
            cur.execute("ALTER TABLE project_assessments ADD COLUMN IF NOT EXISTS alert_status TEXT NOT NULL DEFAULT 'NOT_SENT'")
            cur.execute("ALTER TABLE project_assessments ADD COLUMN IF NOT EXISTS alert_attempts INTEGER NOT NULL DEFAULT 0")
            cur.execute("ALTER TABLE project_assessments ADD COLUMN IF NOT EXISTS alert_last_error TEXT")
            cur.execute("ALTER TABLE project_assessments ADD COLUMN IF NOT EXISTS alert_sent_at TIMESTAMPTZ")

            # Quotation revisions can be explicitly superseded.
            cur.execute("ALTER TABLE project_quotations DROP CONSTRAINT IF EXISTS project_quotations_status_check")
            cur.execute("""
                ALTER TABLE project_quotations
                ADD CONSTRAINT project_quotations_status_check
                CHECK (status IN ('ISSUED','VIEWED','ACCEPTED','DECLINED','EXPIRED','SUPERSEDED'))
            """)

            # Reconcile harmless duplicate ACCEPTED revisions before enforcing one authoritative revision.
            cur.execute("""
                SELECT project_id, array_agg(id ORDER BY revision_no DESC, id DESC)
                FROM project_quotations
                WHERE status='ACCEPTED'
                GROUP BY project_id
                HAVING COUNT(*) > 1
            """)
            duplicate_accepted = cur.fetchall()
            for project_id, quote_ids in duplicate_accepted:
                cur.execute(
                    "SELECT COUNT(*) FROM project_payments WHERE project_id=%s AND quotation_id = ANY(%s)",
                    (project_id, quote_ids),
                )
                payment_count = int((cur.fetchone() or [0])[0] or 0)
                cur.execute("SELECT COUNT(*) FROM project_execution WHERE project_id=%s", (project_id,))
                execution_count = int((cur.fetchone() or [0])[0] or 0)
                if payment_count or execution_count:
                    raise RuntimeError(
                        f"Project {project_id} has multiple accepted quotation revisions with commercial activity; manual reconciliation is required before V43 can start."
                    )
                keep_id = int(quote_ids[0])
                cur.execute(
                    "UPDATE project_quotations SET status='SUPERSEDED', updated_at=NOW() WHERE project_id=%s AND status='ACCEPTED' AND id<>%s",
                    (project_id, keep_id),
                )
            cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_project_one_accepted_quote ON project_quotations(project_id) WHERE status='ACCEPTED'")

            # Project payment idempotency survives browser double-submit.
            cur.execute("ALTER TABLE project_payments ADD COLUMN IF NOT EXISTS request_token TEXT")
            cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_project_payments_request_token ON project_payments(request_token) WHERE request_token IS NOT NULL")
            cur.execute("ALTER TABLE project_payment_void_audit ADD COLUMN IF NOT EXISTS request_token TEXT")
            cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_project_void_request_token ON project_payment_void_audit(request_token) WHERE request_token IS NOT NULL")

            # Durable pending WhatsApp delivery manifest. File bytes are erased as soon as each item sends.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS whatsapp_delivery_outbox (
                    id BIGSERIAL PRIMARY KEY,
                    message_id TEXT NOT NULL,
                    customer_number TEXT NOT NULL,
                    item_order INTEGER NOT NULL,
                    item_type TEXT NOT NULL CHECK (item_type IN ('text','document')),
                    text_body TEXT,
                    filename TEXT,
                    mime_type TEXT,
                    file_bytes BYTEA,
                    caption TEXT,
                    status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','FAILED')),
                    attempts INTEGER NOT NULL DEFAULT 0,
                    last_error TEXT,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    UNIQUE(message_id, item_order)
                )
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_whatsapp_outbox_message ON whatsapp_delivery_outbox(message_id, item_order)")

            # Server-side staging replaces large Flask session cookies for costing imports.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS project_cost_import_staging (
                    token TEXT PRIMARY KEY,
                    project_id BIGINT NOT NULL REFERENCES project_assessments(id) ON DELETE CASCADE,
                    payload JSONB NOT NULL,
                    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    expires_at TIMESTAMPTZ NOT NULL
                )
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_project_cost_import_expiry ON project_cost_import_staging(expires_at)")

            # Shared login/public throttling survives worker restarts.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS admin_login_attempts (
                    client_key TEXT PRIMARY KEY,
                    attempts INTEGER NOT NULL DEFAULT 0,
                    window_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                    locked_until TIMESTAMPTZ
                )
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public_rate_limits (
                    rate_key TEXT PRIMARY KEY,
                    hit_count INTEGER NOT NULL DEFAULT 0,
                    window_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)

            # Expense corrections preserve an immutable audit row instead of disappearing.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS business_expense_void_audit (
                    id BIGSERIAL PRIMARY KEY,
                    original_expense_id BIGINT NOT NULL UNIQUE,
                    amount NUMERIC(14,2) NOT NULL,
                    currency TEXT NOT NULL,
                    category TEXT NOT NULL,
                    service TEXT,
                    description TEXT NOT NULL,
                    payment_method TEXT NOT NULL,
                    reference TEXT,
                    original_expense_date TIMESTAMPTZ NOT NULL,
                    void_reason TEXT NOT NULL,
                    voided_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                )
            """)

            # General budgets use an empty service key instead of NULL so uniqueness is real.
            cur.execute("""
                DELETE FROM business_expense_budgets a
                USING business_expense_budgets b
                WHERE a.id < b.id
                  AND a.budget_year=b.budget_year
                  AND a.budget_month=b.budget_month
                  AND a.currency=b.currency
                  AND a.category=b.category
                  AND COALESCE(a.service,'')=COALESCE(b.service,'')
            """)
            cur.execute("UPDATE business_expense_budgets SET service='' WHERE service IS NULL")
            cur.execute("ALTER TABLE business_expense_budgets ALTER COLUMN service SET DEFAULT ''")
            cur.execute("ALTER TABLE business_expense_budgets ALTER COLUMN service SET NOT NULL")

            # Prevent concurrent duplicate open service leads at database level where canonical labels already match.
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_active_customer_service_lookup
                ON leads(customer_number, lower(btrim(service)))
                WHERE status IN ('NEW','CONTACTED')
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                  AND entitlement_consumed_at IS NULL
            """)
        conn.commit()


def _v43_trusted_client_ip():
    trust_proxy = bool(os.environ.get("RENDER")) or str(os.environ.get("IBROWS_TRUST_PROXY_HEADERS") or "").strip() == "1"
    if trust_proxy:
        forwarded = str(request.headers.get("X-Forwarded-For") or "")
        if forwarded:
            candidate = forwarded.split(",", 1)[0].strip()
            try:
                return str(ipaddress.ip_address(candidate))
            except ValueError:
                pass
    return request.remote_addr or "unknown"


def _login_client_key():
    return _v43_trusted_client_ip()


def _login_is_locked(client_key):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT attempts, window_started_at, locked_until FROM admin_login_attempts WHERE client_key=%s", (client_key,))
            row = cur.fetchone()
            if not row:
                return False
            attempts, window_started_at, locked_until = row
            cur.execute("SELECT NOW()")
            now_db = cur.fetchone()[0]
            if locked_until and locked_until > now_db:
                return True
            if locked_until and locked_until <= now_db:
                cur.execute("DELETE FROM admin_login_attempts WHERE client_key=%s", (client_key,))
                conn.commit()
                return False
            if window_started_at < now_db - timedelta(seconds=LOGIN_WINDOW_SECONDS):
                cur.execute("DELETE FROM admin_login_attempts WHERE client_key=%s", (client_key,))
                conn.commit()
                return False
            return False


def _record_failed_login(client_key):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                INSERT INTO admin_login_attempts(client_key,attempts,window_started_at,locked_until)
                VALUES(%s,1,NOW(),NULL)
                ON CONFLICT(client_key) DO UPDATE SET
                    attempts=CASE
                        WHEN admin_login_attempts.window_started_at < NOW() - (%s * INTERVAL '1 second') THEN 1
                        ELSE admin_login_attempts.attempts + 1 END,
                    window_started_at=CASE
                        WHEN admin_login_attempts.window_started_at < NOW() - (%s * INTERVAL '1 second') THEN NOW()
                        ELSE admin_login_attempts.window_started_at END,
                    locked_until=CASE
                        WHEN (CASE WHEN admin_login_attempts.window_started_at < NOW() - (%s * INTERVAL '1 second') THEN 1 ELSE admin_login_attempts.attempts + 1 END) >= %s
                        THEN NOW() + (%s * INTERVAL '1 second')
                        ELSE admin_login_attempts.locked_until END
                RETURNING attempts
            """, (client_key, LOGIN_WINDOW_SECONDS, LOGIN_WINDOW_SECONDS, LOGIN_WINDOW_SECONDS, LOGIN_MAX_ATTEMPTS, LOGIN_LOCKOUT_SECONDS))
        conn.commit()


def _clear_failed_logins(client_key):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM admin_login_attempts WHERE client_key=%s", (client_key,))
        conn.commit()


def _v43_rate_limit(rate_key, max_hits, window_seconds=V43_PUBLIC_RATE_WINDOW_SECONDS):
    rate_key = str(rate_key or "")[:240]
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                INSERT INTO public_rate_limits(rate_key,hit_count,window_started_at)
                VALUES(%s,1,NOW())
                ON CONFLICT(rate_key) DO UPDATE SET
                    hit_count=CASE
                        WHEN public_rate_limits.window_started_at < NOW() - (%s * INTERVAL '1 second') THEN 1
                        ELSE public_rate_limits.hit_count + 1 END,
                    window_started_at=CASE
                        WHEN public_rate_limits.window_started_at < NOW() - (%s * INTERVAL '1 second') THEN NOW()
                        ELSE public_rate_limits.window_started_at END
                RETURNING hit_count
            """, (rate_key, window_seconds, window_seconds))
            hits = int((cur.fetchone() or [0])[0] or 0)
        conn.commit()
    return hits <= int(max_hits)


def _v43_verify_meta_signature():
    if request.path != "/webhook" or request.method != "POST":
        return None
    if not META_APP_SECRET:
        abort(503)
    supplied = str(request.headers.get("X-Hub-Signature-256") or "")
    if not supplied.startswith("sha256="):
        abort(403)
    raw_body = request.get_data(cache=True)
    expected = "sha256=" + hmac.new(META_APP_SECRET.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        abort(403)
    return None


def _v43_public_abuse_guard():
    if request.method != "POST":
        return None
    ip = _v43_trusted_client_ip()
    if request.path == "/project-discovery/start":
        if not _v43_rate_limit(f"pd-start:{ip}", 10, 3600):
            abort(429)
    elif request.path.startswith("/project-discovery/"):
        limit = 12 if request.path.endswith("/step/6") else 80
        if not _v43_rate_limit(f"pd-step:{ip}:{request.path.rsplit('/',1)[-1]}", limit, 3600):
            abort(429)
    return None


app.before_request(_v43_verify_meta_signature)
app.before_request(_v43_public_abuse_guard)


def _v43_sensitive_response_headers(response):
    sensitive = (
        request.path.startswith("/quotation/")
        or request.path.startswith("/project-status/")
        or request.path.startswith("/project-discovery/")
    )
    if sensitive:
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, private, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        response.headers["X-Robots-Tag"] = "noindex, nofollow, noarchive"
    return response


app.after_request(_v43_sensitive_response_headers)


def _v43_csv_cell(value):
    if value is None:
        return ""
    text_value = str(value)
    stripped = text_value.lstrip()
    if stripped.startswith(("=", "+", "-", "@")):
        return "'" + text_value
    return value


def _csv_text(headers, rows):
    output = io.StringIO(newline="")
    writer = csv.writer(output)
    writer.writerow(headers)
    for row in rows:
        writer.writerow([_v43_csv_cell(value) for value in row])
    return output.getvalue().encode("utf-8-sig")


def _v43_payment_schedule_from_costing(costing):
    costing = _costing_view(costing)
    deposit = _money_decimal(costing.get("deposit_percent"), Decimal("50"))
    terms = str(costing.get("payment_terms") or "")
    m2_match = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+after\s+functional\s+demonstration", terms, re.I)
    final_match = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+at\s+production\s+deployment", terms, re.I)
    milestone = Decimal(m2_match.group(1)) if m2_match else None
    final = Decimal(final_match.group(1)) if final_match else None
    remaining = Decimal("100") - deposit
    if milestone is None and final is None:
        milestone = min(Decimal("30"), max(Decimal("0"), remaining))
        final = remaining - milestone
    elif milestone is None:
        milestone = remaining - final
    elif final is None:
        final = remaining - milestone
    values = {"DEPOSIT": deposit, "MILESTONE_2": milestone, "FINAL": final}
    if any(v is None or v < 0 for v in values.values()):
        raise ValueError("Project payment schedule contains a negative or missing percentage.")
    total = sum(values.values(), Decimal("0"))
    if total != Decimal("100"):
        raise ValueError(f"Project payment schedule must total 100%; current total is {total}%. ")
    return {key: str(value.quantize(Decimal("0.01"))) for key, value in values.items()}


def _quotation_snapshot(project, costing):
    snapshot = _V42_QUOTATION_SNAPSHOT(project, costing)
    snapshot["payment_schedule"] = _v43_payment_schedule_from_costing(costing)
    return snapshot


def _execution_schedule_percentages(quote_item):
    schedule = (quote_item.get("snapshot") or {}).get("payment_schedule") or {}
    if schedule:
        try:
            out = {key: float(Decimal(str(schedule.get(key, "0")))) for key in ("DEPOSIT", "MILESTONE_2", "FINAL")}
            if round(sum(out.values()), 6) == 100.0 and all(v >= 0 for v in out.values()):
                return out
        except Exception:
            pass
    # Legacy quotation fallback: parse once, but normalize to a guaranteed 100% schedule.
    pricing = quote_item.get("pricing") or {}
    deposit_pct = float(pricing.get("deposit_percent") or 0)
    terms = str((quote_item.get("terms") or {}).get("payment_terms") or "")
    m2 = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+after\s+functional\s+demonstration", terms, re.I)
    mf = re.search(r"([0-9]+(?:\.[0-9]+)?)%\s+at\s+production\s+deployment", terms, re.I)
    milestone_pct = float(m2.group(1)) if m2 else 0.0
    final_pct = float(mf.group(1)) if mf else max(0.0, 100.0 - deposit_pct - milestone_pct)
    total = deposit_pct + milestone_pct + final_pct
    if abs(total - 100.0) > 1e-6:
        final_pct = max(0.0, 100.0 - deposit_pct - milestone_pct)
    return {"DEPOSIT": deposit_pct, "MILESTONE_2": milestone_pct, "FINAL": final_pct}


PROJECT_QUOTE_STATUSES["SUPERSEDED"] = "Superseded"


def _ensure_project_portal_token(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT portal_token FROM project_assessments WHERE id=%s FOR UPDATE", (project_id,))
            row = cur.fetchone()
            if not row:
                raise ValueError("Project not found")
            token = row[0]
            if not token:
                token = secrets.token_urlsafe(32)
                cur.execute("UPDATE project_assessments SET portal_token=%s, updated_at=NOW() WHERE id=%s", (token, project_id))
        conn.commit()
    return token


def _get_project_by_portal_token(portal_token):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE portal_token=%s", (portal_token,))
            row = cur.fetchone()
    return _get_project_by_id(row[0]) if row else None


_V42_DELETE_CUSTOMER_DATA = delete_customer_data
_V42_CLEANUP_EXPIRED_DATA = cleanup_expired_data


def get_verified_service_payment_state(customer_number, service, fallback_required_mwk=None):
    """Authoritative ledger state; approved fixed-price services always use their approved price."""
    wanted = canonicalize_service(service)
    fixed_required = CAREER_SERVICE_DEFAULT_PRICES_MWK.get(wanted)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT l.id,l.service,l.estimated_value,COALESCE(l.value_currency,'MWK'),
                       l.quote_status,l.status,l.updated_at,
                       COALESCE(SUM(CASE WHEN p.currency=COALESCE(l.value_currency,'MWK') THEN p.amount ELSE 0 END),0)
                FROM leads l
                LEFT JOIN lead_payments p ON p.lead_id=l.id
                WHERE l.customer_number=%s
                  AND l.status IN ('NEW','CONTACTED')
                  AND l.merged_into_lead_id IS NULL
                  AND l.privacy_deleted_at IS NULL
                  AND l.entitlement_consumed_at IS NULL
                GROUP BY l.id,l.service,l.estimated_value,l.value_currency,l.quote_status,l.status,l.updated_at
                ORDER BY l.updated_at DESC,l.id DESC
                """,
                (customer_number,),
            )
            rows = cur.fetchall()
    row = next((r for r in rows if canonicalize_service(r[1]) == wanted), None)
    required = fixed_required
    if required is None and fallback_required_mwk is not None:
        required = Decimal(str(fallback_required_mwk))
    if not row:
        return {
            "lead_id": None,"service": wanted,"currency": "MWK","required": required,
            "paid": Decimal("0"),"balance": required,"status": "NOT_VERIFIED","quote_status": "NOT_STARTED",
        }
    lead_id,_service,estimated,currency,quote_status,_status,_updated,paid_total = row
    paid = Decimal(paid_total or 0)
    if fixed_required is not None:
        required = Decimal(fixed_required)
        if currency != "MWK":
            return {
                "lead_id": lead_id,"service": wanted,"currency": currency,"required": required,
                "paid": paid,"balance": required,"status": "NOT_VERIFIED","quote_status": quote_status or "NOT_STARTED",
            }
    elif required is None and estimated is not None:
        required = Decimal(estimated)
    balance = None if required is None else max(required - paid, Decimal("0"))
    if paid <= 0:
        state = "NOT_PAID"
    elif required is None:
        state = "RECEIVED_UNPRICED"
    elif paid < required:
        state = "PART_PAID"
    else:
        state = "PAID"
    return {
        "lead_id": lead_id,"service": wanted,"currency": currency,"required": required,
        "paid": paid,"balance": balance,"status": state,"quote_status": quote_status or "NOT_STARTED",
    }


def create_or_update_lead(customer_number, customer_name, service, summary, handover_reason):
    """Concurrency-safe lead creation using a transaction-scoped advisory lock."""
    service = canonicalize_service(service)
    lock_key = f"{customer_number}|{service}"[:500]
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", (lock_key,))
            cur.execute(
                """
                SELECT id,service FROM leads
                WHERE customer_number=%s
                  AND status IN ('NEW','CONTACTED')
                  AND merged_into_lead_id IS NULL
                  AND privacy_deleted_at IS NULL
                  AND entitlement_consumed_at IS NULL
                ORDER BY updated_at DESC,created_at DESC
                FOR UPDATE
                """,
                (customer_number,),
            )
            existing = None
            for candidate_id,candidate_service in cur.fetchall():
                if canonicalize_service(candidate_service).casefold() == service.casefold():
                    existing = (candidate_id,)
                    break
            if existing:
                lead_id = existing[0]
                cur.execute(
                    """
                    UPDATE leads SET customer_name=COALESCE(NULLIF(%s,''),customer_name),service=%s,
                        summary=%s,handover_reason=%s,updated_at=NOW() WHERE id=%s
                    """,
                    (customer_name,service,summary,handover_reason,lead_id),
                )
                _activity_insert(cur,lead_id,"AI_UPDATE","Lead details refreshed from the WhatsApp conversation.")
                created = False
            else:
                cur.execute(
                    """
                    INSERT INTO leads(customer_number,customer_name,service,summary,handover_reason)
                    VALUES(%s,%s,%s,%s,%s) RETURNING id
                    """,
                    (customer_number,customer_name,service,summary,handover_reason),
                )
                lead_id = cur.fetchone()[0]
                _activity_insert(cur,lead_id,"LEAD_CREATED",f"{service} lead created from WhatsApp.")
                created = True
        conn.commit()
    print(f"{'NEW LEAD CREATED' if created else 'LEAD UPDATED'}: {lead_id}", flush=True)
    return lead_id, created


