def _v43_locked_quote(cur,project_id,status="ACCEPTED"):
    cur.execute(_quotation_select_sql()+" WHERE project_id=%s AND status=%s ORDER BY revision_no DESC,id DESC LIMIT 1 FOR UPDATE",(project_id,status))
    row=cur.fetchone(); return _quotation_row_to_dict(row) if row else None


def _v43_ensure_deposit_invoice_locked(cur,quote_item):
    cur.execute("SELECT id,amount,currency,status FROM project_invoices WHERE quotation_id=%s FOR UPDATE",(quote_item["id"],)); row=cur.fetchone()
    if row: return {"id":row[0],"amount":Decimal(row[1]),"currency":row[2],"status":row[3]}
    amount=_money_decimal((quote_item.get("pricing") or {}).get("deposit_amount"))
    if amount<=0: return None
    year=quote_item["issued_at"].astimezone(ADMIN_TIMEZONE).year if quote_item.get("issued_at") else datetime.now(ADMIN_TIMEZONE).year
    number=f"IBR-INV-{year}-{quote_item['project_id']:04d}-D{int(quote_item.get('revision_no') or 1)}"
    cur.execute("INSERT INTO project_invoices(project_id,quotation_id,invoice_number,invoice_type,amount,currency,status,issued_at,updated_at) VALUES(%s,%s,%s,'DEPOSIT',%s,%s,'UNPAID',NOW(),NOW()) ON CONFLICT(quotation_id) DO UPDATE SET updated_at=project_invoices.updated_at RETURNING id,amount,currency,status",(quote_item["project_id"],quote_item["id"],number,amount,quote_item.get("currency") or "MWK"))
    row=cur.fetchone(); return {"id":row[0],"amount":Decimal(row[1]),"currency":row[2],"status":row[3]}


def _v43_quote_totals_locked(cur,quote_item):
    cur.execute("SELECT COALESCE(SUM(amount),0) FROM project_payments WHERE quotation_id=%s",(quote_item["id"],)); paid=Decimal(cur.fetchone()[0] or 0)
    final=_money_decimal((quote_item.get("pricing") or {}).get("final_price")); deposit=_money_decimal((quote_item.get("pricing") or {}).get("deposit_amount"))
    return paid,final,deposit


def _v43_deposit_paid_locked(cur,quote_item):
    cur.execute("SELECT COALESCE(SUM(amount),0) FROM project_payments WHERE quotation_id=%s AND stage='DEPOSIT'",(quote_item["id"],))
    return Decimal((cur.fetchone() or [0])[0] or 0)


def _admin_project_quotation_issue_v43(project_id):
    validate_csrf()
    if request.form.get("confirm_issue")!="1": abort(400)
    project=_get_project_by_id(project_id)
    if not project: abort(404)
    costing=_costing_view(_get_project_costing(project))
    if costing.get("status")!="APPROVED_FOR_QUOTE" or not costing.get("quote_reference"):
        return redirect(url_for("admin_project_costing",project_id=project_id))
    try: valid_days=max(1,min(int(request.form.get("valid_days") or 14),60)); snapshot=_quotation_snapshot(project,costing)
    except (ValueError,TypeError) as exc: abort(400,description=str(exc))
    public_token=secrets.token_urlsafe(32)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,))
            cur.execute("SELECT id FROM project_quotations WHERE project_id=%s AND quote_reference=%s",(project_id,costing["quote_reference"])); existing=cur.fetchone()
            if existing:
                conn.commit(); return redirect(url_for("admin_project_quotation_detail",project_id=project_id,quotation_id=existing[0]))
            cur.execute("SELECT COALESCE(MAX(revision_no),0)+1 FROM project_quotations WHERE project_id=%s",(project_id,)); revision=int(cur.fetchone()[0] or 1)
            cur.execute("UPDATE project_quotations SET status='SUPERSEDED',updated_at=NOW() WHERE project_id=%s AND status IN ('ISSUED','VIEWED')",(project_id,))
            cur.execute("INSERT INTO project_quotations(project_id,quote_reference,revision_no,public_token,status,snapshot,issued_at,valid_until,updated_at) VALUES(%s,%s,%s,%s,'ISSUED',%s::jsonb,NOW(),NOW()+(%s*INTERVAL '1 day'),NOW()) RETURNING id",(project_id,costing["quote_reference"],revision,public_token,json.dumps(snapshot),valid_days)); qid=cur.fetchone()[0]
            _quote_event_insert(cur,qid,"ISSUED",f"Quotation issued by IBROWS with {valid_days}-day validity.")
            cur.execute("UPDATE project_assessments SET status='QUOTED',updated_at=NOW() WHERE id=%s",(project_id,)); _project_activity_insert(cur,project_id,"QUOTE_ISSUED",f"Quotation {costing['quote_reference']} issued as revision {revision}.")
        conn.commit()
    return redirect(url_for("admin_project_quotation_detail",project_id=project_id,quotation_id=qid))


def _public_project_quotation_v43(public_token):
    quote=_get_project_quotation_by_token(public_token)
    if not quote: abort(404)
    if quote.get("status") in {"ISSUED","VIEWED"} and quote.get("valid_until") and quote["valid_until"] <= datetime.now(UTC_TIMEZONE):
        quote=dict(quote); quote["status"]="EXPIRED"; quote["status_label"]=PROJECT_QUOTE_STATUSES["EXPIRED"]
    response_nonce=secrets.token_urlsafe(20); session[f"quote_response_nonce_{quote['id']}"]=response_nonce
    return render_template_string(PROJECT_QUOTATION_PUBLIC_TEMPLATE,quote=quote,preview_only=False,response_nonce=response_nonce,pdf_url=url_for("public_project_quotation_pdf",public_token=public_token),commercial_state=_project_commercial_state(quote["project_id"],quote,sync=False) if quote.get("status")=="ACCEPTED" else None,deposit_invoice_url=(url_for("public_project_deposit_invoice_pdf",public_token=public_token) if quote.get("status")=="ACCEPTED" else "")),200


def _public_project_quotation_respond_v43(public_token):
    quote=_get_project_quotation_by_token(public_token)
    if not quote: abort(404)
    nonce=str(request.form.get("response_nonce") or ""); expected=str(session.pop(f"quote_response_nonce_{quote['id']}","") or "")
    if not nonce or not expected or not hmac.compare_digest(nonce,expected): abort(400)
    if request.form.get("authorized")!="1": abort(400)
    decision=_project_clean(request.form.get("decision"),20).upper(); responded_by=_project_clean(request.form.get("responded_by"),160); response_note=_project_clean(request.form.get("response_note"),1200)
    if decision not in {"ACCEPTED","DECLINED"} or not responded_by: abort(400)
    conflict=False
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(quote["project_id"],))
            cur.execute(_quotation_select_sql()+" WHERE id=%s FOR UPDATE",(quote["id"],)); row=cur.fetchone()
            if not row: abort(404)
            current=_quotation_row_to_dict(row)
            if current.get("status") not in {"ISSUED","VIEWED"}: conn.commit(); return redirect(url_for("public_project_quotation",public_token=public_token))
            if current.get("valid_until") and current["valid_until"] <= datetime.now(UTC_TIMEZONE):
                cur.execute("UPDATE project_quotations SET status='EXPIRED',updated_at=NOW() WHERE id=%s",(current["id"],)); conn.commit(); return redirect(url_for("public_project_quotation",public_token=public_token))
            if decision=="ACCEPTED":
                cur.execute("SELECT id FROM project_quotations WHERE project_id=%s AND status='ACCEPTED' AND id<>%s FOR UPDATE",(current["project_id"],current["id"])); other=cur.fetchone()
                if other:
                    cur.execute("SELECT EXISTS(SELECT 1 FROM project_payments WHERE quotation_id=%s) OR EXISTS(SELECT 1 FROM project_execution WHERE quotation_id=%s)",(other[0],other[0])); busy=bool(cur.fetchone()[0])
                    if busy: conflict=True
                    else: cur.execute("UPDATE project_quotations SET status='SUPERSEDED',updated_at=NOW() WHERE id=%s",(other[0],))
                if not conflict:
                    cur.execute("UPDATE project_quotations SET status='SUPERSEDED',updated_at=NOW() WHERE project_id=%s AND id<>%s AND status IN ('ISSUED','VIEWED')",(current["project_id"],current["id"]))
                    cur.execute("UPDATE project_quotations SET status='ACCEPTED',responded_at=NOW(),responded_by=%s,response_note=NULLIF(%s,''),accepted_at=NOW(),updated_at=NOW() WHERE id=%s",(responded_by,response_note,current["id"]))
                    cur.execute("UPDATE project_assessments SET status='ACCEPTED',portal_token=COALESCE(portal_token,%s),updated_at=NOW() WHERE id=%s",(secrets.token_urlsafe(32),current["project_id"]))
                    current["status"]="ACCEPTED"
                    _v43_ensure_deposit_invoice_locked(cur,current)
                    _quote_event_insert(cur,current["id"],"ACCEPTED",f"Quotation accepted by {responded_by}. Acceptance does not record payment."); _project_activity_insert(cur,current["project_id"],"QUOTE_ACCEPTED",f"Quotation {current['quote_reference']} accepted by {responded_by}; awaiting payment/deposit confirmation.")
            else:
                cur.execute("UPDATE project_quotations SET status='DECLINED',responded_at=NOW(),responded_by=%s,response_note=NULLIF(%s,''),declined_at=NOW(),updated_at=NOW() WHERE id=%s",(responded_by,response_note,current["id"]))
                cur.execute("SELECT 1 FROM project_quotations WHERE project_id=%s AND status='ACCEPTED' LIMIT 1",(current["project_id"],)); has_accepted=cur.fetchone() is not None
                if not has_accepted: cur.execute("UPDATE project_assessments SET status='DECLINED',updated_at=NOW() WHERE id=%s",(current["project_id"],))
                _quote_event_insert(cur,current["id"],"DECLINED",f"Quotation declined by {responded_by}."); _project_activity_insert(cur,current["project_id"],"QUOTE_DECLINED",f"Quotation {current['quote_reference']} declined by {responded_by}.")
        if conflict:
            conn.rollback()
        else:
            conn.commit()
    if conflict:
        return Response("This project already has an accepted quotation with verified commercial activity. IBROWS must reconcile the revision before a replacement quotation can be accepted.",status=409,mimetype="text/plain")
    return redirect(url_for("public_project_quotation",public_token=public_token))

