def _v43_project_service_name(project_type):
    label=dict(PROJECT_TYPES).get(str(project_type or "").upper(),str(project_type or "Project").replace("_"," ").title())
    return f"Digital Project · {label}"


def get_service_profitability_data(period="month"):
    period=period if period in FINANCE_PERIODS else "month"; start_utc=_finance_period_start(period); services={}
    def bucket(name):
        name=canonicalize_service(name) if name else "General business"
        return services.setdefault(name,{"service":name,"revenue":{},"expenses":{},"net":{},"payment_count":0,"expense_count":0})
    with get_db() as conn:
        with conn.cursor() as cur:
            params=[]; sql="SELECT l.service,p.currency,COALESCE(SUM(p.amount),0),COUNT(p.id) FROM lead_payments p JOIN leads l ON l.id=p.lead_id WHERE l.merged_into_lead_id IS NULL"
            if start_utc is not None: sql+=" AND p.received_at>=%s"; params.append(start_utc)
            sql+=" GROUP BY l.service,p.currency"; cur.execute(sql,params); lead_rows=cur.fetchall()
            params=[]; sql="SELECT pa.project_type,pp.currency,COALESCE(SUM(pp.amount),0),COUNT(pp.id) FROM project_payments pp JOIN project_assessments pa ON pa.id=pp.project_id WHERE 1=1"
            if start_utc is not None: sql+=" AND pp.received_at>=%s"; params.append(start_utc)
            sql+=" GROUP BY pa.project_type,pp.currency"; cur.execute(sql,params); project_rows=cur.fetchall()
            params=[]; sql="SELECT service,currency,COALESCE(SUM(amount),0),COUNT(id) FROM business_expenses WHERE service IS NOT NULL AND BTRIM(service)<>''"
            if start_utc is not None: sql+=" AND expense_date>=%s"; params.append(start_utc)
            sql+=" GROUP BY service,currency"; cur.execute(sql,params); expenses=cur.fetchall()
            params=[]; sql="SELECT currency,COALESCE(SUM(amount),0),COUNT(id) FROM business_expenses WHERE service IS NULL OR BTRIM(service)=''"
            if start_utc is not None: sql+=" AND expense_date>=%s"; params.append(start_utc)
            sql+=" GROUP BY currency"; cur.execute(sql,params); overhead=cur.fetchall()
    for service,currency,total,count in lead_rows:
        b=bucket(service); b["revenue"][currency]=Decimal(total); b["payment_count"]+=int(count)
    for project_type,currency,total,count in project_rows:
        b=bucket(_v43_project_service_name(project_type)); b["revenue"][currency]=b["revenue"].get(currency,Decimal("0"))+Decimal(total); b["payment_count"]+=int(count)
    for service,currency,total,count in expenses:
        b=bucket(service); b["expenses"][currency]=Decimal(total); b["expense_count"]+=int(count)
    for currency,total,count in overhead:
        b=bucket(None); b["expenses"][currency]=Decimal(total); b["expense_count"]+=int(count)
    rows=[]
    for b in services.values():
        for c in set(b["revenue"])|set(b["expenses"]): b["net"][c]=b["revenue"].get(c,Decimal("0"))-b["expenses"].get(c,Decimal("0"))
        b["revenue_lines"]=_crm_amount_lines(b["revenue"]); b["expense_lines"]=_crm_amount_lines(b["expenses"]); b["net_lines"]=[{"currency":c,"amount":a,"label":_format_crm_amount(a,c)} for c,a in sorted(b["net"].items())]; rows.append(b)
    rows.sort(key=lambda x:(x["service"]=="General business",x["service"].lower())); return rows


def get_monthly_bookkeeping_history(limit_months=36):
    months={}
    def mb(dt):
        local=dt.astimezone(ADMIN_TIMEZONE); key=local.strftime("%Y-%m")
        return months.setdefault(key,{"key":key,"label":local.strftime("%B %Y"),"received":{},"expenses":{},"net":{},"payment_count":0,"expense_count":0,"services":{}})
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT p.amount,COALESCE(p.currency,'MWK'),p.received_at,l.service FROM lead_payments p JOIN leads l ON l.id=p.lead_id WHERE l.merged_into_lead_id IS NULL ORDER BY p.received_at DESC"); lead_rows=cur.fetchall()
            cur.execute("SELECT pp.amount,COALESCE(pp.currency,'MWK'),pp.received_at,pa.project_type FROM project_payments pp JOIN project_assessments pa ON pa.id=pp.project_id ORDER BY pp.received_at DESC"); project_rows=cur.fetchall()
            cur.execute("SELECT amount,COALESCE(currency,'MWK'),expense_date,service FROM business_expenses ORDER BY expense_date DESC"); expense_rows=cur.fetchall()
    def add_revenue(amount,currency,dt,service):
        b=mb(dt); amount=Decimal(amount); currency=currency or "MWK"; b["received"][currency]=b["received"].get(currency,Decimal("0"))+amount; b["payment_count"]+=1; sb=b["services"].setdefault(service,{"revenue":{},"expenses":{}}); sb["revenue"][currency]=sb["revenue"].get(currency,Decimal("0"))+amount
    for amount,currency,dt,service in lead_rows: add_revenue(amount,currency,dt,canonicalize_service(service) if service else "General business")
    for amount,currency,dt,ptype in project_rows: add_revenue(amount,currency,dt,_v43_project_service_name(ptype))
    for amount,currency,dt,service in expense_rows:
        b=mb(dt); amount=Decimal(amount); currency=currency or "MWK"; b["expenses"][currency]=b["expenses"].get(currency,Decimal("0"))+amount; b["expense_count"]+=1; name=canonicalize_service(service) if service else "General business"; sb=b["services"].setdefault(name,{"revenue":{},"expenses":{}}); sb["expenses"][currency]=sb["expenses"].get(currency,Decimal("0"))+amount
    rows=[]
    for key in sorted(months,reverse=True)[:max(1,int(limit_months))]:
        b=months[key]; currencies=set(b["received"])|set(b["expenses"])
        for c in currencies: b["net"][c]=b["received"].get(c,Decimal("0"))-b["expenses"].get(c,Decimal("0"))
        b["received_lines"]=_crm_amount_lines(b["received"]); b["expense_lines"]=_crm_amount_lines(b["expenses"]); b["net_lines"]=[{"currency":c,"amount":a,"label":_format_crm_amount(a,c)} for c,a in sorted(b["net"].items())]
        sr=[]
        for name,sb in sorted(b["services"].items()):
            net={c:sb["revenue"].get(c,Decimal("0"))-sb["expenses"].get(c,Decimal("0")) for c in set(sb["revenue"])|set(sb["expenses"])}; sr.append({"service":name,"revenue_lines":_crm_amount_lines(sb["revenue"]),"expense_lines":_crm_amount_lines(sb["expenses"]),"net_lines":[{"currency":c,"amount":a,"label":_format_crm_amount(a,c)} for c,a in sorted(net.items())]})
        b["service_rows"]=sr; rows.append(b)
    return rows


def get_budget_dashboard_data(year=None,month=None):
    now=datetime.now(ADMIN_TIMEZONE)
    try: year=int(year or now.year)
    except Exception: year=now.year
    try: month=int(month or now.month)
    except Exception: month=now.month
    if month<1 or month>12: month=now.month
    start_local=datetime(year,month,1,tzinfo=ADMIN_TIMEZONE); end_local=datetime(year+1,1,1,tzinfo=ADMIN_TIMEZONE) if month==12 else datetime(year,month+1,1,tzinfo=ADMIN_TIMEZONE); start_utc,end_utc=start_local.astimezone(UTC_TIMEZONE),end_local.astimezone(UTC_TIMEZONE)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id,budget_year,budget_month,amount,currency,category,COALESCE(service,'') FROM business_expense_budgets WHERE budget_year=%s AND budget_month=%s ORDER BY currency,category,service",(year,month)); budgets=cur.fetchall()
            cur.execute("SELECT COALESCE(currency,'MWK'),category,COALESCE(service,''),SUM(amount) FROM business_expenses WHERE expense_date>=%s AND expense_date<%s GROUP BY COALESCE(currency,'MWK'),category,COALESCE(service,'')",(start_utc,end_utc)); actuals=cur.fetchall()
    actual_map={(c or "MWK",(cat or "OTHER").upper(),svc or ""):Decimal(total or 0) for c,cat,svc,total in actuals}; rows=[]
    for bid,by,bm,amount,currency,category,service in budgets:
        amount=Decimal(amount or 0); currency=currency or "MWK"; category=(category or "OTHER").upper(); service=service or ""; spent=actual_map.get((currency,category,service),Decimal("0")) if service else sum((v for (c,cat,svc),v in actual_map.items() if c==currency and cat==category),Decimal("0")); remaining=amount-spent; pct=float((spent/amount*100) if amount else 0); state="Over budget" if spent>amount else ("Near limit" if pct>=80 else "On track"); rows.append({"id":bid,"amount":amount,"currency":currency,"category":category.title(),"category_code":category,"service":service or "General business","service_value":service,"spent":spent,"remaining":remaining,"percent":min(pct,100.0),"raw_percent":pct,"state":state})
    totals={}
    grouped={}
    for r in rows: grouped.setdefault((r["currency"],r["category_code"]),[]).append(r)
    for (currency,category),items in grouped.items():
        general=next((x for x in items if not x["service_value"]),None)
        t=totals.setdefault(currency,{"budget":Decimal("0"),"spent":Decimal("0")})
        if general:
            t["budget"]+=general["amount"]; t["spent"]+=general["spent"]
        else:
            t["budget"]+=sum((x["amount"] for x in items),Decimal("0")); t["spent"]+=sum((x["spent"] for x in items),Decimal("0"))
    total_rows=[{"currency":c,"budget":t["budget"],"spent":t["spent"],"remaining":t["budget"]-t["spent"]} for c,t in sorted(totals.items())]
    return {"year":year,"month":month,"month_label":start_local.strftime("%B %Y"),"rows":rows,"totals":total_rows}


def get_accounts_receivable_data(status_filter="all"):
    status_filter=status_filter if status_filter in RECEIVABLE_FILTERS else "all"; base=_V42_GET_ACCOUNTS_RECEIVABLE("all"); invoices=list(base["invoices"]); today=datetime.now(ADMIN_TIMEZONE).date()
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT 'DEPOSIT',pi.id,pi.project_id,pi.quotation_id,NULL,pi.invoice_number,pi.amount,pi.currency,pi.issued_at,
                       pa.contact_name,pa.organisation,pa.project_type,COALESCE(SUM(pp.amount),0)
                FROM project_invoices pi JOIN project_assessments pa ON pa.id=pi.project_id
                LEFT JOIN project_payments pp ON pp.quotation_id=pi.quotation_id
                WHERE pi.status<>'VOID'
                GROUP BY pi.id,pa.contact_name,pa.organisation,pa.project_type
                UNION ALL
                SELECT 'STAGE',si.id,si.project_id,si.quotation_id,si.stage,si.invoice_number,si.amount,si.currency,si.issued_at,
                       pa.contact_name,pa.organisation,pa.project_type,COALESCE(SUM(pp.amount),0)
                FROM project_stage_invoices si JOIN project_assessments pa ON pa.id=si.project_id
                LEFT JOIN project_payments pp ON pp.quotation_id=si.quotation_id AND pp.stage=si.stage
                WHERE si.status<>'VOID'
                GROUP BY si.id,pa.contact_name,pa.organisation,pa.project_type
                ORDER BY 9 DESC
            """); prows=cur.fetchall()
    for kind,doc_id,project_id,qid,stage,number,amount,currency,issued_at,contact,org,ptype,paid in prows:
        amount=Decimal(amount or 0); paid=min(Decimal(paid or 0),amount); balance=max(amount-paid,Decimal("0")); issued_local=issued_at.astimezone(ADMIN_TIMEZONE); due_local=issued_local+timedelta(days=BUSINESS_INVOICE_DUE_DAYS); days=(due_local.date()-today).days
        if balance<=0 and amount>0: sk,sl,urg,pstat="paid","Paid","Paid in full","Paid"
        else:
            pstat="Part paid" if paid>0 else "Not paid"
            if days<0: sk,sl,urg="overdue","Overdue",f"Overdue by {abs(days)} day{'' if abs(days)==1 else 's'}"
            elif days<=RECEIVABLE_DUE_SOON_DAYS: sk,sl,urg="due_soon","Due soon",("Due today" if days==0 else "Due tomorrow" if days==1 else f"Due in {days} days")
            else: sk,sl,urg="open","Open",f"Due in {days} days"
        invoices.append({"document_id":doc_id,"lead_id":None,"project_id":project_id,"stage":stage,"invoice_kind":kind,"document_number":number,"customer_number":"","customer_name":org or contact or "Project client","service":_v43_project_service_name(ptype),"issued_at":issued_at,"issued_label":issued_local.strftime("%d %b %Y"),"due_label":due_local.strftime("%d %b %Y"),"estimated_value":amount,"value_label":_format_crm_amount(amount,currency),"paid_total":paid,"paid_label":_format_crm_amount(paid,currency),"balance":balance,"balance_label":_format_crm_amount(balance,currency),"currency":currency,"status_key":sk,"status_label":sl,"urgency_label":urg,"payment_status":pstat,"send_count":0,"sent_label":"Project invoice · client portal","due_soon_notified_at":None,"overdue_notified_at":None,"admin_reminder_label":""})
    priority={"overdue":0,"due_soon":1,"open":2,"paid":3}; invoices.sort(key=lambda x:(priority.get(x["status_key"],9),x["issued_at"])); visible=invoices if status_filter=="all" else [x for x in invoices if x["status_key"]==status_filter]
    outstanding={}; overdue={}; due_soon={}; counts={"open":0,"due_soon":0,"overdue":0,"paid":0}
    for inv in invoices:
        counts[inv["status_key"]]+=1
        if inv["balance"]>0:
            c=inv["currency"]; outstanding[c]=outstanding.get(c,Decimal("0"))+inv["balance"]
            if inv["status_key"]=="overdue": overdue[c]=overdue.get(c,Decimal("0"))+inv["balance"]
            if inv["status_key"]=="due_soon": due_soon[c]=due_soon.get(c,Decimal("0"))+inv["balance"]
    return {"filter":status_filter,"filter_label":RECEIVABLE_FILTERS[status_filter],"invoices":visible,"invoice_count":len(invoices),"visible_count":len(visible),"outstanding":_crm_amount_lines(outstanding),"overdue":_crm_amount_lines(overdue),"due_soon":_crm_amount_lines(due_soon),"status_counts":counts}

