def _admin_finance_export_csv_v43():
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT p.id,p.lead_id,l.customer_name,l.customer_number,l.service,p.amount,COALESCE(p.currency,'MWK'),p.payment_method,p.reference,p.payment_note,p.received_at FROM lead_payments p JOIN leads l ON l.id=p.lead_id WHERE l.merged_into_lead_id IS NULL ORDER BY p.received_at,p.id"); payments=cur.fetchall()
            cur.execute("SELECT v.original_payment_id,v.lead_id,COALESCE(l.customer_name,'Customer'),COALESCE(l.customer_number,''),COALESCE(l.service,'General Enquiry'),v.amount,COALESCE(v.currency,'MWK'),v.payment_method,v.reference,v.payment_note,v.original_received_at,v.void_reason,v.voided_at FROM payment_void_audit v LEFT JOIN leads l ON l.id=v.lead_id ORDER BY v.voided_at,v.id"); voided=cur.fetchall()
            cur.execute("SELECT pp.id,pp.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),pa.project_type,pq.quote_reference,pp.stage,pp.amount,pp.currency,pp.payment_method,pp.reference,pp.payment_note,pp.received_at FROM project_payments pp JOIN project_assessments pa ON pa.id=pp.project_id JOIN project_quotations pq ON pq.id=pp.quotation_id ORDER BY pp.received_at,pp.id"); project_payments=cur.fetchall()
            cur.execute("SELECT v.original_payment_id,v.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),pq.quote_reference,v.stage,v.amount,v.currency,v.payment_method,v.reference,v.payment_note,v.original_received_at,v.void_reason,v.voided_at FROM project_payment_void_audit v JOIN project_assessments pa ON pa.id=v.project_id JOIN project_quotations pq ON pq.id=v.quotation_id ORDER BY v.voided_at,v.id"); project_voids=cur.fetchall()
            cur.execute("SELECT id,amount,COALESCE(currency,'MWK'),category,service,description,payment_method,reference,expense_date FROM business_expenses ORDER BY expense_date,id"); expenses=cur.fetchall()
            cur.execute("SELECT original_expense_id,amount,currency,category,service,description,payment_method,reference,original_expense_date,void_reason,voided_at FROM business_expense_void_audit ORDER BY voided_at,id"); expense_voids=cur.fetchall()
            cur.execute("SELECT pi.id,pi.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),pi.invoice_number,pi.invoice_type,pi.amount,pi.currency,pi.status,pi.issued_at,pi.paid_at FROM project_invoices pi JOIN project_assessments pa ON pa.id=pi.project_id UNION ALL SELECT si.id,si.project_id,pa.reference,COALESCE(pa.organisation,pa.contact_name),si.invoice_number,si.stage,si.amount,si.currency,si.status,si.issued_at,si.paid_at FROM project_stage_invoices si JOIN project_assessments pa ON pa.id=si.project_id ORDER BY 10,1"); project_invoices=cur.fetchall()
    files={
        "payments.csv":_csv_text(["payment_id","lead_id","customer_name","customer_number","service","amount","currency","payment_method","reference","note","received_at_malawi"],[list(r[:10])+[_export_local_datetime(r[10])] for r in payments]),
        "voided_payments.csv":_csv_text(["original_payment_id","lead_id","customer_name","customer_number","service","amount","currency","payment_method","reference","note","original_received_at_malawi","void_reason","voided_at_malawi"],[list(r[:10])+[_export_local_datetime(r[10]),r[11],_export_local_datetime(r[12])] for r in voided]),
        "project_payments.csv":_csv_text(["payment_id","project_id","project_reference","client","project_type","quotation_reference","stage","amount","currency","payment_method","reference","note","received_at_malawi"],[list(r[:12])+[_export_local_datetime(r[12])] for r in project_payments]),
        "project_voided_payments.csv":_csv_text(["original_payment_id","project_id","project_reference","client","quotation_reference","stage","amount","currency","payment_method","reference","note","original_received_at_malawi","void_reason","voided_at_malawi"],[list(r[:11])+[_export_local_datetime(r[11]),r[12],_export_local_datetime(r[13])] for r in project_voids]),
        "project_invoices.csv":_csv_text(["invoice_id","project_id","project_reference","client","invoice_number","invoice_type_or_stage","amount","currency","status","issued_at_malawi","paid_at_malawi"],[list(r[:9])+[_export_local_datetime(r[9]),_export_local_datetime(r[10])] for r in project_invoices]),
        "expenses.csv":_csv_text(["expense_id","amount","currency","category","related_service","description","payment_method","reference","expense_date_malawi"],[list(r[:8])+[_export_local_datetime(r[8])] for r in expenses]),
        "voided_expenses.csv":_csv_text(["original_expense_id","amount","currency","category","related_service","description","payment_method","reference","original_expense_date_malawi","void_reason","voided_at_malawi"],[list(r[:8])+[_export_local_datetime(r[8]),r[9],_export_local_datetime(r[10])] for r in expense_voids]),
    }
    monthly=[]; service_monthly=[]
    for month in get_monthly_bookkeeping_history(36):
        for c in sorted(set(month.get("received",{}))|set(month.get("expenses",{}))): monthly.append([month["key"],month["label"],c,month["received"].get(c,Decimal("0")),month["expenses"].get(c,Decimal("0")),month["net"].get(c,Decimal("0")),month["payment_count"],month["expense_count"]])
        for svc in month.get("service_rows",[]):
            rev={x["currency"]:x["amount"] for x in svc.get("revenue_lines",[])}; exp={x["currency"]:x["amount"] for x in svc.get("expense_lines",[])}; net={x["currency"]:x["amount"] for x in svc.get("net_lines",[])}
            for c in sorted(set(rev)|set(exp)|set(net)): service_monthly.append([month["key"],month["label"],svc["service"],c,rev.get(c,0),exp.get(c,0),net.get(c,0)])
    files["monthly_summary.csv"]=_csv_text(["month","month_label","currency","payments_received","business_expenses","net_cash","payment_count","expense_count"],monthly); files["monthly_service_summary.csv"]=_csv_text(["month","month_label","service","currency","payments_received","assigned_expenses","net_cash_contribution"],service_monthly)
    memory=io.BytesIO();
    with zipfile.ZipFile(memory,"w",compression=zipfile.ZIP_DEFLATED) as archive:
        for name,data in files.items(): archive.writestr(name,data)
    stamp=datetime.now(ADMIN_TIMEZONE).strftime("%Y-%m-%d"); response=Response(memory.getvalue(),mimetype="application/zip"); response.headers["Content-Disposition"]=f'attachment; filename="IBROWS_Finance_Export_{stamp}.zip"'; response.headers["Cache-Control"]="no-store"; return response

