def delete_project_assessment_data(project_id):
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM project_assessments WHERE id=%s FOR UPDATE",(project_id,)); row=cur.fetchone()
            if not row: raise ValueError("Project not found")
            cur.execute("SELECT EXISTS(SELECT 1 FROM project_quotations WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_payments WHERE project_id=%s) OR EXISTS(SELECT 1 FROM project_execution WHERE project_id=%s)",(project_id,project_id,project_id)); commercial=bool(cur.fetchone()[0])
            if not commercial:
                cur.execute("DELETE FROM project_assessments WHERE id=%s",(project_id,)); action="deleted"
            else:
                cur.execute("DELETE FROM project_notes WHERE project_id=%s",(project_id,)); cur.execute("UPDATE project_assessments SET contact_name='Deleted customer',organisation=NULL,phone=NULL,email=NULL,answers='{}'::jsonb,ai_summary='Personal discovery data deleted; commercial record retained.',ai_required_features='[]'::jsonb,ai_recommended_features='[]'::jsonb,ai_future_enhancements='[]'::jsonb,ai_missing_information='[]'::jsonb,ai_risk_flags='[]'::jsonb,ai_cost_drivers='[]'::jsonb,ai_scope_reducers='[]'::jsonb,portal_token=NULL,alert_last_error=NULL,updated_at=NOW() WHERE id=%s",(project_id,)); cur.execute("SELECT id FROM project_quotations WHERE project_id=%s",(project_id,))
                for (qid,) in cur.fetchall(): cur.execute("UPDATE project_quotations SET public_token=%s,updated_at=NOW() WHERE id=%s",(secrets.token_urlsafe(32),qid))
                action="anonymized"
        conn.commit()
    return action

